package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.BinaryResourceScanner;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.google.common.collect.ImmutableSet;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;

public class IconDetector extends ResourceXmlDetector implements BinaryResourceScanner {
    private static final String WEBP_FILE_EXTENSION = "webp";
    private static final String PNG_FILE_EXTENSION = "png";
    private static final String JPEG_FILE_EXTENSION = "jpeg";
    private static final String JPG_FILE_EXTENSION = "jpg";
    private static final String BMP_FILE_EXTENSION = "bmp";
    private static final String GIF_FILE_EXTENSION = "gif";

    public static final Issue CONVERT_TO_WEBP = Issue.create(
            "ConvertToWebp",
            "Convert to WebP",
            "The WebP format is typically more compact than PNG and JPEG. As of Android 4.2.1 "
                    + "it supports transparency and lossless conversion as well. Note that there is a "
                    + "quickfix in the IDE which lets you perform conversion.\n\n"
                    + "Previously, launcher icons were required to be in the PNG format but that "
                    + "restriction is no longer there, so lint now flags these.",
            Category.USABILITY,
            5,
            Severity.WARNING,
            new Implementation(IconDetector.class,
                    Scope.BINARY_RESOURCE_FILE_SCOPE))
            .setEnabledByDefault(true)
            .setVendor("Android Lint");

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE
                || folderType == ResourceFolderType.MIPMAP;
    }

    @Override
    public void checkBinaryResource(@NonNull Context context) {
        String extension = context.file.getName();
        int dot = extension.lastIndexOf('.');
        if (dot == -1) {
            return;
        }
        extension = extension.substring(dot + 1).toLowerCase();

        if (extension.equals(PNG_FILE_EXTENSION)
                || extension.equals(JPEG_FILE_EXTENSION)
                || extension.equals(JPG_FILE_EXTENSION)
                || extension.equals(BMP_FILE_EXTENSION)
                || extension.equals(GIF_FILE_EXTENSION)) {
            Location location = Location.create(context.file);
            String message = String.format(
                    "Convert `%1$s` to WebP format", context.file.getName());
            context.report(CONVERT_TO_WEBP, location, message);
        }
    }
}
```

