private final Set<File> mProcessedParents = new HashSet<>();

@Override
public void checkFolder(@NonNull Context context, @NonNull File folder) {
    File parent = folder.getParentFile();
    if (parent == null || !mProcessedParents.add(parent)) {
        return;
    }

    String folderName = folder.getName();
    ResourceFolderType folderType = ResourceFolderType.getFolderType(folderName);
    if (folderType != ResourceFolderType.DRAWABLE && folderType != ResourceFolderType.MIPMAP) {
        return;
    }

    String prefix = folderType == ResourceFolderType.DRAWABLE ? "drawable" : "mipmap";
    File[] subFolders = parent.listFiles();
    if (subFolders == null) {
        return;
    }

    Map<String, List<File>> baseNames = new HashMap<>();
    Map<String, EnumSet<Density>> densities = new HashMap<>();

    for (File subFolder : subFolders) {
        String name = subFolder.getName();
        if (!name.startsWith(prefix)) {
            continue;
        }
        Density density = getDensity(name);
        if (density == null) {
            continue;
        }
        File[] files = subFolder.listFiles();
        if (files == null) {
            continue;
        }
        for (File file : files) {
            String fileName = file.getName();
            String baseName = getBaseName(fileName);
            if (baseName == null) {
                continue;
            }
            densities.computeIfAbsent(baseName, k -> EnumSet.noneOf(Density.class)).add(density);
            baseNames.computeIfAbsent(baseName, k -> new ArrayList<>()).add(file);
        }
    }

    EnumSet<Density> required = EnumSet.of(Density.MEDIUM, Density.HIGH, Density.XHIGH);
    if (INCLUDE_LDPI) {
        required.add(Density.LOW);
    }

    for (Map.Entry<String, EnumSet<Density>> entry : densities.entrySet()) {
        EnumSet<Density> present = entry.getValue();
        if (present.containsAll(required)) {
            continue;
        }
        EnumSet<Density> missing = EnumSet.copyOf(required);
        missing.removeAll(present);
        List<File> files = baseNames.get(entry.getKey());
        File first = files.get(0);
        Location location = Location.create(first);
        String message = String.format(
                "The icon %s is missing density %s",
                entry.getKey(),
                missing.toString().toLowerCase(Locale.US));
        context.report(ISSUE, location, message);
    }
}
```

