private static String getDensityQualifier(String folderName, ResourceFolderType type) {
    String prefix = type.getName() + "-";
    if (!folderName.startsWith(prefix)) return null;
    String[] parts = folderName.substring(prefix.length()).split("-");
    for (String part : parts) {
        if (part.equals("anydpi") || part.equals("nodpi")) {
            return "any";
        }
        Density d = Density.getEnum(part);
        if (d != null) {
            return part;
        }
    }
    return null;
}
```
