            }

            String key = folderType.getName() + "/" + name;
            if (isWildcard) {
                mWildcardIcons.add(key);
                continue;
            }

            Map<String, File> densityMap = mIcons.get(key);
            if (densityMap == null) {
                densityMap = new HashMap<>();
                mIcons.put(key, densityMap);
            }
            densityMap.put(density, file);
