    private static String getDensityQualifier(File folder, ResourceFolderType folderType) {
        String folderName = folder.getName();
        String prefix = folderType.getName() + "-";
        if (!folderName.startsWith(prefix)) {
            return null;
        }

        String[] qualifiers = folderName.substring(prefix.length()).split("-");
        for (String qualifier : qualifiers) {
            if ("anydpi".equals(qualifier) || "nodpi".equals(qualifier)) {
                return "any";
            }

            Density density = Density.getEnum(qualifier);
            if (density != null) {
                return qualifier;
            }
        }

        return null;
    }

    private static boolean isImageFile(String name) {
        String lower = name.toLowerCase(Locale.US);
        return lower.endsWith(".png") || lower.endsWith(".webp") || lower.endsWith(".jpg")
                || lower.endsWith(".jpeg") || lower.endsWith(".gif") || lower.endsWith(".9.png");
    }

    private static String join(List<String> list) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(list.get(i));
        }
        return sb.toString();
    }
