```java
package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.Density;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceContext;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;

import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.Collections;
import java.util.List;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;

public class IconDetector extends Detector implements Detector.ResourceFolderScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            IconDetector.class,
            Scope.RESOURCE_FOLDER_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "IconExpectedSize",
            "Icon has incorrect size",
            "There are predefined sizes (for each density) for launcher icons. You should follow " +
            "these conventions to make sure your icons fit in with the overall look of the platform.",
            Category.ICONS,
            5,
            Severity.WARNING,
            IMPLEMENTATION);

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.MIPMAP || folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public void checkResourceFolder(@NonNull ResourceContext context) {
        File folder = context.getFile();
        String folderName = folder.getName();
        Density density = Density.getEnum(folderName);
        if (density == null) {
            // Try to parse density qualifier
            density = parseDensity(folderName);
        }
        if (density == null) {
            return;
        }

        int expectedSize = getExpectedLauncherIconSize(density);
        if (expectedSize <= 0) {
            return;
        }

        File[] files = folder.listFiles();
        if (files == null) {
            return;
        }

        for (File file : files) {
            if (!isImage(file)) {
                continue;
            }
            if (!isLauncherIcon(file.getName())) {
                continue;
            }

            int[] dimensions = getImageDimensions(file);
            if (dimensions == null) {
                continue;
            }

            int width = dimensions[0];
            int height = dimensions[1];
            if (width != expectedSize || height != expectedSize) {
                String message = String.format(
                        "The image `%1$s` has dimensions %2$dx%3$d, but the expected dimension for a %4$s launcher icon is %5$dx%5$d",
                        file.getName(), width, height, density.getResourceValue(), expectedSize);
                Location location = Location.create(file);
                context.report(ISSUE, location, message);
            }
        }
    }

    private static Density parseDensity(String folderName) {
        // folder names like mipmap-mdpi, drawable-hdpi, etc.
        int index = folderName.lastIndexOf('-');
        if (index == -1) {
            return Density.MEDIUM;
        }
        String qualifier = folderName.substring(index + 1);
        return Density.getEnum(qualifier);
    }

    private static int getExpectedLauncherIconSize(@NonNull Density density) {
        switch (density) {
            case LOW: return 36;
            case MEDIUM: return 48;
            case HIGH: return 72;
            case XHIGH: return 96;
            case XXHIGH: return 144;
            case XXXHIGH: return 192;
            case TV: return 64;
            default: return 48;
        }
    }

    private static boolean isImage(@NonNull File file) {
        String name = file.getName().toLowerCase();
        return name.endsWith(".png") || name.endsWith(".jpg") || name.endsWith(".jpeg") || name.endsWith(".gif") || name.endsWith(".webp");
    }

    private static boolean isLauncherIcon(@NonNull String name) {
        String base = name.toLowerCase();
        if (base.contains(".")) {
            base = base.substring(0, base.lastIndexOf('.'));
        }
        return base.equals("ic_launcher") || base.equals("ic_launcher_round") || base.contains("launcher");
    }

    @Nullable
    private static int[] getImageDimensions(@NonNull File file) {
        try {
            BufferedImage image = ImageIO.read(file);
            if (image != null) {
                return new int[] { image.getWidth(), image.getHeight() };
            }
        } catch (IOException e) {
            // ignore
        }
        return null;
    }
}
```

