private static int[] getImageSize(File file) throws IOException {
    try (InputStream is = new BufferedInputStream(new FileInputStream(file))) {
        byte[] sig = new byte[8];
        if (is.read(sig) != 8 || !isPngSignature(sig)) return null;
        while (true) {
            int length = readInt(is);
            byte[] type = new byte[4];
            if (is.read(type) != 4) return null;
            if (type[0]=='I' && type[1]=='H' && type[2]=='D' && type[3]=='R') {
                int w = readInt(is);
                int h = readInt(is);
                return new int[]{w,h};
            }
            // skip data + crc
            long skipped = is.skip(length + 4);
            if (skipped != length + 4) return null;
        }
    }
}
