package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.ide.common.resources.configuration.Density;
import com.android.ide.common.resources.configuration.FolderConfiguration;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceContext;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;

import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;

public class IconDetector extends Detector implements Detector.BinaryResourceScanner {

    private static final Implementation IMPLEMENTATION = new Implementation(
            IconDetector.class,
            Scope.BINARY_RESOURCE_FILE_SCOPE);

    public static final Issue ICON_EXPECTED_SIZE = Issue.create(
            "IconExpectedSize",
            "Icon has incorrect size",
            "There are predefined sizes (for each density) for launcher icons. You should follow " +
            "these conventions to make sure your icons fit in with the overall look of the platform.",
            Category.ICONS,
            5,
            Severity.WARNING,
            IMPLEMENTATION)
            .addMoreInfo("https://developer.android.com/guide/practices/ui_guidelines/icon_design_launcher.html");

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.MIPMAP;
    }

    @Override
    public void checkBinaryResource(@NonNull ResourceContext context) {
        FolderConfiguration config = context.getFolderConfiguration();
        if (config == null) {
            return;
        }
        Density density = config.getDensityQualifier().getValue(); // Need check method
        if (density == null || density == Density.NODPI || density == Density.ANYDPI) {
            return;
        }

        int dpi = density.getDpiValue();
        if (dpi <= 0) {
            return;
        }

        BufferedImage image = context.getImage();
        if (image == null) {
            return;
        }
        int width = image.getWidth();
        int height = image.getHeight();

        int expected = Math.round(48f * dpi / Density.MEDIUM.getDpiValue());
        if (width != expected || height != expected) {
            String message = String.format(
                    "The image %1$s has size %2$dx%3$d pixels, but it should be %4$dx%4$d pixels for density %5$s",
                    context.file.getName(), width, height, expected, density.getResourceValue());
            context.report(ICON_EXPECTED_SIZE, Location.create(context.file), message);
        }
    }
}
```

