@Nullable
private static int[] readWebpDimensions(byte[] header, InputStream stream) throws IOException {
    // VP8 simple chunk at offset 12: "VP8 " then 4 bytes length, then frame tag
    // Actually offset 12 is chunk fourcc, offset 16 is chunk size
    String chunk = new String(header, 12, 4, US_ASCII);
    if ("VP8 ".equals(chunk)) {
        // Read 10 more bytes for frame tag
        byte[] frame = new byte[10];
        int r = stream.read(frame);
        if (r < 10) return null;
        int b0 = frame[3] & 0xFF;
        int b1 = frame[4] & 0xFF;
        int b2 = frame[5] & 0xFF;
        int width = (b0 | (b1 << 8)) & 0x3FFF;
        int height = ((b1 >> 6) | (b2 << 2)) & 0x3FFF;
        return new int[] {width, height};
    } else if ("VP8L".equals(chunk)) {
        byte[] buf = new byte[5];
        int r = stream.read(buf);
        if (r < 5) return null;
        int b0 = buf[0] & 0xFF;
        int b1 = buf[1] & 0xFF;
        int b2 = buf[2] & 0xFF;
        int b3 = buf[3] & 0xFF;
        int bits = b0 | (b1 << 8) | (b2 << 16) | (b3 << 24);
        int width = (bits & 0x3FFF) + 1;
        int height = ((bits >> 14) & 0x3FFF) + 1;
        return new int[] {width, height};
    }
    return null;
}
