private static String detectFormat(File file) {
    byte[] header = new byte[12];
    try (InputStream is = new BufferedInputStream(new FileInputStream(file))) {
        int read = is.read(header);
        if (read < 4) return null;
        if (isPng(header, read)) return "png";
        if (isGif(header, read)) return "gif";
        if (isJpeg(header, read)) return "jpg";
        if (isWebp(header, read)) return "webp";
        if (isXml(file)) return "xml";
        if (isBmp(header, read)) return "bmp";
    } catch (IOException e) {
        // ignore
    }
    return null;
}
