package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceFolderDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.EnumSet;

public class IconDetector extends ResourceFolderDetector {
    public static final Issue ISSUE = Issue.create(
        "IconExtension",
        "Icon format does not match the file extension",
        "Icons should use a file extension that matches their actual image format. ...",
        Category.ICONS,
        5,
        Severity.WARNING,
        new Implementation(IconDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE || folderType == ResourceFolderType.MIPMAP;
    }

    @Override
    public void checkFile(@NonNull Context context, @NonNull File file) {
        String name = file.getName();
        if (name.startsWith(".")) return;

        String extension = getExtension(name).toLowerCase();
        if (extension.isEmpty()) return;

        // Only check known image formats
        switch (extension) {
            case "png":
            case "gif":
            case "jpg":
            case "jpeg":
            case "webp":
            case "xml":
                break;
            default:
                return;
        }

        String detected = detectFormat(file);
        if (detected == null) return;

        if (!extensionMatches(detected, extension)) {
            String message = String.format(
                "The file extension `.%1$s` does not match the file's format (%2$s)",
                extension, detected.toUpperCase()
            );
            context.report(ISSUE, Location.create(file), message);
        }
    }

    private static String getExtension(String filename) {
        int dot = filename.lastIndexOf('.');
        if (dot <= 0 || dot == filename.length() - 1) return "";
        return filename.substring(dot + 1);
    }

    private static boolean extensionMatches(String detected, String extension) {
        switch (detected) {
            case "png": return extension.equals("png") || extension.equals("9.png")? Wait.
            case "gif": return extension.equals("gif");
            case "jpeg": return extension.equals("jpg") || extension.equals("jpeg");
            case "webp": return extension.equals("webp");
            case "xml": return extension.equals("xml");
            default: return false;
        }
    }

    private static String detectFormat(File file) {
        byte[] header = new byte[12];
        try (FileInputStream fis = new FileInputStream(file)) {
            int read = fis.read(header);
            if (read < 4) return null;
        } catch (IOException e) {
            return null;
        }

        if (header[0] == (byte)0x89 && header[1] == 'P' && header[2] == 'N' && header[3] == 'G'
                && header[4] == 0x0D && header[5] == 0x0A && header[6] == 0x1A && header[7] == 0x0A) {
            return "png";
        }
        if (header[0] == 'G' && header[1] == 'I' && header[2] == 'F' && header[3] == '8'
                && (header[4] == '7' || header[4] == '9') && header[5] == 'a') {
            return "gif";
        }
        if (header[0] == (byte)0xFF && header[1] == (byte)0xD8 && header[2] == (byte)0xFF) {
            return "jpeg";
        }
        if (header[0] == 'R' && header[1] == 'I' && header[2] == 'F' && header[3] == 'F' && read >= 12) {
            // bytes 8-11 = WEBP
            if (header[8] == 'W' && header[9] == 'E' && header[10] == 'B' && header[11] == 'P') {
                return "webp";
            }
        }
        // xml
        // skip whitespace
        try {
            String content = new String(header, java.nio.charset.StandardCharsets.UTF_8);
            if (content.trim().startsWith("<?xml") || content.trim().startsWith("<")) {
                return "xml";
            }
        } catch (Exception ignore) {}
        return null;
    }
}

