package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;

import java.io.File;
import java.util.Arrays;
import java.util.EnumSet;

public class IconDetector extends Detector implements Detector.BinaryFileScanner {

    public static final Issue ICON_EXTENSION = Issue.create(
            "IconExtension",
            "Icon format does not match the file extension",
            "Ensures that icons have the correct file extension (e.g. a `.png` file is really in the PNG format and not for example a GIF file named `.png`).",
            Category.ICONS,
            5,
            Severity.WARNING,
            new Implementation(IconDetector.class, Scope.BINARY_RESOURCE_FILE_SCOPE)
    );

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE || folderType == ResourceFolderType.MIPMAP;
    }

    @Override
    public void checkBinaryFile(@NonNull Context context, @NonNull File file, @NonNull byte[] content) {
        String name = file.getName();
        int dot = name.lastIndexOf('.');
        if (dot < 0) {
            return;
        }
        String extension = name.substring(dot + 1).toLowerCase();

        String actualFormat = detectFormat(content);
        if (actualFormat == null) {
            return;
        }

        if (!actualFormat.equals(extension)) {
            String message = String.format(
                    "The file extension `%s` does not match the actual file format `%s`",
                    extension, actualFormat);
            context.report(ICON_EXTENSION, Location.create(file), message);
        }
    }

    private String detectFormat(byte[] content) {
        if (content.length < 4) {
            return null;
        }
        if (content[0] == (byte) 0x89 && content[1] == (byte) 0x50
                && content[2] == (byte) 0x4E && content[3] == (byte) 0x47) {
            return "png";
        }
        if (content[0] == (byte) 0xFF && content[1] == (byte) 0xD8) {
            return "jpg"; // or jpeg
        }
        if (content[0] == (byte) 0x47 && content[1] == (byte) 0x49
                && content[2] == (byte) 0x46) {
            return "gif";
        }
        if (content[0] == (byte) 0x42 && content[1] == (byte) 0x4D) {
            return "bmp";
        }
        if (content[0] == (byte) 0x52 && content[1] == (byte) 0x49
                && content[2] == (byte) 0x46 && content[3] == (byte) 0x46) {
            return "webp"; // Actually RIFF could be other things; webp has WEBP at offset 8
        }
        // WebP refined
        if (content.length >= 12 && content[0] == (byte)0x52 && content[1] == (byte)0x49
                && content[2] == (byte)0x46 && content[3] == (byte)0x46
                && content[8] == (byte)0x57 && content[9] == (byte)0x45
                && content[10] == (byte)0x42 && content[11] == (byte)0x50) {
            return "webp";
        }
        // SVG starts with <?xml or <svg; but binary scanner won't get XML
        return null;
    }
}
```

