package com.android.tools.lint.checks;

import static com.android.SdkConstants.EXT_PNG;
import static com.android.SdkConstants.EXT_JPG;
import static com.android.SdkConstants.EXT_JPEG;
import static com.android.SdkConstants.EXT_GIF;
import static com.android.SdkConstants.EXT_WEBP;
import static com.android.SdkConstants.EXT_BMP;
import static com.android.SdkConstants.EXT_XML;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;

import java.io.File;
import java.util.EnumSet;

public class IconDetector extends Detector implements Detector.BinaryFileScanner {

    private static final String ISSUE_ID = "IconExtension";
    private static final String ISSUE_SUMMARY = "Icon format does not match the file extension";
    private static final String ISSUE_EXPLANATION =
            "Ensures that icons have the correct file extension (e.g. a `.png` file is really in the PNG format and not for example a GIF file named `.png`).";

    public static final Issue ICON_EXTENSION = Issue.create(
            ISSUE_ID,
            ISSUE_SUMMARY,
            ISSUE_EXPLANATION,
            Category.ICONS,
            5,
            Severity.WARNING,
            new Implementation(
                    IconDetector.class,
                    EnumSet.of(Scope.BINARY_RESOURCE_FILE)
            )
    );

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE || folderType == ResourceFolderType.MIPMAP;
    }

    @Override
    public void checkBinaryFile(@NonNull Context context, @NonNull File file, @NonNull byte[] content) {
        String name = file.getName();
        int dot = name.lastIndexOf('.');
        if (dot == -1 || dot == name.length() - 1) {
            return;
        }

        String extension = name.substring(dot + 1).toLowerCase();
        String format = detectImageFormat(content);
        if (format == null || format.equals(extension)) {
            return;
        }

        // JPEG files may use either .jpg or .jpeg extension
        if (format.equals("jpg") && (extension.equals("jpeg") || extension.equals("jpg"))) {
            return;
        }

        context.report(
                ICON_EXTENSION,
                Location.create(file),
                String.format("The file is a `%s` file but has a `.%s` extension", format, extension)
        );
    }

    private static String detectImageFormat(@NonNull byte[] content) {
        if (content.length < 4) {
            return null;
        }

        // PNG: 89 50 4E 47
        if (startsWith(content, 0x89, 0x50, 0x4E, 0x47)) {
            return "png";
        }

        // JPEG: FF D8 FF
        if (content[0] == (byte) 0xFF && content[1] == (byte) 0xD8 && content[2] == (byte) 0xFF) {
            return "jpg";
        }

        // GIF: 47 49 46 38
        if (startsWith(content, 0x47, 0x49, 0x46, 0x38)) {
            return "gif";
        }

        // BMP: 42 4D
        if (content[0] == (byte) 0x42 && content[1] == (byte) 0x4D) {
            return "bmp";
        }

        // WebP: RIFF....WEBP
        if (content.length >= 12
                && startsWith(content, 0x52, 0x49, 0x46, 0x46)
                && content[8] == (byte) 0x57 && content[9] == (byte) 0x45
                && content[10] == (byte) 0x42 && content[11] == (byte) 0x50) {
            return "webp";
        }

        return null;
    }

    private static boolean startsWith(@NonNull byte[] content, int... bytes) {
        if (content.length < bytes.length) {
            return false;
        }
        for (int i = 0; i < bytes.length; i++) {
            if (content[i] != (byte) bytes[i]) {
                return false;
            }
        }
        return true;
    }
}
