import com.google.common.base.Ascii;

import java.io.File;
import java.util.Arrays;
import java.util.List;

public class IconDetector extends Detector implements Detector.ResourceFolderScanner {

    private static final String ID = "IconLocation";
    private static final String DESCRIPTION = "Image defined in density-independent drawable folder";
    private static final String EXPLANATION =
            "The res/drawable folder is intended for density-independent graphics such as "
            + "shapes defined in XML. For bitmaps, move it to `drawable-mdpi` and consider "
            + "providing higher and lower resolution versions in `drawable-ldpi`, "
            + "`drawable-hdpi` and `drawable-xhdpi`. If the icon really is density independent "
            + "(for example a solid color) you can place it in `drawable-nodpi`.";

    public static final Issue ICON_LOCATION = Issue.create(
            ID,
            DESCRIPTION,
            EXPLANATION,
            Category.ICONS,
            5,
            Severity.WARNING,
            new Implementation(IconDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private static final List<String> BITMAP_EXTENSIONS = Arrays.asList(
            "png", "jpg", "jpeg", "gif", "webp", "bmp", "9.png");

    @Override
    public void checkFile(@NonNull ResourceContext context) {
        if (context.getResourceFolderType() != ResourceFolderType.DRAWABLE) {
            return;
        }

        File file = context.getFile();
        // Only the plain drawable folder is for density independent drawables.
        if (!"drawable".equals(file.getParentFile().getName())) {
            return;
        }

        String name = file.getName();
        if (isBitmap(name)) {
            Location location = Location.create(file);
            context.report(ICON_LOCATION, location, DESCRIPTION);
        }
    }

    private static boolean isBitmap(String fileName) {
        String lower = Ascii.toLowerCase(fileName);
        for (String ext : BITMAP_EXTENSIONS) {
            if (lower.endsWith("." + ext)) {
                return true;
            }
        }
        return false;
    }
}
