public class IconDetector extends ResourceFolderDetector {
    private static final String PNG_EXTENSION = ".png";
    private static final String NINE_PATCH_EXTENSION = ".9.png";
    public static final Issue ICON_MIXED_NINE_PATCH = Issue.create(
        "IconMixedNinePatch",
        "Clashing PNG and 9-PNG files",
        "If you accidentally name two separate resources `file.png` and `file.9.png`, ...",
        Category.ICONS,
        5,
        Severity.WARNING,
        new Implementation(IconDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private Map<File, Map<String, File>> mFolderToBaseNames;

    @Override public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE || folderType == ResourceFolderType.MIPMAP;
    }

    @Override public void beforeCheckProject(@NonNull Context context) {
        mFolderToBaseNames = new HashMap<>();
    }

    @Override public void checkFile(@NonNull ResourceContext context) {
        File file = context.file;
        String name = file.getName();
        boolean ninePatch = name.endsWith(NINE_PATCH_EXTENSION);
        if (!ninePatch && !name.endsWith(PNG_EXTENSION)) return;
        String baseName = ninePatch ? name.substring(0, name.length() - NINE_PATCH_EXTENSION.length())
                                    : name.substring(0, name.length() - PNG_EXTENSION.length());
        File folder = file.getParentFile();
        Map<String, File> baseNames = mFolderToBaseNames.get(folder);
        if (baseNames == null) {
            baseNames = new HashMap<>();
            mFolderToBaseNames.put(folder, baseNames);
        }
        File existing = baseNames.get(baseName);
        if (existing != null) {
            // check if one is nine patch and other png, or both? The issue is mixed.
            boolean existingNinePatch = existing.getName().endsWith(NINE_PATCH_EXTENSION);
            if (existingNinePatch != ninePatch) {
                Location location = Location.create(file);
                Location secondary = Location.create(existing);
                location.setSecondary(secondary);
                context.report(ICON_MIXED_NINE_PATCH, location,
                    "Found both `" + existing.getName() + "` and `" + name + "` in " + folder.getName() + "; they both resolve to @drawable/" + baseName);
            }
        } else {
            baseNames.put(baseName, file);
        }
    }
