private static void checkWebp(ResourceContext context, File file) {
    int minSdk = context.getProject().getMinSdk();
    if (minSdk >= 18) return;
    try (InputStream stream = new BufferedInputStream(new FileInputStream(file))) {
        byte[] header = new byte[64];
        int read = stream.read(header);
        if (read < 12) return;
        if (header[0]!='R' || header[1]!='I' || header[2]!='F' || header[3]!='F') return;
        if (header[8]!='W' || header[9]!='E' || header[10]!='B' || header[11]!='P') return;
        if (read < 16) return;
        String chunk = new String(header, 12, 4, "US-ASCII");
        boolean requiresApi18 = false;
        if ("VP8L".equals(chunk)) {
            requiresApi18 = true;
        } else if ("VP8X".equals(chunk)) {
            if (read > 20) {
                int flags = header[20] & 0xFF;
                boolean hasAlpha = (flags & 0x10) != 0;
                if (hasAlpha) requiresApi18 = true;
            }
            // Also could scan for VP8L chunks; but for extended, lossless is indicated by VP8L chunk.
            // Simpler: if extended, assume may require API 18? But spec says lossless and transparency require 18.
            // We can search bytes for VP8L chunk in header buffer.
            requiresApi18 = requiresApi18 || containsLosslessChunk(header, read);
