        if (minSdk < 15) {
            report(context, file, "WebP images require API 15 (Android 4.0) or higher.");
        } else if (requiresApi18) {
            report(context, file, "Lossless and transparent WebP images require API 18 (Android 4.2.1) or higher.");
        }
    } catch (IOException e) {
        // ignore
    }
}
