private static WebpInfo getWebpInfo(File file) throws IOException {
    try (DataInputStream in = new DataInputStream(new BufferedInputStream(new FileInputStream(file)))) {
        byte[] riff = new byte[12];
        in.readFully(riff);
        if (!isFourCC(riff, 0, "RIFF") || !isFourCC(riff, 8, "WEBP")) return null;
        byte[] fourcc = new byte[4];
        in.readFully(fourcc);
        WebpInfo info = new WebpInfo();
        if (isFourCC(fourcc, 0, "VP8 ")) {
            return info;
        } else if (isFourCC(fourcc, 0, "VP8L")) {
            info.lossless = true;
            return info;
        } else if (isFourCC(fourcc, 0, "VP8X")) {
            int chunkSize = readLE(in);
            byte[] payload = new byte[chunkSize];
            in.readFully(payload);
            int flags = payload[0] & 0xFF;
            info.alpha = (flags & 0x10) != 0;
            // parse remaining chunks for VP8L
            while (true) {
                try {
                    in.readFully(fourcc);
                } catch (EOFException e) { break; }
                int size = readLE(in);
                if (isFourCC(fourcc, 0, "VP8L")) {
                    info.lossless = true;
                    break;
                }
                // skip size bytes (pad to even)
                long skip = size + (size & 1);
                while (skip > 0) {
                    long s = in.skip(skip);
                    if (s <= 0) break;
                    skip -= s;
                }
            }
            return info;
        }
        return null;
    } catch (EOFException e) {
        return null;
    }
}
```
