    @Override
    public void checkBinaryResource(ResourceContext context) {
        File file = context.file;
        if (!file.getName().regionMatches(true, file.getName().length() - EXT_WEBP.length(),
                EXT_WEBP, 0, EXT_WEBP.length())) {
            return;
        }

        // Only flag images under drawable/mipmap resource folders.
        String parentName = file.getParentFile().getName();
        if (!parentName.startsWith("drawable") && !parentName.startsWith("mipmap")) {
            return;
        }

        int minSdk = context.getProject().getMinSdk();
        if (minSdk >= 18) {
            return;
        }

        byte[] header = context.readFile(file);
        if (header == null || header.length < 16) {
            return;
        }

        // Validate RIFF....WEBP header.
        if (header[0] != 'R' || header[1] != 'I' || header[2] != 'F' || header[3] != 'F'
                || header[8] != 'W' || header[9] != 'E' || header[10] != 'B' || header[11] != 'P') {
            return;
        }

        boolean isLossyVp8 = header[12] == 'V' && header[13] == 'P'
