    private static final int FEATURE_LOSSLESS = 1;
    private static final int FEATURE_TRANSPARENCY = 2;

    private int getWebpFeatures(@NonNull File file) {
        int features = 0;
        RandomAccessFile raf = null;
        try {
            raf = new RandomAccessFile(file, "r");
            byte[] header = new byte[12];
            if (raf.read(header) != 12) {
                return 0;
            }
            // RIFF .... WEBP
            if (header[0] != 'R' || header[1] != 'I' || header[2] != 'F' || header[3] != 'F'
                    || header[8] != 'W' || header[9] != 'E' || header[10] != 'B'
                    || header[11] != 'P') {
                return 0;
            }

            byte[] chunk = new byte[8];
            while (raf.read(chunk) == 8) {
                int size = (chunk[4] & 0xFF) | ((chunk[5] & 0xFF) << 8)
                        | ((chunk[6] & 0xFF) << 16) | ((chunk[7] & 0xFF) << 24);
                if (chunk[0] == 'V' && chunk[1] == 'P' && chunk[2] == '8' && chunk[3] == 'L') {
                    features |= FEATURE_LOSSLESS;
                    features |= FEATURE_TRANSPARENCY;
                    break;
                } else if (chunk[0] == 'V' && chunk[1] == 'P' && chunk[2] == '8' && chunk[3] == 'X') {
                    byte[] vp8x = new byte[10];
                    if (raf.read(vp8x) == 10) {
                        int flags = vp8x[0];
                        if ((flags & 0x10) != 0) {
                            features |= FEATURE_TRANSPARENCY;
                        }
                    }
                    // Need to skip rest of chunk
                    if (size > 10) {
                        raf.skipBytes(size - 10);
                    }
                    // VP8X chunk size is padded to even
                    if ((size & 1) != 0) {
                        raf.skipBytes(1);
                    }
                } else if (chunk[0] == 'V' && chunk[1] == 'P' && chunk[2] == '8' && chunk[3] == ' ') {
                    // Simple lossy WebP, no transparency
                    break;
                } else {
                    // Skip chunk + padding
                    int skip = size + (size & 1);
                    if (raf.skipBytes(skip) != skip) {
                        break;
                    }
                }
            }
        } catch (IOException e) {
            // ignore
        } finally {
            if (raf != null) {
                try {
                    raf.close();
                } catch (IOException e) {
                    // ignore
                }
            }
        }
        return features;
    }
}
