package com.android.tools.lint.checks;
import static com.android.tools.lint.client.api.AndroidVisitor.*? no.
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;
import java.util.Arrays;
import java.util.Collection;

public class RtlDetector extends ResourceXmlDetector {
  public static final Issue ISSUE = Issue.create(
    "RtlCompat",
    "Right-to-left text compatibility issues",
    "The `textAlignment` attribute was introduced in API 17, so it will not be applied on older devices. You should also use `android:gravity` or `android:layout_gravity` to ensure correct alignment on older platforms.",
    Category.I18N,
    3,
    Severity.WARNING,
    new Implementation(RtlDetector.class, Scope.RESOURCE_FILE_SCOPE)
  );

  private static final String TEXT_ALIGNMENT = "textAlignment";
  private static final String GRAVITY = "gravity";
  private static final String LAYOUT_GRAVITY = "layoutGravity";
  private static final String LAYOUT_GRAVITY_ATTR = "layout_gravity";

  @Override
  public Collection<String> getApplicableAttributes() {
    return Arrays.asList(TEXT_ALIGNMENT);
  }

  @Override
  public void visitAttribute(XmlContext context, Attr attribute) {
    // check minSdk
    if (context.getProject().getMinSdk() >= 17) return;

    Element element = attribute.getOwnerElement();
    if (hasAttribute(element, GRAVITY) || hasAttribute(element, LAYOUT_GRAVITY_ATTR)) return;

    // ignore if attribute value is "inherit"
    String value = attribute.getValue();
    if ("inherit".equals(value)) return;

    context.report(ISSUE, attribute, context.getValueLocation(attribute), 
      "textAlignment will be ignored on devices running API < 17; you should also use `android:gravity` or `android:layout_gravity`");
  }

  private static boolean hasAttribute(Element element, String localName) {
    if (element.hasAttribute("http://schemas.android.com/apk/res/android:" + localName)) {
      return true;
    }
    // fallback scanning attributes by local name
    NamedNodeMap attrs = element.getAttributes();
    for (int i=0; i<attrs.getLength(); i++) {
      Attr attr = (Attr) attrs.item(i);
      if (localName.equals(attr.getLocalName())) return true;
    }
    return false;
  }
}

