package com.android.tools.lint.checks;

import com.android.SdkConstants;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Arrays;
import java.util.Collection;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

public class RtlDetector extends Detector implements Detector.XmlScanner {

    public static final Issue ISSUE = Issue.create(
            "RtlSymmetry",
            "Padding and margin symmetry",
            "If you specify padding or margin on the left side of a layout, you should also "
                    + "specify padding on the right side (and vice versa) for right-to-left "
                    + "layout symmetry.",
            Category.RTL,
            5,
            Severity.WARNING,
            new Implementation(RtlDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableAttributes() {
        return Arrays.asList(
                SdkConstants.ATTR_PADDING_LEFT,
                SdkConstants.ATTR_PADDING_RIGHT,
                SdkConstants.ATTR_PADDING_START,
                SdkConstants.ATTR_PADDING_END,
                SdkConstants.ATTR_LAYOUT_MARGIN_LEFT,
                SdkConstants.ATTR_LAYOUT_MARGIN_RIGHT,
                SdkConstants.ATTR_LAYOUT_MARGIN_START,
                SdkConstants.ATTR_LAYOUT_MARGIN_END);
    }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        String namespace = attribute.getNamespaceURI();
        if (namespace == null || !namespace.equals(SdkConstants.ANDROID_URI)) {
            return;
        }

        String name = attribute.getLocalName();
        Element element = attribute.getOwnerElement();

        String opposite = getOpposite(name);
        if (opposite == null) {
            return;
        }

        String global = getGlobal(name);
        if (hasAttribute(element, opposite) || hasAttribute(element, global)) {
            return;
        }

        String side = name.endsWith("Left") || name.endsWith("Start") ? "left/start" : "right/end";
        String type = name.contains("layout_margin") ? "margin" : "padding";
        context.report(ISSUE, attribute, context.getLocation(attribute),
                String.format("When you define %1$s on one side you should define %1$s on the other side for RTL symmetry",
                        type));
    }

    private static boolean hasAttribute(Element element, String name) {
        return name != null && element.hasAttributeNS(SdkConstants.ANDROID_URI, name);
    }

    private static String getOpposite(String name) {
        if (SdkConstants.ATTR_PADDING_LEFT.equals(name)) return SdkConstants.ATTR_PADDING_RIGHT;
        if (SdkConstants.ATTR_PADDING_RIGHT.equals(name)) return SdkConstants.ATTR_PADDING_LEFT;
        if (SdkConstants.ATTR_PADDING_START.equals(name)) return SdkConstants.ATTR_PADDING_END;
        if (SdkConstants.ATTR_PADDING_END.equals(name)) return SdkConstants.ATTR_PADDING_START;
        if (SdkConstants.ATTR_LAYOUT_MARGIN_LEFT.equals(name)) return SdkConstants.ATTR_LAYOUT_MARGIN_RIGHT;
        if (SdkConstants.ATTR_LAYOUT_MARGIN_RIGHT.equals(name)) return SdkConstants.ATTR_LAYOUT_MARGIN_LEFT;
        if (SdkConstants.ATTR_LAYOUT_MARGIN_START.equals(name)) return SdkConstants.ATTR_LAYOUT_MARGIN_END;
        if (SdkConstants.ATTR_LAYOUT_MARGIN_END.equals(name)) return SdkConstants.ATTR_LAYOUT_MARGIN_START;
        return null;
    }

    private static String getGlobal(String name) {
        if (name.contains("layout_margin")) return SdkConstants.ATTR_LAYOUT_MARGIN;
        return SdkConstants.ATTR_PADDING;
    }
}

