public void visitMethodCall(@NonNull JavaContext context, @NonNull UCallExpression node, @NonNull PsiMethod method) {
    if (!"setContentView".equals(method.getName())) return;
    List<UExpression> args = node.getValueArguments();
    if (args.isEmpty()) return;
    UExpression arg = args.get(0);
    String text = arg.getSourcePsi() != null ? arg.getSourcePsi().getText() : arg.asSourceString();
    if (text == null) return;
    Matcher matcher = SET_CONTENT_VIEW_PATTERN.matcher(text);
    if (matcher.find()) {
        String layout = matcher.group(1);
        UClass cls = UastUtils.getParentOfType(node, UClass.class, false);
        if (cls != null) {
            String name = cls.getQualifiedName();
            if (name == null) name = cls.getName();
            if (name != null) mLayoutToActivities.put(layout, name);
        }
    }
}
