```java
private boolean hasWindowBackground(@NonNull Context context, @NonNull String className) {
    Document manifest = context.getMainProject().getMergingManifest();
    if (manifest == null) return true;
    Element root = manifest.getDocumentElement();
    String packageName = root.getAttribute("package");
    String absoluteClassName = className.startsWith(".") ? packageName + className : className;
    if (!absoluteClassName.contains(".") && packageName != null && !packageName.isEmpty()) {
        absoluteClassName = packageName + "." + absoluteClassName;
    }
    String activityTheme = null;
    NodeList activities = root.getElementsByTagName(TAG_ACTIVITY);
    for (int i = 0, n = activities.getLength(); i < n; i++) {
        Element activity = (Element) activities.item(i);
        String name = activity.getAttribute(ANDROID_URI, ATTR_NAME);
        if (name == null) name = activity.getAttribute(ATTR_NAME);
        name = normalizeClassName(packageName, name);
        if (absoluteClassName.equals(name)) {
            activityTheme = activity.getAttribute(ANDROID_URI, ATTR_THEME);
            if (activityTheme != null && !activityTheme.isEmpty()) break;
        }
    }
    if (activityTheme == null || activityTheme.isEmpty()) {
        Element application = (Element) root.getElementsByTagName(TAG_APPLICATION).item(0);
        if (application != null) activityTheme = application.getAttribute(ANDROID_URI, ATTR_THEME);
    }
    if (activityTheme == null || activityTheme.isEmpty()) return true; // default theme
    // If the theme reference resolves to a style whose windowBackground is @null, no overdraw.
    return !isWindowBackgroundNull(context, activityTheme);
}
```
