@Override
public void visitMethod(@NonNull JavaContext context,
                        @NonNull JavaElementVisitor visitor,
                        @NonNull PsiMethodCallExpression call,
                        @NonNull PsiMethod method) {
    String name = method.getName();
    if (!"setContentView".equals(name)) return;
    PsiExpression[] args = call.getArgumentList().getExpressions();
    if (args.length >= 1) {
        PsiExpression first = args[0];
        if (first instanceof PsiReferenceExpression) {
            PsiReferenceExpression ref = (PsiReferenceExpression) first;
            String layout = ref.getReferenceName();
            if (layout != null) {
                PsiExpression qualifier = ref.getQualifierExpression();
                if (qualifier instanceof PsiReferenceExpression) {
                    PsiReferenceExpression parent = (PsiReferenceExpression) qualifier;
                    if ("layout".equals(parent.getReferenceName()) &&
                            parent.getQualifierExpression() instanceof PsiReferenceExpression &&
                            "R".equals(((PsiReferenceExpression) parent.getQualifierExpression()).getReferenceName())) {
                        PsiClass containing = context.getEvaluator().findSurroundingClass(call);
                        if (containing != null) {
                            String activity = containing.getQualifiedName();
                            if (activity != null) {
                                mReferences.put(layout, activity);
                            }
                        }
                    }
                }
            }
        }
    }
}
```

