@Override
public void visitMethodCall(@NonNull JavaContext context, @NonNull UCallExpression node, @NonNull PsiElement method) {
    if (!"setContentView".equals(node.getMethodName())) return;
    if (node.getValueArgumentCount() < 1) return;
    UExpression arg = node.getValueArguments().get(0);
    String layoutName = getLayoutName(arg);
    if (layoutName == null) return;
    UClass containingClass = UastUtils.getParentOfType(node, UClass.class, false);
    if (containingClass == null) return;
    // Check class extends Activity/AppCompatActivity
    if (!isActivityClass(containingClass)) return;
    String activityName = getQualifiedName(containingClass);
    if (activityName == null) return;
    mActivityToLayout.put(activityName, layoutName);
}
```

