@Nullable
private String resolveActivityName(@NonNull XmlContext context, @NonNull String name) {
    String pkg = context.getMainProject().getPackage();
    if (pkg == null) pkg = "";
    if (name.startsWith(".")) return pkg + name;
    if (name.contains(".")) return name;
    return pkg + "." + name;
}
