@Override
public void afterCheckEachProject(@NonNull Context context) {
    for (String layout : mOverdrawLayouts) {
        Set<String> activities = mLayoutToActivities.get(layout);
        if (activities == null || activities.isEmpty()) continue;
        boolean overdraw = false;
        for (String activity : activities) {
            String theme = mActivityThemes.get(activity);
            if (theme == null || theme.isEmpty()) theme = mApplicationTheme;
            if (hasWindowBackground(theme)) {
                overdraw = true;
                break;
            }
        }
        if (overdraw) {
            Location location = mLayoutLocations.get(layout);
            if (location != null) {
                context.report(ISSUE, location,
                    "Possible overdraw: root view of layout \"" + layout + "\" has a custom background, and this layout is used by an Activity whose theme also has a window background. Consider using a theme with a null windowBackground.");
            }
        }
    }
}
