@Nullable
private static String normalizeStyleName(@Nullable String value) {
    if (value == null || value.isEmpty()) return null;
    if (value.startsWith(STYLE_PREFIX)) return value.substring(STYLE_PREFIX.length());
    if (value.startsWith(ANDROID_STYLE_PREFIX)) return value.substring(ANDROID_STYLE_PREFIX.length());
    if (value.startsWith("@")) return value.substring(1);
    return value;
}
