package com.android.tools.lint.checks

import com.android.SdkConstants
import com.android.resources.ResourceFolderType
import com.android.tools.lint.detector.api.Context
import com.android.tools.lint.detector.api.Detector
import com.android.tools.lint.detector.api.Implementation
import com.android.tools.lint.detector.api.Issue
import com.android.tools.lint.detector.api.Location
import com.android.tools.lint.detector.api.Scope
import com.android.tools.lint.detector.api.Severity
import com.android.tools.lint.detector.api.XmlContext
import org.w3c.dom.Element

class TranslucentViewDetector : Detector(), Detector.XmlScanner {

    private data class StyleInfo(
        val name: String,
        val parent: String?,
        val items: Map<String, String>
    )

    private data class PendingActivity(
        val context: XmlContext,
        val element: Element,
        val location: Location,
        val orientation: String,
        val themeRef: String
    )

    private val styles = mutableMapOf<String, StyleInfo>()
    private val pendingActivities = mutableListOf<PendingActivity>()

    override fun getApplicableElements(): Collection<String> =
        listOf(SdkConstants.TAG_ACTIVITY, SdkConstants.TAG_STYLE)

    override fun appliesTo(folderType: ResourceFolderType): Boolean = true

    override fun beforeCheckRootProject(context: Context) {
        styles.clear()
        pendingActivities.clear()
    }

    override fun visitElement(context: XmlContext, element: Element) {
        val tagName = element.tagName
        if (tagName == SdkConstants.TAG_STYLE) {
            recordStyle(element)
        } else if (tagName == SdkConstants.TAG_ACTIVITY &&
            context.file.name == SdkConstants.ANDROID_MANIFEST_XML
        ) {
            recordActivity(context, element)
        }
    }

    private fun recordStyle(element: Element) {
        val name = element.getAttribute(SdkConstants.ATTR_NAME).takeUnless { it.isEmpty() } ?: return
        var parent = element.getAttribute(SdkConstants.ATTR_PARENT).takeUnless { it.isEmpty() }
        if (parent == null) {
            val lastDot = name.lastIndexOf('.')
            if (lastDot > 0) {
                parent = name.substring(0, lastDot)
            }
        } else {
            parent = normalizeStyleReference(parent) ?: parent // returns name only if @style/ or @android:style/
        }

        val items = mutableMapOf<String, String>()
        val children = element.childNodes
        for (i in 0 until children.length) {
            val child = children.item(i) as? Element ?: continue
            if (child.tagName != SdkConstants.TAG_ITEM) continue
            val itemName = child.getAttribute(SdkConstants.ATTR_NAME).takeUnless { it.isEmpty() } ?: continue
            val normalizedName = if (itemName.startsWith(ANDROID_PREFIX)) {
                itemName.substring(ANDROID_PREFIX.length)
            } else itemName
            items[normalizedName] = child.textContent?.trim() ?: ""
        }

        styles[name] = StyleInfo(name, parent, items)
    }

    private fun recordActivity(context: XmlContext, element: Element) {
        val orientation = element.getAttribute(SdkConstants.ATTR_SCREEN_ORIENTATION).takeUnless { it.isEmpty() } ?: return
        if (orientation == UNSPECIFIED || orientation == BEHIND || orientation !in FIXED_ORIENTATIONS) return
        val themeRef = element.getAttribute(SdkConstants.ATTR_THEME).takeUnless { it.isEmpty() } ?: return
        val location = context.getLocation(element)
        pendingActivities.add(PendingActivity(context, element, location, orientation, themeRef))
    }

    override fun afterCheckRootProject(context: Context) {
        val translucent = computeTranslucentStyles()
        for (pending in pendingActivities) {
            val (isFramework, styleName) = parseStyleReference(pending.themeRef) ?: continue
            if (isFramework) {
                if (styleName.contains(TRANSLUCENT)) {
                    report(pending, "translucent platform theme")
                }
            } else if (styleName in translucent) {
                report(pending, "translucent theme")
            }
        }
    }

    private fun computeTranslucentStyles(): Set<String> {
        val translucent = mutableSetOf<String>()
        // direct
        for (style in styles.values) {
            if (style.items[WINDOW_IS_TRANSLUCENT] == SdkConstants.VALUE_TRUE) {
                translucent.add(style.name)
            }
        }
        // platform translucent parent
        for (style in styles.values) {
            val parent = style.parent
            if (parent != null && parent.contains(TRANSLUCENT) && style.items[WINDOW_IS_TRANSLUCENT] != SdkConstants.VALUE_FALSE) {
                translucent.add(style.name)
            }
        }
        // transitive
        var changed = true
        while (changed) {
            changed = false
            for (style in styles.values) {
                if (style.name in translucent) continue
                if (style.items[WINDOW_IS_TRANSLUCENT] == SdkConstants.VALUE_FALSE) continue
                val parent = style.parent ?: continue
                if (parent in translucent) {
                    translucent.add(style.name)
                    changed = true
                }
            }
        }
        return translucent
    }

    private fun report(pending: PendingActivity, description: String) {
        pending.context.report(
            ISSUE,
            pending.element,
            pending.location,
            "This activity declares a fixed screenOrientation ("${pending.orientation}") with a $description. " +
                "This combination is not supported on apps with targetSdkVersion O or higher and will throw an exception on Android O+ devices. " +
                "Either remove android:screenOrientation or remove android:windowIsTranslucent from the theme."
        )
    }

    private fun parseStyleReference(ref: String): Pair<Boolean, String>? {
        return when {
            ref.startsWith(STYLE_PREFIX) -> false to ref.substring(STYLE_PREFIX.length)
            ref.startsWith(ANDROID_STYLE_PREFIX) -> true to ref.substring(ANDROID_STYLE_PREFIX.length)
            ref.startsWith(ANDROID_STAR_STYLE_PREFIX) -> true to ref.substring(ANDROID_STAR_STYLE_PREFIX.length)
            else -> null
        }
    }

    private fun normalizeStyleReference(ref: String): String? {
        return parseStyleReference(ref)?.second
    }

    companion object {
        private const val WINDOW_IS_TRANSLUCENT = "windowIsTranslucent"
        private const val TRANSLUCENT = "Translucent"
        private const val STYLE_PREFIX = "@style/"
        private const val ANDROID_STYLE_PREFIX = "@android:style/"
        private const val ANDROID_STAR_STYLE_PREFIX = "@*android:style/"
        private const val ANDROID_PREFIX = "android:"
        private const val UNSPECIFIED = "unspecified"
        private const val BEHIND = "behind"
        private val FIXED_ORIENTATIONS = setOf(
            "landscape", "portrait", "reverseLandscape", "reversePortrait",
            "sensorLandscape", "sensorPortrait", "userLandscape", "userPortrait", "locked"
        )

        @JvmField
        val ISSUE = Issue.create(
            id = "TranslucentOrientation",
            briefDescription = "Mixing screenOrientation with a translucent theme",
            explanation = """
                Specifying a fixed screenOrientation with a translucent theme is not supported on apps with targetSdkVersion O or greater. If another activity visible behind the translucent activity requests a conflicting orientation, the system on Android O and higher throws an IllegalArgumentException.

                To fix this, either remove the fixed android:screenOrientation or remove android:windowIsTranslucent from the activity theme.
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.ERROR,
            implementation = Implementation(
                TranslucentViewDetector::class.java,
                Scope.MANIFEST_SCOPE,
                Scope.RESOURCE_FILE_SCOPE
            )
        )
    }
}
