package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import org.jetbrains.uast.*

class PictureInPictureDetector : Detector(), SourceCodeScanner {

    companion object {
        val ISSUE = Issue.create(
            id = "PictureInPictureIssue",
            briefDescription = "Picture In Picture best practices not followed",
            explanation = """
                Starting in Android 12, the recommended approach for enabling picture-in-picture \
                has changed. To ensure smooth transitions, you should call \
                `setAutoEnterEnabled(true)` and `setSourceRectHint(...)` on the \
                `PictureInPictureParams.Builder`.
            """,
            category = Category.USABILITY,
            priority = 5,
            severity = Severity.WARNING,
            implementation = Implementation(
                PictureInPictureDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }

    override fun getApplicableUastTypes(): List<Class<out UElement>>? =
        listOf(UCallExpression::class.java)

    override fun createUastHandler(context: JavaContext): UElementHandler? =
        object : UElementHandler() {
            override fun visitCallExpression(node: UCallExpression) {
                val methodName = node.methodName ?: return
                if (methodName == "build") {
                    val receiver = node.receiverType ?: return
                    if (receiver.canonicalText == "android.app.PictureInPictureParams.Builder") {
                        val chain = collectBuilderChain(node)
                        val hasAuto = chain.any { it.methodName == "setAutoEnterEnabled" && hasTrueArg(it) }
                        val hasSource = chain.any { it.methodName == "setSourceRectHint" }
                        if (!hasAuto || !hasSource) {
                            context.report(
                                ISSUE,
                                node,
                                context.getLocation(node),
                                "Picture-in-Picture should use setAutoEnterEnabled(true) and setSourceRectHint(...)"
                            )
                        }
                    }
                } else if (methodName == "enterPictureInPictureMode") {
                    val arg = node.valueArguments.firstOrNull() ?: return
                    val build = findBuildExpression(arg)
                    if (build != null) {
                        // inspect builder chain
                        val receiver = build.receiverType ?: return
                        if (receiver.canonicalText == "android.app.PictureInPictureParams.Builder") {
                            val chain = collectBuilderChain(build)
                            val hasAuto = chain.any { it.methodName == "setAutoEnterEnabled" && hasTrueArg(it) }
                            val hasSource = chain.any { it.methodName == "setSourceRectHint" }
                            if (!hasAuto || !hasSource) {
                                context.report(
                                    ISSUE,
                                    node,
                                    context.getLocation(node),
                                    "Picture-in-Picture should use setAutoEnterEnabled(true) and setSourceRectHint(...)"
                                )
                            }
                        }
                    }
                }
            }
        }

    private fun collectBuilderChain(build: UCallExpression): List<UCallExpression> {
        val result = mutableListOf<UCallExpression>()
        var current: UElement? = build
        while (current != null) {
            if (current is UCallExpression) {
                result.add(current)
                current = current.receiver
            } else {
                break
            }
        }
        return result
    }

    private fun UCallExpression.receiverType(): PsiType? {
        val receiver = this.receiver ?: return null
        return (receiver as? UTypedExpression)?.getExpressionType()
            ?: (receiver as? UCallExpression)?.resolve()?.containingClass?.let { PsiTypesUtil.getClassType(it) }
    }
}

