package com.android.tools.lint.checks

import com.android.tools.lint.client.api.LintClient
import com.android.tools.lint.detector.api.*
import org.w3c.dom.Element
import java.util.*

class AppBundleLocaleChangesDetector : Detector(), XmlScanner, GradleScanner {
    private var hasRuntimeLocaleChange = false
    private var localeConfigLocation: Location? = null
    private var languageSplitDisabled = false
    private var hasPlayCore = false

    override fun getApplicableElements(): Collection<String> = listOf(SdkConstants.TAG_APPLICATION)

    override fun visitElement(context: XmlContext, element: Element) {
        val localeConfig = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_LOCALE_CONFIG)
        if (localeConfig.isNotBlank()) {
            hasRuntimeLocaleChange = true
            localeConfigLocation = context.getElementLocation(element)
        }
    }

    override fun visitBuildScript(context: GradleContext) {
        val source = try { context.file.readText() } catch (e: Exception) { return }
        // Check bundle language enableSplit = false
        if (source.contains("enableSplit") && source.contains("language") && source.contains("bundle")) {
            // More precise regex
            val pattern = Regex("""bundle\s*\{[\s\S]*?language\s*\{[\s\S]*?enableSplit\s*=\s*false""")
            if (pattern.containsMatchIn(source)) {
                languageSplitDisabled = true
            }
        }
        // Check Android Gradle Plugin shortcut android.bundle.language.enableSplit = false
        if (Regex("""\bandroid\s*\{\s*[\s\S]*?\bbundle\s*\{\s*[\s\S]*?\blanguage\s*\{\s*[\s\S]*?\benableSplit\s*=\s*false\b""").containsMatchIn(source)) {
            languageSplitDisabled = true
        }
        // Check play core library
        if (source.contains("com.google.android.play:core") ||
            source.contains("com.google.android.play:feature-delivery") ||
            source.contains("com.google.android.play:core-ktx")) {
            hasPlayCore = true
        }
    }

    override fun afterCheckRootProject(context: Context) {
        if (!hasRuntimeLocaleChange) return
        if (languageSplitDisabled || hasPlayCore) return
        localeConfigLocation?.let { loc ->
            context.report(
                ISSUE,
                loc,
                "When changing locales at runtime, the App Bundle must not split by locale, or the Play Core library must be used to download additional languages at runtime.",
                null
            )
        }
    }

    companion object {
        private const val ID = "AppBundleLocaleChanges"
        private const val BRIEF = "App Bundle locale change handling missing"
        private const val EXPLANATION = """
            When your app supports changing locales at runtime (e.g. via an in-app language switcher),
            you must either disable App Bundle language splitting in your build configuration
            (`bundle { language { enableSplit = false } }`) or use the Play Core library to fetch
            additional language splits at runtime. Otherwise, users may not see the selected language.
            """
        val ISSUE = Issue.create(
            ID,
            BRIEF,
            EXPLANATION,
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            Implementation(AppBundleLocaleChangesDetector::class.java, Scope.MANIFEST_AND_GRADLE_SCOPE)
        )
    }
}
