private String resolveManifestName(String name) {
    if (mManifestPackage == null || name == null) return name;
    if (name.startsWith(".")) {
        return mManifestPackage + name;
    }
    if (name.indexOf('.') < 0) {
        return mManifestPackage + "." + name;
    }
    return name;
}
