public class RegistrationDetector extends Detector implements XmlScanner, SourceCodeScanner {
    ...
    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_MANIFEST, TAG_ACTIVITY, TAG_SERVICE, TAG_PROVIDER);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Node node) {
        String tag = node.getNodeName();
        if (TAG_MANIFEST.equals(tag)) {
            mPackageName = ((Element) node).getAttribute(ATTR_PACKAGE);
            return;
        }
        if (mPackageName == null) return;
        String name = ((Element) node).getAttributeNS(ANDROID_URI, ATTR_NAME);
        if (name == null || name.isEmpty()) return;
        String fqcn = getFullyQualifiedClassName(mPackageName, name);
        if (fqcn != null) {
            mRegisteredClasses.put(fqcn, node);
        }
    }

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NonNull JavaContext context) {
        return new ComponentVisitor(context);
    }

    private class ComponentVisitor extends UElementHandler {
        private final JavaContext context;

        ComponentVisitor(JavaContext context) { this.context = context; }

        @Override
        public void visitClass(@NonNull UClass node) {
            JavaEvaluator evaluator = context.evaluator;
            PsiClass psiClass = node.getJavaPsi();
            if (psiClass != null && evaluator.isAbstract(psiClass)) { // skip abstract classes
                return;
            }
            // Also maybe check is interface/enum
            if (node.isInterface() || node.isEnum() || node.isAnnotationType()) return;

            String fqcn = node.getQualifiedName();
            if (fqcn == null) return;

            boolean isComponent = false;
            String message = null;
            if (evaluator.extendsClass(node, CLASS_ACTIVITY, false)) {
                isComponent = true;
                message = String.format("%s is not registered in the manifest", fqcn);
            } else if (evaluator.extendsClass(node, CLASS_SERVICE, false)) {
                isComponent = true;
                message = String.format("%s is not registered in the manifest", fqcn);
            } else if (evaluator.extendsClass(node, CLASS_CONTENT_PROVIDER, false)) {
                isComponent = true;
                message = String.format("%s is not registered in the manifest", fqcn);
            }
            if (isComponent && !mRegisteredClasses.containsKey(fqcn)) {
                context.report(ISSUE, node, context.getLocation(node), message);
            }
        }
    }
