private String resolveManifestName(XmlContext context, String name) {
    if (name.isEmpty()) return name;
    int firstDot = name.indexOf('.');
    int secondDot = name.indexOf('.', firstDot + 1);
    if (firstDot == -1 || (name.charAt(0) == '.' && secondDot == -1 && firstDot == 0)) {
        String packageName = context.getDocument().getDocumentElement().getAttribute("package");
        if (!packageName.isEmpty()) {
            if (name.charAt(0) == '.') {
                return packageName + name;
            } else {
                return packageName + '.' + name;
            }
        }
    }
    return name;
}
```

