public class AndroidAutoDetector extends Detector implements XmlScanner {
    private static final String MEDIA_PLAY_FROM_SEARCH = "android.media.action.MEDIA_PLAY_FROM_SEARCH";

    public static final Issue ISSUE = Issue.create(
        "MissingIntentFilterForMediaSearch",
        "Missing MEDIA_PLAY_FROM_SEARCH intent-filter",
        "To support voice searches on Android Auto, you should register an intent-filter for the action android.media.action.MEDIA_PLAY_FROM_SEARCH.",
        Category.CORRECTNESS, 6, Severity.WARNING,
        new Implementation(AndroidAutoDetector.class, Scope.MANIFEST_SCOPE)
    );

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_MANIFEST);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (!hasAction(element, MEDIA_PLAY_FROM_SEARCH)) {
            context.report(ISSUE, element, context.getLocation(element),
                "Missing intent-filter for action android.media.action.MEDIA_PLAY_FROM_SEARCH");
        }
    }

    private static boolean hasAction(Element root, String actionName) {
        NodeList actions = root.getElementsByTagName(TAG_ACTION);
        for (int i = 0; i < actions.getLength(); i++) {
            Element action = (Element) actions.item(i);
            if (actionName.equals(action.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
                return true;
            }
        }
        return false;
    }
}
