        }
    } else if (TAG_ACTION.equals(tag)) {
        String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
        if (MEDIA_PLAY_FROM_SEARCH.equals(name)) {
            mHasMediaPlayFromSearch = true;
        }
    }
}
