private String getQualifiedServiceName(@NonNull XmlContext context, @NonNull Element service) {
    String name = service.getAttributeNS(SdkConstants.ANDROID_URI, "name");
    if (name == null || name.isEmpty()) return null;
    if (name.startsWith(".")) {
        name = context.getMainProject().getPackage() + name;
    } else if (!name.contains(".")) {
        name = context.getMainProject().getPackage() + "." + name;
    }
    return name;
}
