```
private static String getQualifiedServiceName(XmlContext context, Element element) {
    String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
    if (name == null || name.isEmpty()) return null;
    Element manifest = context.document.getDocumentElement();
    String packageName = manifest.getAttributeNS(ANDROID_URI, ATTR_PACKAGE);
    if (packageName == null) packageName = manifest.getAttribute(ATTR_PACKAGE); // no prefix
    if (packageName == null) return name;
    if (name.startsWith(".")) {
        return packageName + name;
    } else if (name.indexOf('.') < 0) {
        return packageName + "." + name;
    }
    return name;
}
```
