    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (!TAG_SERVICE.equals(element.getTagName())) return;
        String serviceName = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
        if (serviceName.isEmpty()) return;
        NodeList intentFilters = element.getElementsByTagName(TAG_INTENT_FILTER);
        for (int i=0; i<intentFilters.getLength(); i++) {
            Element intentFilter = (Element) intentFilters.item(i);
            NodeList actions = intentFilter.getElementsByTagName(TAG_ACTION);
            for (int j=0; j<actions.getLength(); j++) {
                Element action = (Element) actions.item(j);
                String actionName = action.getAttributeNS(ANDROID_URI, ATTR_NAME);
                if (MEDIA_BROWSER_INTENT_FILTER.equals(actionName)) {
                    mMediaBrowserServices.put(serviceName, Boolean.TRUE);
                    return;
                }
            }
        }
    }

    @Override
    public List<String> applicableFiles() {
        return Collections.singletonList(Scope.CLASS_FILE_SCOPE);
    }

    @Override
    public void checkClass(@NonNull JavaContext context, @NonNull ClassNode classNode) {
        String className = classNode.name.replace('/', '.');
        if (!mMediaBrowserServices.containsKey(className)) return;
        if (!isMediaBrowserService(classNode)) return;
        boolean hasMethod = false;
        for (Object m : classNode.methods) {
            MethodNode method = (MethodNode) m;
            if (ON_PLAY_FROM_SEARCH.equals(method.name)
                    && ON_PLAY_FROM_SEARCH_DESC.equals(method.desc)) {
                hasMethod = true;
                break;
            }
        }
        if (!hasMethod) {
            context.report(MISSING_ON_PLAY_FROM_SEARCH,
                    context.getLocation(classNode),
                    "You should override and implement onPlayFromSearch(String, Bundle) in this MediaBrowserService to support voice searches on Android Auto.");
        }
    }

    private static boolean isMediaBrowserService(ClassNode classNode) {
        return MEDIA_BROWSER_SERVICE.equals(classNode.superName.replace('/', '.'))
                || MEDIA_BROWSER_SERVICE_COMPAT.equals(classNode.superName.replace('/', '.'));
    }
}
