package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_ID;
import static com.android.SdkConstants.ATTR_LAYOUT;
import static com.android.SdkConstants.ID_PREFIX;
import static com.android.SdkConstants.NEW_ID_PREFIX;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

import java.io.File;
import java.util.*;

public class DuplicateIdDetector extends ResourceXmlDetector {
    private static final String ISSUE_SUMMARY = "Duplicate ids across layouts combined with include tags";
    private static final String ISSUE_EXPLANATION = "...";

    public static final Issue ISSUE = Issue.create(
        "DuplicateIncludedIds",
        ISSUE_SUMMARY,
        ISSUE_EXPLANATION,
        Category.CORRECTNESS,
        7,
        Severity.ERROR,
        new Implementation(DuplicateIdDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private final Map<String, Map<String, Location>> mIds = new HashMap<>();
    private final Map<String, List<IncludeReference>> mIncludes = new HashMap<>();

    private static class IncludeReference {
        final String layout;
        final Location location;
        IncludeReference(String layout, Location location) { this.layout = layout; this.location = location; }
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    @NonNull
    public Collection<String> getApplicableElements() {
        return Arrays.asList(INCLUDE_TAG, SdkConstants.TAG_MERGE, "*");
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String tag = element.getTagName();
        String currentLayout = getLayoutName(context.file);

        if ("include".equals(tag)) {
            Attr layoutAttr = element.getAttributeNode(ATTR_LAYOUT);
            if (layoutAttr == null) layoutAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_LAYOUT);
            if (layoutAttr != null) {
                String value = layoutAttr.getValue();
                if (value.startsWith(PREFIX_ANDROID + "layout/")? Wait ATTR_LAYOUT value is @layout/...
                if (value.startsWith("@layout/") or value.startsWith(SdkConstants.LAYOUT_PREFIX). Let's import SdkConstants.LAYOUT_PREFIX = "@layout/". 
                    String included = value.substring(LAYOUT_PREFIX.length());
                    mIncludes.computeIfAbsent(currentLayout, k -> new ArrayList<>())
                        .add(new IncludeReference(included, context.getLocation(layoutAttr)));
                }
            }

            Attr idAttr = element.getAttributeNode(ATTR_ID); // or ANDROID_URI
            if (idAttr == null) idAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_ID);
            if (idAttr != null) recordId(currentLayout, idAttr, context);
        } else {
            Attr idAttr = element.getAttributeNode(ATTR_ID);
            if (idAttr == null) idAttr = element.getAttributeNodeNS(ANDROID_URI, ATTR_ID);
            if (idAttr != null) recordId(currentLayout, idAttr, context);
        }
    }

    private void recordId(String layoutName, Attr idAttr, XmlContext context) {
        String value = idAttr.getValue();
        String id = getIdName(value);
        if (id == null) return;
        Map<String, Location> map = mIds.computeIfAbsent(layoutName, k -> new HashMap<>());
        if (!map.containsKey(id)) {
            map.put(id, context.getLocation(idAttr));
        }
    }

    private String getIdName(String value) {
        if (value.startsWith(NEW_ID_PREFIX)) return value.substring(NEW_ID_PREFIX.length());
        if (value.startsWith(ID_PREFIX)) return value.substring(ID_PREFIX.length());
        int slash = value.lastIndexOf('/');
        if (slash != -1) return value.substring(slash + 1);
        return null;
    }

    private String getLayoutName(File file) {
        String name = file.getName();
        int dot = name.lastIndexOf('.');
        if (dot > 0) name = name.substring(0, dot);
        return name;
    }

    @Override
    public void afterCheckEachProject(@NonNull Context context) {
        Set<String> reported = new HashSet<>();
        for (String layout : mIncludes.keySet()) {
            Set<String> visited = new HashSet<>();
            visited.add(layout);
            List<String> path = new ArrayList<>();
            path.add(layout);
            check(layout, layout, path, visited, reported);
        }
        mIds.clear();
        mIncludes.clear();
    }

    private void check(String root, String current, List<String> path, Set<String> visited, Set<String> reported) {
        List<IncludeReference> refs = mIncludes.get(current);
        if (refs == null) return;
        for (IncludeReference ref : refs) {
            if (visited.contains(ref.layout)) continue;
            visited.add(ref.layout);
            path.add(ref.layout);
            // check for duplicate ids between current layout and included layout
            Map<String, Location> currentIds = mIds.get(current);
            Map<String, Location> includedIds = mIds.get(ref.layout);
            if (currentIds != null && includedIds != null) {
                for (Map.Entry<String, Location> entry : currentIds.entrySet()) {
                    String id = entry.getKey();
                    Location includedLoc = includedIds.get(id);
                    if (includedLoc != null) {
                        String key = root + "|" + current + "|" + ref.layout + "|" + id;
                        if (!reported.contains(key)) {
                            reported.add(key);
                            Location location = entry.getValue();
                            Location secondary = Location.create(includedLoc.getFile(), includedLoc.getContents(), includedLoc.getStartOffset(), includedLoc.getEndOffset(), includedLoc.getStartLine(), includedLoc.getEndLine(), includedLoc.getStartColumn(), includedLoc.getEndColumn(), null);
                            String message = String.format("Duplicate id %1$s found between %2$s and included layout %3$s", id, current, ref.layout);
                            context.report(ISSUE, location, message, secondary);
                        }
                    }
                }
            }
            check(root, ref.layout, path, visited, reported);
            path.remove(path.size() - 1);
            visited.remove(ref.layout);
