private static String getResourceName(String value) {
    if (value == null || value.isEmpty()) {
        return null;
    }
    int slash = value.lastIndexOf('/');
    if (slash == -1) {
        return null;
    }
    String name = value.substring(slash + 1);
    int colon = name.indexOf(':');
    if (colon != -1) {
        name = name.substring(0, colon);
    }
    return name;
}
```

