    public void afterCheckFile(XmlContext context) {
        checkFile(context);
    }

    private void checkFile(XmlContext context) {
        Element root = context.document.getDocumentElement();
        if (root == null) return;

        List<IdOccurrence> occurrences = new ArrayList<>();
        Set<File> chain = new HashSet<>();
        collectIdsFromElement(context, root, null, context.file, chain, occurrences);

        Map<String, List<IdOccurrence>> idMap = new HashMap<>();
        for (IdOccurrence occurrence : occurrences) {
            idMap.computeIfAbsent(occurrence.id, k -> new ArrayList<>()).add(occurrence);
