        for (Map.Entry<String, List<IdOccurrence>> entry : idMap.entrySet()) {
            List<IdOccurrence> list = entry.getValue();
            if (list.size() > 1) {
                reportDuplicate(context, entry.getKey(), list);
            }
        }
    }
    ...
}
