private static class IdOccurrence {
    final String id;
    final Location location;
    IdOccurrence(String id, Location location) { ... }
}

private void collectIds(@NonNull XmlContext context,
                        @NonNull File file,
                        @Nullable String overrideId,
                        @Nullable Location overrideLocation,
                        @NonNull Set<File> chain,
                        @NonNull List<IdOccurrence> occurrences) {
    if (!chain.add(file)) return;
    try {
        Document doc = PositionXmlParser.parse(file);
        if (doc != null) {
            Element root = doc.getDocumentElement();
            if (root != null) {
                collectIdsFromElement(context, root, overrideId, overrideLocation, file, chain, occurrences);
            }
        }
    } catch (Exception e) {
        // ignore parse errors
    } finally {
        chain.remove(file);
    }
}

private void collectIdsFromElement(@NonNull XmlContext context,
                                    @NonNull Element element,
                                    @Nullable String overrideId,
                                    @Nullable Location overrideLocation,
                                    @NonNull File sourceFile,
                                    @NonNull Set<File> chain,
                                    @NonNull List<IdOccurrence> occurrences) {
    if (TAG_INCLUDE.equals(element.getTagName())) {
        String layoutName = getLayoutName(getLayoutAttribute(element));
        if (layoutName != null) {
            File included = resolveLayout(context, layoutName);
            if (included != null) {
                String includeOverrideId = getIdName(element);
                Location includeOverrideLocation = null;
                if (includeOverrideId != null) {
                    includeOverrideLocation = sourceFile.equals(context.file)
                        ? context.getLocation(element)
                        : Location.create(sourceFile);
                }
                collectIds(context, included, includeOverrideId, includeOverrideLocation, chain, occurrences);
                return;
            }
        }
    }

    String id = overrideId;
    Location location = overrideLocation;
    if (id == null) {
        id = getIdName(element);
        if (id != null) {
            location = sourceFile.equals(context.file)
                ? context.getLocation(getIdAttribute(element))
                : Location.create(sourceFile);
        }
    }

    if (id != null && !TAG_MERGE.equals(element.getTagName())) {
        occurrences.add(new IdOccurrence(id, location != null ? location : Location.create(sourceFile)));
    }

    Node child = element.getFirstChild();
    while (child != null) {
        if (child.getNodeType() == Node.ELEMENT_NODE) {
            collectIdsFromElement(context, (Element) child, null, null, sourceFile, chain, occurrences);
        }
        child = child.getNextSibling();
    }
}
