Implementation:

```
class EmptySuperDetector : Detector(), SourceCodeScanner {
    override fun getApplicableUastTypes() = listOf(UMethod::class.java)

    override fun createUastHandler(context: JavaContext): UElementHandler {
        return object : UElementHandler() {
            override fun visitMethod(node: UMethod) {
                val emptySuperMethods = node.findSuperMethods().filter { hasEmptySuperAnnotation(it) }
                if (emptySuperMethods.isEmpty()) return

                val body = node.uastBody ?: return
                body.accept(object : AbstractUastVisitor() {
                    override fun visitCallExpression(node: UCallExpression): Boolean {
                        if (node.receiver is USuperExpression && node.kind == UastCallKind.METHOD_CALL) {
                            val resolved = node.resolve()
                            val matches = if (resolved != null) {
                                emptySuperMethods.any { it == resolved }
                            } else {
                                node.methodName == node.name // careful shadowing: outer node.name vs call node.methodName
                            }
                            if (matches) {
                                context.report(ISSUE, node, context.getLocation(node), "Calling super implementation of a method annotated @EmptySuper is not recommended")
                            }
                        }
                        return super.visitCallExpression(node)
                    }
                })
            }
        }
    }

    private fun hasEmptySuperAnnotation(method: PsiMethod): Boolean = method.annotations.any { 
        val name = it.qualifiedName ?: return@any false
        name == "EmptySuper" || name.endsWith(".EmptySuper")
    }

    companion object {
        @JvmField
        val ISSUE = Issue.create(
            id = "EmptySuperCall",
            briefDescription = "Calling an empty super method",
            explanation = "Methods annotated with @EmptySuper indicate that overriding methods should not call the super implementation, either because it is empty or because it contains code not intended to be run when the method is overridden.",
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(EmptySuperDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )
    }
}
