        if (!isValidJavaIdentifier(value)) {
            context.report(ISSUE, attribute, context.getValueLocation(attribute),
                    String.format("'%1$s' is not a valid method name", value));
            return;
        }

        String methodName = value;
        JavaEvaluator evaluator = context.getClient().getJavaEvaluator();
        if (evaluator == null) {
            return;
        }

        // Look up the Activity context for this layout
        String activityName = findActivityContext(context, attribute);
        if (activityName != null) {
            PsiClass activityClass = evaluator.findClass(activityName);
