        }

        context.report(ISSUE, attribute, context.getValueLocation(attribute),
                String.format("Corresponding method handler '%1$s(View)' not found", methodName));
    }

    private static boolean isValidJavaIdentifier(String name) {
        if (name.isEmpty() || !Character.isJavaIdentifierStart(name.charAt(0))) {
            return false;
        }
        for (int i = 1, n = name.length(); i < n; i++) {
            if (!Character.isJavaIdentifierPart(name.charAt(i))) {
                return false;
            }
        }
        return true;
    }

    @Nullable
    private static String findActivityContext(@NonNull XmlContext context, @NonNull Attr attribute) {
        Element root = attribute.getOwnerElement().getOwnerDocument().getDocumentElement();
        if (root == null) return null;
        String contextValue = root.getAttributeNS(TOOLS_URI, "context");
        if (contextValue == null || contextValue.isEmpty()) return null;
        if (contextValue.startsWith(".")) {
            // Relative to package
