        if (value.startsWith("@")) return; // no checking
        if (!isValidJavaIdentifier(value)) {
            context.report(ISSUE, attribute, context.getValueLocation(attribute),
                String.format("Method name '%1$s' is not a valid Java identifier", value));
            return;
        }

        JavaEvaluator evaluator = context.getClient().getJavaEvaluator();
        if (!hasMethod(evaluator, value)) {
            context.report(ISSUE, attribute, context.getValueLocation(attribute),
                String.format("Corresponding method handler '%1$s(View)' not found", value));
        }
    }

    private static boolean hasMethod(JavaEvaluator evaluator, String name) {
        for (String className : getCandidateClasses()) {
            PsiClass cls = evaluator.findClass(className);
            if (cls == null) continue;
            for (PsiMethod method : cls.findMethodsByName(name, true)) {
                if (isValidOnClickMethod(method)) return true;
            }
        }
        return false;
    }
