private static boolean methodExists(JavaEvaluator evaluator, String name, Collection<String> classNames) {
    for (String className : classNames) {
        PsiClass cls = evaluator.findClass(className);
        if (cls == null) continue;
        for (PsiMethod method : cls.findMethodsByName(name, true)) {
            PsiParameterList params = method.getParameterList();
            if (params.getParametersCount() == 1) {
                PsiParameter param = params.getParameters()[0];
                PsiType type = param.getType();
                if (type.equalsToText("android.view.View") || type.equalsToText("View")) {
                    if (method.hasModifierProperty(PsiModifier.PUBLIC)) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}
```

