package com.android.tools.lint.checks;

import static com.android.tools.lint.detector.api.LintConstants.ANDROID_URI;
import static com.android.tools.lint.detector.api.LintConstants.ATTR_LAYOUT_HEIGHT;
import static com.android.tools.lint.detector.api.LintConstants.ATTR_LAYOUT_WIDTH;
import static com.android.tools.lint.detector.api.LintConstants.VIEW;
import static com.android.tools.lint.detector.api.LintConstants.GRID_LAYOUT;

import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;
import java.util.Collection;
import java.util.Collections;

public class RequiredAttributeDetector extends LayoutDetector {
    private static final Implementation IMPLEMENTATION = new Implementation(
            RequiredAttributeDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "RequiredSize",
            "Missing layout_width or layout_height attributes",
            "All views must specify an explicit `layout_width` and `layout_height` attribute. ...",
            Category.CORRECTNESS,
            8,
            Severity.FATAL,
            IMPLEMENTATION)
            .setAndroidSpecific(true);

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String tag = element.getTagName();
        if (tag.equals("GridLayout") || tag.equals(VIEW) || tag.contains(".") && tag.endsWith("GridLayout")) {
            return;
        }
        // skip non-view tags
        if (tag.equals("layout") || tag.equals("data") || tag.equals("merge") || tag.equals("include") || tag.equals("requestFocus") || tag.equals("view")) {
            return;
        }
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH)
                && !hasStyleAttribute(element, ATTR_LAYOUT_WIDTH)) {
            reportMissing(context, element, ATTR_LAYOUT_WIDTH);
        }
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT)
                && !hasStyleAttribute(element, ATTR_LAYOUT_HEIGHT)) {
            reportMissing(context, element, ATTR_LAYOUT_HEIGHT);
        }
    }

    private boolean hasStyleAttribute(Element element, String attrName) {
        // best-effort check style attribute for attrName
        return false;
    }

    private void reportMissing(XmlContext context, Element element, String attrName) {
        context.report(ISSUE, element, context.getLocation(element),
                "Element is missing required attribute android:" + attrName);
    }
}
```

