        boolean hasHeight = element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_LAYOUT_HEIGHT);

        if (!hasWidth && !hasHeight) {
            context.report(REQUIRED_SIZE, element, context.getLocation(element),
                "Element is missing `android:layout_width` and `android:layout_height` attributes");
        } else if (!hasWidth) {
            context.report(REQUIRED_SIZE, element, context.getLocation(element),
                "Element is missing `android:layout_width` attribute");
        } else if (!hasHeight) {
            context.report(REQUIRED_SIZE, element, context.getLocation(element),
                "Element is missing `android:layout_height` attribute");
        }
    }

    private static boolean isLikelyView(String tag) {
        // Layout XML view class tags conventionally start with an uppercase letter.
        // Non-view tags such as <include>, <merge>, <fragment>, etc. start lowercase.
        char c = tag.charAt(0);
        return Character.isUpperCase(c);
    }

    private static boolean isGridLayout(String tag) {
        return tag.equals("GridLayout") || tag.endsWith(".GridLayout");
    }
}
