public class AlwaysShowActionDetector extends Detector implements Detector.XmlScanner, Detector.JavaScanner {

    private static final String ANDROID_URI = "http://schemas.android.com/apk/res/android";
    private static final String ATTR_SHOW_AS_ACTION = "showAsAction";
    private static final String VALUE_ALWAYS = "always";
    private static final String VALUE_IF_ROOM = "ifRoom";
    private static final String TAG_ITEM = "item";
    private static final String MENU_ITEM_CLASS = "android.view.MenuItem";

    public static final Issue ISSUE = Issue.create(
            "AlwaysShowAction",
            "Usage of `showAsAction=always`",
            "Using `showAsAction=\"always\"` in menu XML, or `MenuItem.SHOW_AS_ACTION_ALWAYS` in " +
            "Java code is usually a deviation from the user interface style guide. Use `ifRoom` " +
            "or the corresponding `MenuItem.SHOW_AS_ACTION_IF_ROOM` instead.\n" +
            "\n" +
            "If `always` is used sparingly there are usually no problems and behavior is " +
            "roughly equivalent to `ifRoom` but with preference over other `ifRoom` " +
            "items. Using it more than twice in the same menu is a bad idea.\n" +
            "\n" +
            "This check looks for menu XML files that contain more than two `always` " +
            "actions, or some `always` actions and no `ifRoom` actions. In Java code, " +
            "it looks for projects that contain references to " +
            "`MenuItem.SHOW_AS_ACTION_ALWAYS` and no references to " +
            "`MenuItem.SHOW_AS_ACTION_IF_ROOM`.",
            Category.USABILITY,
            3,
            Severity.WARNING,
            new Implementation(AlwaysShowActionDetector.class,
                    EnumSet.of(Scope.RESOURCE_FILE, Scope.JAVA_FILE))
    );

    // XML state
    private int mAlwaysCount;
    private int mIfRoomCount;
    private List<Location> mAlwaysItemLocations;

    // Java state
    private boolean mJavaHasIfRoom;
    private List<Location> mJavaAlwaysLocations;

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        mJavaAlwaysLocations = new ArrayList<>();
        mJavaHasIfRoom = false;
    }

    @Override
    public void beforeCheckFile(@NonNull Context context) {
        if (context.getResourceFolderType() == ResourceFolderType.MENU) {
            mAlwaysCount = 0;
            mIfRoomCount = 0;
            mAlwaysItemLocations = new ArrayList<>();
        }
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.MENU;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_ITEM);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Attr attr = getShowAsActionAttr(element);
        if (attr == null) {
            return;
        }

        String value = attr.getValue();
        if (value.contains(VALUE_ALWAYS)) {
            mAlwaysCount++;
            mAlwaysItemLocations.add(context.getValueLocation(attr));
        }
        if (value.contains(VALUE_IF_ROOM)) {
            mIfRoomCount++;
        }
    }

    @Override
    public void afterCheckFile(@NonNull Context context) {
        if (context.getResourceFolderType() != ResourceFolderType.MENU) {
            return;
        }

        if (mAlwaysCount > 2) {
            for (Location location : mAlwaysItemLocations) {
                context.report(ISSUE, location,
                        "More than two `showAsAction=\"always\"` items in this menu; use `showAsAction=\"ifRoom\"` instead");
            }
        } else if (mAlwaysCount > 0 && mIfRoomCount == 0) {
            for (Location location : mAlwaysItemLocations) {
                context.report(ISSUE, location,
                        "This menu uses `showAsAction=\"always\"` but contains no `showAsAction=\"ifRoom\"` items");
            }
        }
    }

    @Override
    public List<String> getApplicableFieldNames() {
        return Arrays.asList("SHOW_AS_ACTION_ALWAYS", "SHOW_AS_ACTION_IF_ROOM");
    }

    @Override
    public void visitField(@NonNull JavaContext context, @Nullable AstVisitor visitor,
            @NonNull Node node, @NonNull String name) {
        if (!isMenuItemField(context, node)) {
            return;
        }

        if ("SHOW_AS_ACTION_IF_ROOM".equals(name)) {
            mJavaHasIfRoom = true;
        } else if ("SHOW_AS_ACTION_ALWAYS".equals(name)) {
            mJavaAlwaysLocations.add(context.getLocation(node));
        }
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        if (!mJavaHasIfRoom && mJavaAlwaysLocations != null && !mJavaAlwaysLocations.isEmpty()) {
            for (Location location : mJavaAlwaysLocations) {
                context.report(ISSUE, location,
                        "This project uses `MenuItem.SHOW_AS_ACTION_ALWAYS` but does not reference `MenuItem.SHOW_AS_ACTION_IF_ROOM`");
            }
        }
    }

    private static boolean isMenuItemField(@NonNull JavaContext context, @NonNull Node node) {
        JavaParser.ResolvedNode resolved = context.resolve(node);
        if (resolved instanceof JavaParser.ResolvedField) {
            JavaParser.ResolvedClass cls = ((JavaParser.ResolvedField) resolved).getContainingClass();
            return cls != null && MENU_ITEM_CLASS.equals(cls.getName());
        }
        return false;
    }

    @Nullable
    private static Attr getShowAsActionAttr(@NonNull Element element) {
        Attr attr = element.getAttributeNodeNS(ANDROID_URI, ATTR_SHOW_AS_ACTION);
        if (attr != null) {
            return attr;
        }

        NamedNodeMap attrs = element.getAttributes();
        for (int i = 0, count = attrs.getLength(); i < count; i++) {
            Attr candidate = (Attr) attrs.item(i);
            String name = candidate.getName();
            if (ATTR_SHOW_AS_ACTION.equals(name)
                    || name.endsWith(":" + ATTR_SHOW_AS_ACTION)) {
                return candidate;
            }
        }

        return null;
    }
}
