package com.android.tools.lint.checks;

import com.android.tools.lint.detector.api.*;
import com.intellij.psi.PsiMethod;
import com.intellij.psi.PsiType;
import org.jetbrains.uast.*;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nonnull;
import java.util.Collections;
import java.util.List;

public class BadHostnameVerifierDetector extends Detector implements SourceCodeScanner {
    private static final String HOSTNAME_VERIFIER = "javax.net.ssl.HostnameVerifier";

    public static final Issue ISSUE = Issue.create(
            "BadHostnameVerifier",
            "Insecure HostnameVerifier",
            "This HostnameVerifier implementation unconditionally returns true from its verify(...) method. "
            + "That causes the app to trust any hostname presented in TLS/SSL certificates, "
            + "which makes it vulnerable to man-in-the-middle attacks.",
            Category.SECURITY,
            6,
            Severity.WARNING,
            new Implementation(BadHostnameVerifierDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UMethod.class);
    }

    @Override
    public UElementHandler createUastHandler(JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitMethod(UMethod method) {
                if (!"verify".equals(method.getName())) return;
                UClass containingClass = method.getContainingUClass();
                if (containingClass == null) return;
                if (!context.getEvaluator().implementsInterface(containingClass, HOSTNAME_VERIFIER, false)) {
                    return;
                }
                PsiMethod psiMethod = method.getJavaPsi();
                if (psiMethod == null) return;
                if (!PsiType.BOOLEAN.equals(psiMethod.getReturnType())) return;
                if (psiMethod.getParameterList().getParametersCount() != 2) return;

                UExpression body = method.getUastBody();
                if (body == null) return;

                if (isUnconditionalTrue(body)) {
                    context.report(ISSUE, method, context.getLocation(method), "Insecure HostnameVerifier: unconditionally returns true");
                }
            }
        };
    }

    private static boolean isUnconditionalTrue(UExpression expression) {
        if (expression instanceof UReturnExpression) {
            UExpression returnExpr = ((UReturnExpression) expression).getReturnExpression();
            return isTrueLiteral(returnExpr);
        } else if (expression instanceof UBlockExpression) {
            List<UExpression> expressions = ((UBlockExpression) expression).getExpressions();
            if (expressions.size() != 1) return false;
            return isUnconditionalTrue(expressions.get(0));
        }
        return false;
    }

    private static boolean isTrueLiteral(UExpression expression) {
        if (expression instanceof ULiteralExpression) {
            Object value = ((ULiteralExpression) expression).getValue();
            return Boolean.TRUE.equals(value);
        }
        return false;
    }
}
