            if (params.length != 2) continue;
            if (!isString(params[0].getType())) continue;
            if (!isSslSession(params[1].getType())) continue;
            if (alwaysReturnsTrue(method)) {
                Location location = context.getNameLocation(method);
                context.report(ISSUE, method, location,
                        "Insecure `HostnameVerifier`: unconditionally returns true");
                break; // only report once per class
            }
        }
    }

    private static boolean isString(PsiType type) {
        return "java.lang.String".equals(type.getCanonicalText());
    }
    private static boolean isSslSession(PsiType type) {
        return "javax.net.ssl.SSLSession".equals(type.getCanonicalText());
    }

    private static boolean alwaysReturnsTrue(UMethod method) {
        UExpression body = method.getUastBody();
        if (body == null) return false;
        return isAlwaysTrue(body);
    }

