class ChromeOsSourceDetector : Detector(), SourceCodeScanner {

  override fun getApplicableUastTypes(): List<Class<out UElement>> = listOf(UMethod::class.java)

  override fun createUastHandler(context: JavaContext): UElementHandler {
    return object : UElementHandler() {
      override fun visitMethod(node: UMethod) {
        if (node.name != "onConfigurationChanged") return
        if (node.uastParameters.size != 1) return
        val param = node.uastParameters[0]
        val paramType = param.typeReference?.getQualifiedName() ?: param.type // maybe use context.evaluator.getTypeClass(param.type)
        if (paramType != "android.content.res.Configuration") return
        val containingClass = node.getContainingUClass() ?: return
        if (!context.evaluator.extendsClass(containingClass, "android.app.Activity", false)) return

        node.accept(RedrawCallVisitor(context))
      }
    }
  }

  private inner class RedrawCallVisitor(val context: JavaContext) : AbstractUastVisitor() {
    override fun visitCallExpression(node: UCallExpression): Boolean {
      val method = node.resolve()
      if (method != null) {
        val name = method.name
        val cls = method.containingClass?.qualifiedName ?: ""
        // skip super.onConfigurationChanged
        if (node.receiver is USuperExpression) return super.visitCallExpression(node)
        if (isRedrawMethod(name, cls)) {
          context.report(ISSUE, node, context.getLocation(node), "Avoid calling `$name` inside `onConfigurationChanged()` as it can trigger a UI redraw and cause performance issues on Chrome OS and large-screen devices.")
        }
      } else {
        // unresolved: check method name
        val name = node.methodName ?: node.methodIdentifier?.name
        if (name != null && REDRAW_METHOD_NAMES.contains(name)) {
           // maybe skip super
           if (node.receiver is USuperExpression) return super.visitCallExpression(node)
           context.report(...)
        }
      }
      return super.visitCallExpression(node)
    }
  }

  private fun isRedrawMethod(name: String, className: String): Boolean {
    if (name in REDRAW_METHOD_NAMES) {
       if (name == "notifyDataSetChanged" || name == "notifyItemChanged" ...) return true
       if (className == "android.view.View" || className == "android.view.ViewGroup" || className.startsWith("android.widget.") || className.startsWith("androidx.recyclerview.widget.")) return true
    }
    return false
  }
}

