package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import org.jetbrains.uast.*
import org.jetbrains.uast.visitor.AbstractUastVisitor

class ChromeOsSourceDetector : Detector(), SourceCodeScanner {

    override fun getApplicableUastTypes(): List<Class<out UElement>> = listOf(UMethod::class.java)

    override fun createUastHandler(context: JavaContext): UElementHandler {
        return object : UElementHandler() {
            override fun visitMethod(node: UMethod) {
                if (node.name != "onConfigurationChanged") return
                if (node.uastParameters.size != 1) return

                val paramType = node.uastParameters[0].type.canonicalText.removeSuffix("?")
                if (paramType != "android.content.res.Configuration") return

                val containingClass = node.containingClass?.javaPsi ?: return
                if (!context.evaluator.extendsClass(containingClass, "android.app.Activity", false)) return

                node.accept(RedrawVisitor(context))
            }
        }
    }

    private class RedrawVisitor(private val context: JavaContext) : AbstractUastVisitor() {
        override fun visitCallExpression(node: UCallExpression): Boolean {
            if (node.receiver is USuperExpression) {
                return super.visitCallExpression(node)
            }

            val method = node.resolve()
            if (method != null) {
                val containingClass = method.containingClass ?: return super.visitCallExpression(node)
                if (!context.evaluator.extendsClass(containingClass, "android.view.View", false) &&
                    !context.evaluator.extendsClass(containingClass, "android.widget.AdapterView<*>", false) &&
                    !context.evaluator.extendsClass(containingClass, "androidx.recyclerview.widget.RecyclerView.Adapter", false) &&
                    !context.evaluator.extendsClass(containingClass, "androidx.swiperefreshlayout.widget.SwipeRefreshLayout", false)
                ) {
                    return super.visitCallExpression(node)
                }
                val methodName = method.name
                if (methodName in REDRAW_METHODS) {
                    report(node, methodName)
                }
            } else {
                val methodName = node.methodName ?: node.methodIdentifier?.name
                if (methodName in REDRAW_METHODS) {
                    report(node, methodName)
                }
            }
            return super.visitCallExpression(node)
        }

        private fun report(node: UCallExpression, methodName: String) {
            context.report(
                ISSUE,
                node,
                context.getLocation(node),
                "Avoid calling `$methodName` inside `onConfigurationChanged()`; it can trigger a UI redraw and cause performance issues on Chrome OS and large-screen devices."
            )
        }
    }

    companion object {
        @JvmField
        val ISSUE: Issue = Issue.create(
            id = "ChromeOsOnConfigurationChanged",
            briefDescription = "Avoid UI redraw calls inside onConfigurationChanged()",
            explanation = """
                When users resize the Android emulator in Android 13 and Chrome OS, an \
                `onConfigurationChanged()` call occurs. If this method contains code that can \
                cause a redraw, your app might take a performance hit on large screens. Avoid \
                calling methods such as `invalidate()`, `requestLayout()`, or \
                `notifyDataSetChanged()` here.
            """,
            category = Category.PERFORMANCE,
            priority = 5,
            severity = Severity.WARNING,
            implementation = Implementation(
                ChromeOsSourceDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )

        private val REDRAW_METHODS = setOf(
            "invalidate",
            "postInvalidate",
            "requestLayout",
            "forceLayout",
            "refreshDrawableState",
            "invalidateViews",
            "notifyDataSetChanged",
            "notifyItemChanged",
            "notifyItemRangeChanged",
            "notifyItemRangeInserted",
            "notifyItemRangeRemoved",
            "notifyDataSetInvalidated",
            "setRefreshing"
        )
    }
}
```

