public class JobSchedulerDetector extends Detector implements ClassScanner, XmlScanner {
    public static final Issue ISSUE = Issue.create(
        "JobSchedulerService",
        "JobScheduler problems",
        "The service class must extend `JobService`, must be registered in the manifest and the registration must require the permission `android.permission.BIND_JOB_SERVICE`.",
        Category.CORRECTNESS,
        6,
        Severity.WARNING,
        new Implementation(JobSchedulerDetector.class, Scope.JAVA_AND_RESOURCE_FILES));

    private static final String BIND_JOB_SERVICE = "android.permission.BIND_JOB_SERVICE";
    private static final String JOB_SERVICE = "android.app.job.JobService";

    private final List<Pair<String, Location>> mJobServices = new ArrayList<>();
    private final List<Pair<String, Location>> mManifestServices = new ArrayList<>();

    @Override
    public List<String> getApplicableCallNames() ... no.

    @Override
    public void checkClass(ClassContext context, ClassNode classNode) {
        if (classNode.name == null || classNode.superName == null) return;
        if (classNode.superName.equals("android/app/job/JobService")) {
            String name = classNode.name.replace('/', '.');
            mJobServices.add(Pair.of(name, context.getLocation(classNode)));
        }
    }

    @Override
    public Collection<String> getApplicableElements() { return Collections.singletonList(TAG_SERVICE); }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String permission = element.getAttributeNS(ANDROID_URI, ATTR_PERMISSION);
        if (BIND_JOB_SERVICE.equals(permission)) {
            String className = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
            if (className != null && !className.isEmpty()) {
                if (className.startsWith(".")) className = context.getProject().getPackage() + className;
                else if (!className.contains(".")) className = context.getProject().getPackage() + "." + className;
                mManifestServices.add(Pair.of(className, context.getLocation(element)));
            }
        }
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        // For each JobService class, ensure in manifest with permission
        for (Pair<String, Location> jobService : mJobServices) {
            boolean found = false;
            for (Pair<String, Location> manifestService : mManifestServices) {
                if (manifestService.getFirst().equals(jobService.getFirst())) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                context.report(ISSUE, jobService.getSecond(), "JobService ... must be registered ...");
            }
        }
        // For each manifest service with BIND_JOB_SERVICE permission, ensure class extends JobService
        for (Pair<String, Location> manifestService : mManifestServices) {
            boolean found = false;
            for (Pair<String, Location> jobService : mJobServices) {
                if (jobService.getFirst().equals(manifestService.getFirst())) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                context.report(ISSUE, manifestService.getSecond(), "Service ... must extend JobService");
            }
        }
    }
}

