@Override
public List<Class<? extends UElement>> getApplicableUastTypes() {
    return Collections.singletonList(UClass.class);
}

@Override
public UElementHandler createUastHandler(@NotNull JavaContext context) {
    return new UElementHandler() {
        @Override
        public void visitClass(@NotNull UClass node) {
            if (node instanceof UAnonymousClass) return; // skip anonymous
            String qualifiedName = node.getQualifiedName();
            if (qualifiedName == null) return;
            UTypeReferenceExpression superClass = node.getSuperClassReference();
            boolean extendsJobService = false;
            if (superClass != null) {
                PsiClass resolved = superClass.resolve();
                if (resolved != null) {
                    String superName = resolved.getQualifiedName();
                    extendsJobService = JOB_SERVICE.equals(superName);
                } else {
                    String text = superClass.getQualifiedName();
                    extendsJobService = JOB_SERVICE.equals(text);
                }
