@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    Node parentNode = element.getParentNode();
    if (!(parentNode instanceof Element)) {
        return;
    }
    Element parent = (Element) parentNode;
    String parentTag = parent.getTagName();
    if (parentTag.contains(":")) {
        parentTag = parentTag.substring(parentTag.indexOf(':') + 1);
    }
    Set<String> valid = VALID_PARAMS.get(parentTag);
    if (valid == null) {
        return;
    }

    NamedNodeMap attributes = element.getAttributes();
    for (int i = 0, n = attributes.getLength(); i < n; i++) {
        Attr attr = (Attr) attributes.item(i);
        if (!ANDROID_URI.equals(attr.getNamespaceURI())) {
            continue;
        }
        String name = attr.getLocalName();
        if (name == null) {
            name = attr.getName();
        }
        if (!name.startsWith(LAYOUT_PREFIX)) {
            continue;
        }
        if (!valid.contains(name)) {
            context.report(ISSUE, attr, context.getLocation(attr),
                    String.format("Invalid layout param in a `%1$s`: `%2$s`",
                            parentTag, name));
        }
    }
}
```

