fun strongconnect(v: Resource) {
indices[v] = index
lowlinks[v] = index
index++
sccStack.add(v)
onStack.add(v)
for (ref in graph[v]?.outgoing ?: emptyList()) {
val w = ref.target
if (w !in indices) {
strongconnect(w)
lowlinks[v] = min(lowlinks[v]!!, lowlinks[w]!!)
} else if (w in onStack) {
lowlinks[v] = min(lowlinks[v]!!, indices[w]!!)
}
}
if (lowlinks[v] == indices[v]) {
