public class ResourcePrefixDetector extends ResourceXmlDetector implements Detector.BinaryResourceScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            ResourcePrefixDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "ResourceName",
            "Resource with Wrong Prefix",
            "...",
            Category.USABILITY,
            4,
            Severity.WARNING,
            IMPLEMENTATION)
            .addMoreInfo("https://...");

    private Collection<String> mPrefixes;

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return true;
    }

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        Project project = context.getProject();
        if (project.isGradleProject()) {
            mPrefixes = project.getResourcePrefixes();
        } else {
            mPrefixes = Collections.emptyList();
        }
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (mPrefixes == null || mPrefixes.isEmpty()) return;
        if (context.getResourceFolderType() != ResourceFolderType.VALUES) return;
        String name = element.getAttribute(ATTR_NAME);
        if (!name.isEmpty() && !startsWithPrefix(name)) {
            context.report(ISSUE, context.getLocation(element.getAttributeNode(ATTR_NAME)),
                    String.format("Resource named `%1$s` does not start with required prefix `%2$s`", name, mPrefixes));
        }
    }

    @Override
    public void visitDocument(@NonNull XmlContext context, @NonNull Document document) {
        if (mPrefixes == null || mPrefixes.isEmpty()) return;
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType == null || folderType == ResourceFolderType.VALUES) return;
        String baseName = LintUtils.getBaseName(context.file.getName());
        if (!startsWithPrefix(baseName)) {
            context.report(ISSUE, Location.create(context.file),
                    String.format("Resource file `%1$s` does not start with required prefix `%2$s`", baseName, mPrefixes));
        }
    }

    @Override
    public void checkBinaryResource(@NonNull ResourceContext context) {
        if (mPrefixes == null || mPrefixes.isEmpty()) return;
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType == null || folderType == ResourceFolderType.VALUES) return;
        String baseName = LintUtils.getBaseName(context.file.getName());
        if (!startsWithPrefix(baseName)) {
            context.report(ISSUE, Location.create(context.file),
                    String.format("Resource file `%1$s` does not start with required prefix `%2$s`", baseName, mPrefixes));
        }
    }

    private boolean startsWithPrefix(String name) {
        if (mPrefixes == null) return true;
        for (String prefix : mPrefixes) {
            if (name.startsWith(prefix)) return true;
        }
        return false;
    }
}
