package com.android.tools.lint.checks;

import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.TAG_RESOURCES;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;

import org.w3c.dom.Attr;
import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;

import java.io.File;
import java.util.EnumSet;

public class ResourcePrefixDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
            "ResourceName",
            "Resource with Wrong Prefix",
            "In Gradle projects you can specify a resource prefix that all resources " +
            "in the project must conform to. This makes it easier to ensure that you don't " +
            "accidentally combine resources from different libraries, since they all end " +
            "up in the same shared app namespace.",
            Category.CORRECTNESS,
            3,
            Severity.WARNING,
            new Implementation(ResourcePrefixDetector.class,
                    Scope.RESOURCE_FILE_SCOPE)
    );

    @Nullable private String mPrefix;

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return true;
    }

    @Override
    public void beforeCheckFile(@NonNull XmlContext context) {
        super.beforeCheckFile(context);
        mPrefix = context.getProject().getResourcePrefix();
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (mPrefix == null || mPrefix.isEmpty()) {
            return;
        }

        String tag = element.getTagName();
        if (tag.equals(TAG_RESOURCES)) {
            // also check file name for resource file based folders? but values file name not resource.
            return;
        }

        if (!element.hasAttribute(ATTR_NAME)) {
            return;
        }
        String name = element.getAttribute(ATTR_NAME);
        if (name.isEmpty()) {
            return;
        }
        if (!name.startsWith(mPrefix)) {
            Attr attr = element.getAttributeNode(ATTR_NAME);
            if (attr != null) {
                context.report(ISSUE, attr, context.getLocation(attr),
                        String.format("Resource name should start with prefix '%1$s'", mPrefix));
            }
        }
    }

    @Override
    public void visitDocument(@NonNull XmlContext context, @NonNull org.w3c.dom.Document document) {
        if (mPrefix == null || mPrefix.isEmpty()) {
            return;
        }
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType == ResourceFolderType.VALUES) {
            return; // file names in values are not resource names
        }
        File file = context.file;
        String fileName = file.getName();
        int dot = fileName.indexOf('.');
        String name = dot >= 0 ? fileName.substring(0, dot) : fileName;
        if (!name.startsWith(mPrefix)) {
            Location location = Location.create(file);
            context.report(ISSUE, location,
                String.format("Resource name '%1$s' should start with prefix '%2$s'", name, mPrefix));
        }
    }
}
