```
public class VectorDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
        "VectorRaster",
        "Limitations of vector drawable raster image generation",
        "Vector icons require API 21 or API 24 depending on used features, ...",
        Category.CORRECTNESS,
        5,
        Severity.WARNING,
        new Implementation(VectorDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public Collection<String> getApplicableAttributes() {
        return ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (!isVector(context, element)) return;
        String tag = element.getLocalName();
        if (TAG_GRADIENT.equals(tag) || TAG_CLIP_PATH.equals(tag)) {
            String message = String.format(
                "`<%1$s>` is not supported in vector drawables when generating raster images for older devices; the generated bitmap may differ from the vector drawable.",
                tag);
            context.report(ISSUE, element, context.getLocation(element), message);
        }
    }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        Element owner = attribute.getOwnerElement();
        if (owner == null || !isVector(context, owner)) return;
        String name = attribute.getLocalName();
        if (ATTR_FILL_TYPE.equals(name)) {
            context.report(ISSUE, attribute, context.getLocation(attribute),
                "The `fillType` attribute is not supported when generating raster images for older devices; the generated bitmap may differ from the vector drawable.");
        }
    }

    private static boolean isVector(XmlContext context, Element element) {
        Document doc = element.getOwnerDocument();
        if (doc == null) return false;
        Element root = doc.getDocumentElement();
        return root != null && TAG_VECTOR.equals(root.getLocalName());
    }
}
```

