public class VectorDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
        "VectorRaster",
        "Vector Image Generation",
        "...",
        Category.CORRECTNESS, 5, Severity.WARNING,
        new Implementation(VectorDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private static final String TAG_VECTOR = "vector";
    private static final String TAG_CLIP_PATH = "clip-path";
    private static final String ATTR_FILL_TYPE = "fillType";
    private static final String ATTR_TRIM_PATH_START = "trimPathStart";
    private static final String ATTR_TRIM_PATH_END = "trimPathEnd";
    private static final String ATTR_TRIM_PATH_OFFSET = "trimPathOffset";
    private static final String ATTR_STROKE_LINE_CAP = "strokeLineCap";
    private static final String ATTR_STROKE_LINE_JOIN = "strokeLineJoin";
    private static final String ATTR_STROKE_MITER_LIMIT = "strokeMiterLimit";
    private static final String ATTR_AUTO_MIRRORED = "autoMirrored";
    private static final String ATTR_TINT_MODE = "tintMode";

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_VECTOR, TAG_CLIP_PATH, "path", "group", "gradient");
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String tag = element.getTagName();
        if (tag.equals(TAG_CLIP_PATH)) {
            report(context, element, null, "Raster image generation does not support `<clip-path>` elements");
        } else if (tag.equals("gradient")) {
            report(context, element, null, "Raster image generation does not support gradient fills");
        } else if (tag.equals("path")) {
            checkAttr(context, element, ATTR_FILL_TYPE, "fillType");
            checkAttr(context, element, ATTR_TRIM_PATH_START, "trimPathStart");
            checkAttr(context, element, ATTR_TRIM_PATH_END, "trimPathEnd");
            checkAttr(context, element, ATTR_TRIM_PATH_OFFSET, "trimPathOffset");
            checkAttr(context, element, ATTR_STROKE_LINE_CAP, "strokeLineCap");
            checkAttr(context, element, ATTR_STROKE_LINE_JOIN, "strokeLineJoin");
            checkAttr(context, element, ATTR_STROKE_MITER_LIMIT, "strokeMiterLimit");
        } else if (tag.equals(TAG_VECTOR)) {
            checkAttr(context, element, ATTR_AUTO_MIRRORED, "autoMirrored");
            checkAttr(context, element, ATTR_TINT_MODE, "tintMode");
        }
    }

    private void checkAttr(XmlContext context, Element element, String attrName, String displayName) {
        if (element.hasAttributeNS(ANDROID_URI, attrName)) {
            Attr attr = element.getAttributeNodeNS(ANDROID_URI, attrName);
            report(context, attr, "The attribute `android:" + displayName + "` is not supported when vector drawables are rasterized");
        }
    }
}
```

