        checkAttribute(context, element, ATTR_TRIM_PATH_START, VECTOR_DRAWABLE_GRADIENT_API);
        checkAttribute(context, element, ATTR_TRIM_PATH_END, VECTOR_DRAWABLE_GRADIENT_API);
