package com.android.tools.lint.checks;

import static com.android.SdkConstants.*;
import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;
import java.util.Arrays;
import java.util.Collection;

public class AndroidTvDetector extends Detector implements Detector.XmlScanner {

    public static final Issue IMPLIED_TOUCHSCREEN_HARDWARE = Issue.create(
            "ImpliedTouchscreenHardware",
            "Touchscreen not optional",
            "Apps require the `android.hardware.touchscreen` feature by default. If you want your app to be available on TV, you must also explicitly declare that a touchscreen is not required as follows:\n\n`<uses-feature android:name=\"android.hardware.touchscreen\" android:required=\"false\"/>`",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(AndroidTvDetector.class, Scope.MANIFEST_SCOPE));

    private static final String TOUCHSCREEN_FEATURE = "android.hardware.touchscreen";
    private static final String LEANBACK_FEATURE = "android.software.leanback";
    private static final String TELEVISION_FEATURE = "android.hardware.type.television";
    private static final String LEANBACK_CATEGORY = "android.intent.category.LEANBACK_LAUNCHER";

    private boolean mIsTvApp;
    private boolean mDeclaredOptional;
    private Element mManifestElement;

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(
                TAG_MANIFEST,
                TAG_APPLICATION,
                TAG_ACTIVITY,
                TAG_USES_FEATURE,
                TAG_INTENT_FILTER,
                TAG_CATEGORY);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String tag = element.getTagName();
        if (TAG_MANIFEST.equals(tag)) {
            mManifestElement = element;
        } else if (TAG_USES_FEATURE.equals(tag)) {
            String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
            if (TOUCHSCREEN_FEATURE.equals(name)) {
                String required = element.getAttributeNS(ANDROID_URI, ATTR_REQUIRED);
                // Default for required is true; explicit false means optional.
                if ("false".equals(required)) {
                    mDeclaredOptional = true;
                }
            } else if (LEANBACK_FEATURE.equals(name) || TELEVISION_FEATURE.equals(name)) {
                mIsTvApp = true;
            }
        } else if (TAG_APPLICATION.equals(tag)) {
            if (element.hasAttributeNS(ANDROID_URI, ATTR_BANNER)) {
                mIsTvApp = true;
            }
        } else if (TAG_CATEGORY.equals(tag)) {
            String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
            if (LEANBACK_CATEGORY.equals(name)) {
                mIsTvApp = true;
            }
        }
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        if (mIsTvApp && !mDeclaredOptional && mManifestElement != null) {
            context.report(IMPLIED_TOUCHSCREEN_HARDWARE,
                    mManifestElement,
                    context.getLocation(mManifestElement),
                    "Applications that run on TVs must declare that a touchscreen is not required");
        }
    }
}

