package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.ATTR_REQUIRED;
import static com.android.xml.AndroidManifest.NODE_USES_FEATURE;
import static com.android.xml.AndroidManifest.ANDROID_HARDWARE_TOUCHSCREEN;
import static com.android.xml.AndroidManifest.ANDROID_HARDWARE_TYPE_TELEVISION;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

public class AndroidTvDetector extends Detector implements Detector.XmlScanner {

    private static final Implementation IMPLEMENTATION = new Implementation(
            AndroidTvDetector.class,
            Scope.MANIFEST_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "ImpliedTouchscreenHardware",
            "Touchscreen not optional",
            "Apps require the `android.hardware.touchscreen` feature by default. If you want your "
                    + "app to be available on TV, you must also explicitly declare that a "
                    + "touchscreen is not required as follows:\n"
                    + "`<uses-feature android:name=\"android.hardware.touchscreen\" "
                    + "android:required=\"false\"/>`",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            IMPLEMENTATION)
            .addMoreInfo("https://developer.android.com/guide/topics/manifest/uses-feature-element.html");

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.XML;
    }

    @Override
    public void visitDocument(@NonNull XmlContext context) {
        Element root = context.document.getDocumentElement();
        if (root == null || !"manifest".equals(root.getTagName())) {
            return;
        }
        if (!isAndroidTvProject(context, root)) {
            return;
        }
        boolean declaredOptional = false;
        NodeList usesFeatures = root.getElementsByTagName(NODE_USES_FEATURE);
        for (int i = 0; i < usesFeatures.getLength(); i++) {
            Element element = (Element) usesFeatures.item(i);
            if (ANDROID_HARDWARE_TOUCHSCREEN.equals(element.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
                if (!Boolean.parseBoolean(element.getAttributeNS(ANDROID_URI, ATTR_REQUIRED))) {
                    declaredOptional = true;
                    break;
                }
            }
        }
        if (!declaredOptional) {
            context.report(ISSUE, root, context.getLocation(root),
                    "Apps that target Android TV must declare that a touchscreen is not required");
        }
    }

    private boolean isAndroidTvProject(@NonNull XmlContext context, @NonNull Element root) {
        // Check if the manifest declares TV support.
        NodeList usesFeatures = root.getElementsByTagName(NODE_USES_FEATURE);
        for (int i = 0; i < usesFeatures.getLength(); i++) {
            Element element = (Element) usesFeatures.item(i);
            String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
            if (ANDROID_HARDWARE_TYPE_TELEVISION.equals(name)) {
                return true;
            }
        }
        NodeList activities = root.getElementsByTagName("activity");
        for (int i = 0; i < activities.getLength(); i++) {
            Element activity = (Element) activities.item(i);
            NodeList intentFilters = activity.getElementsByTagName("intent-filter");
            for (int j = 0; j < intentFilters.getLength(); j++) {
                Element intentFilter = (Element) intentFilters.item(j);
                NodeList categories = intentFilter.getElementsByTagName("category");
                for (int k = 0; k < categories.getLength(); k++) {
                    Element category = (Element) categories.item(k);
                    if ("android.intent.category.LEANBACK_LAUNCHER".equals(
                            category.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}
```

