private boolean mHasOptional;

@Override public void beforeVisitRoot(XmlContext context, Element root) {
    mHasOptional = false;
}

@Override public List<String> getApplicableElements() { return Collections.singletonList("uses-feature"); }

@Override public void visitElement(XmlContext context, Element element) {
    String name = element.getAttributeNS(ANDROID_URI, SdkConstants.ATTR_NAME);
    if (!"android.hardware.touchscreen".equals(name)) return;
    String required = element.getAttributeNS(ANDROID_URI, SdkConstants.ATTR_REQUIRED);
    if ("false".equalsIgnoreCase(required)) {
        mHasOptional = true;
    }
}

@Override public void afterVisitRoot(XmlContext context, Element root) {
    if (!mHasOptional) {
        context.report(ISSUE, root, context.getLocation(root),
            "Touchscreen hardware is required by default; declare `<uses-feature android:name=\"android.hardware.touchscreen\" android:required=\"false\"/>` to support TV devices");
    }
}

