private boolean hasLeanbackLauncher(Element activity) {
    NodeList children = activity.getChildNodes();
    for (int i=0; i<children.getLength(); i++) {
        Node node = children.item(i);
        if (node.getNodeType() == Node.ELEMENT_NODE && TAG_INTENT_FILTER.equals(node.getNodeName())) {
            Element filter = (Element) node;
            boolean hasMain = false, hasLeanback = false;
            NodeList filterChildren = filter.getChildNodes();
            for (int j=0; j<filterChildren.getLength(); j++) {
                Node child = filterChildren.item(j);
                if (child.getNodeType() != Node.ELEMENT_NODE) continue;
                Element e = (Element) child;
                if (TAG_ACTION.equals(e.getNodeName())) {
                    String actionName = e.getAttributeNS(ANDROID_URI, ATTR_NAME);
                    if (ANDROID_INTENT_ACTION_MAIN.equals(actionName)) hasMain = true;
                } else if (TAG_CATEGORY.equals(e.getNodeName())) {
                    String catName = e.getAttributeNS(ANDROID_URI, ATTR_NAME);
                    if (ANDROID_INTENT_CATEGORY_LEANBACK_LAUNCHER.equals(catName)) hasLeanback = true;
                }
            }
            if (hasMain && hasLeanback) return true;
        }
    }
    return false;
}
