package com.android.tools.lint.checks;

import static com.android.AndroidConstants.*;
import com.android.SdkConstants;
import com.android.tools.lint.detector.api.*;
import org.jetbrains.annotations.NotNull;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import java.util.Collection;
import java.util.Collections;

public class AndroidTvDetector extends Detector implements XmlScanner {

    private static final String TV_FEATURE = "android.hardware.type.television";
    private static final String LEANBACK_CATEGORY = "android.intent.category.LEANBACK_LAUNCHER";

    public static final Issue ISSUE = Issue.create(
            "MissingLeanbackLauncher",
            "Missing Leanback Launcher intent filter",
            "Apps that run on TV devices must declare a launcher activity with the LEANBACK_LAUNCHER category.",
            Category.CORRECTNESS,
            8,
            Severity.WARNING,
            new Implementation(AndroidTvDetector.class, Scope.MANIFEST_SCOPE));

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(SdkConstants.TAG_MANIFEST);
    }

    @Override
    public void visitElement(@NotNull XmlContext context, @NotNull Element element) {
        boolean requiresTv = false;
        boolean hasLeanbackLauncher = false;

        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() != Node.ELEMENT_NODE) continue;

            if (SdkConstants.TAG_USES_FEATURE.equals(child.getLocalName())) {
                Element usesFeature = (Element) child;
                String name = usesFeature.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME);
                if (TV_FEATURE.equals(name)) {
                    String required = usesFeature.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_REQUIRED);
                    if (required.isEmpty() || SdkConstants.VALUE_TRUE.equals(required)) {
                        requiresTv = true;
                    }
                }
            } else if (SdkConstants.TAG_APPLICATION.equals(child.getLocalName())) {
                hasLeanbackLauncher = hasLeanbackLauncher((Element) child);
            }
        }

        if (requiresTv && !hasLeanbackLauncher) {
            context.report(ISSUE, element, context.getElementLocation(element),
                    "TV app should declare a launcher activity with CATEGORY_LEANBACK_LAUNCHER");
        }
    }

    private boolean hasLeanbackLauncher(Element application) {
        NodeList activities = application.getElementsByTagName(SdkConstants.TAG_ACTIVITY);
        for (int i = 0; i < activities.getLength(); i++) {
            Element activity = (Element) activities.item(i);
            NodeList filters = activity.getElementsByTagName(SdkConstants.TAG_INTENT_FILTER);
            for (int j = 0; j < filters.getLength(); j++) {
                Element filter = (Element) filters.item(j);
                NodeList categories = filter.getElementsByTagName(SdkConstants.TAG_CATEGORY);
                for (int k = 0; k < categories.getLength(); k++) {
                    Element category = (Element) categories.item(k);
                    if (LEANBACK_CATEGORY.equals(category.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME))) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

