        }
    }

    private static boolean hasLeanbackFeature(Element manifest) {
        NodeList features = manifest.getElementsByTagName(USES_FEATURE);
        for (int i = 0; i < features.getLength(); i++) {
            Node node = features.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element feature = (Element) node;
                String name = feature.getAttributeNS(ANDROID_NS, ATTR_NAME);
                if (name == null) {
                    name = feature.getAttribute(ATTR_NAME);
                }
                if (FEATURE_LEANBACK.equals(name)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isAndroidTvApp(Element manifest) {
        NodeList activities = manifest.getElementsByTagName("activity");
        if (!containsLeanbackLauncher(activities)) {
            NodeList aliases = manifest.getElementsByTagName("activity-alias");
            return containsLeanbackLauncher(aliases);
        }
        return true;
    }

    private static boolean containsLeanbackLauncher(NodeList components) {
        for (int i = 0; i < components.getLength(); i++) {
            Node node = components.item(i);
            if (node.getNodeType() != Node.ELEMENT_NODE) {
                continue;
            }
            Element component = (Element) node;
            NodeList filters = component.getElementsByTagName("intent-filter");
            for (int j = 0; j < filters.getLength(); j++) {
                Node filterNode = filters.item(j);
                if (filterNode.getNodeType() != Node.ELEMENT_NODE) {
                    continue;
                }
                Element filter = (Element) filterNode;
                NodeList categories = filter.getElementsByTagName("category");
                for (int k = 0; k < categories.getLength(); k++) {
                    Node categoryNode = categories.item(k);
                    if (categoryNode.getNodeType() != Node.ELEMENT_NODE) {
                        continue;
                    }
                    Element category = (Element) categoryNode;
                    String name = category.getAttributeNS(ANDROID_NS, ATTR_NAME);
                    if (name == null) {
                        name = category.getAttribute(ATTR_NAME);
                    }
                    if (CATEGORY_LEANBACK_LAUNCHER.equals(name)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}
