    return XmlScannerConstants.ALL;
}

@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    String tag = element.getTagName();
    FileData data = mFileData.get(context.getFile());
    if (data == null) {
        data = new FileData(context);
        mFileData.put(context.getFile(), data);
    }
    if (TAG_USES_FEATURE.equals(tag)) {
        if (LEANBACK_FEATURE.equals(element.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
            data.hasLeanbackFeature = true;
        }
    } else if (TAG_CATEGORY.equals(tag)) {
        if (LEANBACK_LAUNCHER_CATEGORY.equals(element.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
            data.hasLeanbackLauncher = true;
        }
    }
}

