                MISSING_LEANBACK_SUPPORT,
                data.context.getLocation(data.context.document.getDocumentElement()),
                "You must add `<uses-feature android:name=\"android.software.leanback\" android:required=\"false\" />` to the manifest for Android TV support."
            );
        }
    }
}

