package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.ATTR_REQUIRED;
import static com.android.SdkConstants.TAG_ACTIVITY;
import static com.android.SdkConstants.TAG_APPLICATION;
import static com.android.SdkConstants.TAG_INTENT_FILTER;
import static com.android.SdkConstants.TAG_MANIFEST;
import static com.android.SdkConstants.TAG_USES_FEATURE;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.LintFix;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Collection;
import java.util.Collections;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;

public class AndroidTvDetector extends Detector implements Detector.XmlScanner {

    public static final Issue MISSING_LEANBACK_SUPPORT = Issue.create(
            "MissingLeanbackSupport",
            "Missing Leanback Support",
            "The manifest should declare the use of the Leanback user interface required by Android TV. "
                    + "To fix this, add `<uses-feature android:name=\"android.software.leanback\" "
                    + "android:required=\"false\" />` to your manifest.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(AndroidTvDetector.class, Scope.MANIFEST_SCOPE))
            .addMoreInfo("https://developer.android.com/training/tv/start/start.html#leanback-req");

    private static final String LEANBACK_FEATURE = "android.software.leanback";
    private static final String LEANBACK_LAUNCHER_CATEGORY = "android.intent.category.LEANBACK_LAUNCHER";
    private static final String CATEGORY_TAG = "category";

    @Nullable
    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_MANIFEST);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        // Only check manifests that declare a leanback launcher activity
        if (!hasLeanbackLauncher(context, element)) {
            return;
        }

        // Look for existing leanback uses-feature
        Element[] usesFeatures = getUsesFeatures(element);
        for (Element usesFeature : usesFeatures) {
            if (LEANBACK_FEATURE.equals(usesFeature.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
                return;
            }
        }

        // Not found: report
        LintFix fix = fix()
                .replace()
                .text(">")
                .with(">\n    <uses-feature android:name=\"android.software.leanback\"\n        android:required=\"false\" />")
                .build();

        context.report(MISSING_LEANBACK_SUPPORT, element, context.getLocation(element),
                "Missing `android.software.leanback` uses-feature declaration required by Android TV",
                fix);
    }

    private boolean hasLeanbackLauncher(@NonNull XmlContext context, @NonNull Element manifest) {
        Element application = getChildElement(manifest, TAG_APPLICATION);
        if (application == null) {
            return false;
        }
        for (Element activity : getChildElements(application, TAG_ACTIVITY)) {
            for (Element intentFilter : getChildElements(activity, TAG_INTENT_FILTER)) {
                for (Element category : getChildElements(intentFilter, CATEGORY_TAG)) {
                    if (LEANBACK_LAUNCHER_CATEGORY.equals(category.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private Element[] getUsesFeatures(@NonNull Element manifest) {
        return getChildElements(manifest, TAG_USES_FEATURE);
    }

    @Nullable
    private Element getChildElement(@NonNull Element parent, @NonNull String tagName) {
        for (Element child : getChildElements(parent, tagName)) {
            return child;
        }
        return null;
    }

    @NonNull
    private Element[] getChildElements(@NonNull Element parent, @NonNull String tagName) {
        // Use NodeList filtering
        org.w3c.dom.NodeList children = parent.getChildNodes();
        java.util.List<Element> result = new java.util.ArrayList<>();
        for (int i = 0, n = children.getLength(); i < n; i++) {
            org.w3c.dom.Node child = children.item(i);
            if (child.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE
                    && tagName.equals(child.getNodeName())) {
                result.add((Element) child);
            }
        }
        return result.toArray(new Element[0]);
    }
}
