private boolean hasLeanbackLauncher(@NonNull Element manifest) {
    Element application = getChildByTag(manifest, TAG_APPLICATION);
    if (application == null) return false;
    for (Element activity : getChildrenByTag(application, TAG_ACTIVITY)) {
        for (Element intentFilter : getChildrenByTag(activity, TAG_INTENT_FILTER)) {
            for (Element category : getChildrenByTag(intentFilter, "category")) {
                String name = category.getAttributeNS(ANDROID_URI, ATTR_NAME);
                if (LEANBACK_LAUNCHER_CATEGORY.equals(name)) {
                    return true;
                }
            }
        }
    }
    return false;
}

private boolean hasLeanbackFeature(@NonNull Element manifest) {
    for (Element child : getChildrenByTag(manifest, TAG_USES_FEATURE)) {
        String name = child.getAttributeNS(ANDROID_URI, ATTR_NAME);
        if (LEANBACK_FEATURE.equals(name)) {
            return true;
        }
    }
    return false;
}
