public final class AndroidTvDetector extends Detector implements XmlScanner {
    private static final String LEANBACK_FEATURE = "android.software.leanback";
    private static final String TAG_USES_FEATURE = "uses-feature";
    private static final String TAG_MANIFEST = "manifest";
    private static final String ATTR_NAME = "name";
    private static final String ANDROID_NS = "http://schemas.android.com/apk/res/android";

    public static final Issue ISSUE = Issue.create(
        "MissingLeanbackSupport",
        "Missing Leanback Support",
        "The manifest should declare the use of the Leanback user interface required by Android TV. "
            + "To fix this, add `<uses-feature android:name=\"android.software.leanback\" android:required=\"false\" />` to your manifest.",
        Category.CORRECTNESS,
        5,
        Severity.WARNING,
        new Implementation(AndroidTvDetector.class, Scope.MANIFEST_SCOPE)
    );

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_MANIFEST);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        NodeList features = element.getElementsByTagName(TAG_USES_FEATURE);
        boolean found = false;
        for (int i = 0, n = features.getLength(); i < n; i++) {
            Element feature = (Element) features.item(i);
            String name = feature.getAttributeNS(ANDROID_NS, ATTR_NAME);
            if (name.isEmpty()) {
                name = feature.getAttribute(ATTR_NAME);
            }
            if (LEANBACK_FEATURE.equals(name)) {
                found = true;
                break;
            }
        }
        if (!found) {
            context.report(ISSUE, element, context.getLocation(element),
                "Missing `uses-feature` declaration for Leanback support");
        }
    }
}

