package com.android.tools.lint.checks;

import com.android.SdkConstants;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Arrays;
import java.util.Collection;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

public class AndroidTvDetector extends Detector implements Detector.XmlScanner {

    private static final String LEANBACK_LAUNCHER = "android.intent.category.LEANBACK_LAUNCHER";
    private static final String ACTION_MAIN = "android.intent.action.MAIN";

    public static final Issue ISSUE = Issue.create(
            "MissingTvBanner",
            "Missing TV Banner",
            "A TV application that includes a Leanback launcher intent filter must provide a "
                    + "home screen banner. The banner is the app launch point that appears on the "
                    + "home screen in the apps and games rows. Add `android:banner` to the "
                    + "`<application>` element, typically with a reference to an `xhdpi` drawable.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(AndroidTvDetector.class, Scope.MANIFEST_SCOPE))
            .addMoreInfo("https://developer.android.com/training/tv/start/start.html#banner");

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(SdkConstants.TAG_APPLICATION);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (!SdkConstants.TAG_APPLICATION.equals(element.getTagName())) {
            return;
        }

        if (element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_BANNER)) {
            return;
        }

        NodeList activities = element.getElementsByTagName(SdkConstants.TAG_ACTIVITY);
        for (int i = 0; i < activities.getLength(); i++) {
            Element activity = (Element) activities.item(i);
            if (isLeanbackLauncher(activity)) {
                context.report(
                        ISSUE,
                        element,
                        context.getLocation(element),
                        "Missing TV banner: the application declares a Leanback launcher "
                                + "intent filter but does not declare an `android:banner` attribute.");
                return;
            }
        }
    }

    private static boolean isLeanbackLauncher(Element activity) {
        NodeList filters = activity.getElementsByTagName(SdkConstants.TAG_INTENT_FILTER);
        for (int i = 0; i < filters.getLength(); i++) {
            Element filter = (Element) filters.item(i);
            if (hasAction(filter, ACTION_MAIN) && hasCategory(filter, LEANBACK_LAUNCHER)) {
                return true;
            }
        }
        return false;
    }

    private static boolean hasAction(Element filter, String actionName) {
        return hasChildWithNameAttribute(filter, SdkConstants.TAG_ACTION, actionName);
    }

    private static boolean hasCategory(Element filter, String categoryName) {
        return hasChildWithNameAttribute(filter, SdkConstants.TAG_CATEGORY, categoryName);
    }

    private static boolean hasChildWithNameAttribute(Element parent, String tag, String value) {
        NodeList children = parent.getElementsByTagName(tag);
        for (int i = 0; i < children.getLength(); i++) {
            Element child = (Element) children.item(i);
            if (value.equals(child.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME))) {
                return true;
            }
        }
        return false;
    }
}
