public class AndroidTvDetector extends Detector implements XmlScanner {
    public static final Issue MISSING_BANNER = Issue.create(
            id="MissingTvBanner",
            briefDescription="TV Missing Banner",
            explanation="...",
            category=Category.TV,
            priority=5,
            severity=Severity.WARNING,
            implementation=new Implementation(AndroidTvDetector.class, Scope.MANIFEST_SCOPE));

    private static final String LEANBACK_LAUNCHER = "android.intent.category.LEANBACK_LAUNCHER";

    @Override public Collection<String> getApplicableElements() { return Collections.singletonList(SdkConstants.TAG_APPLICATION); }

    @Override public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        boolean isLeanback = false;
        NodeList activities = element.getElementsByTagName(SdkConstants.TAG_ACTIVITY);
        for (int i=0;i<activities.getLength();i++) {
            Element activity = (Element) activities.item(i);
            NodeList filters = activity.getElementsByTagName(SdkConstants.TAG_INTENT_FILTER);
            for (int j=0;j<filters.getLength();j++) {
                Element filter = (Element) filters.item(j);
                NodeList categories = filter.getElementsByTagName(SdkConstants.TAG_CATEGORY);
                for (int k=0;k<categories.getLength();k++) {
                    Element category = (Element) categories.item(k);
                    if (LEANBACK_LAUNCHER.equals(category.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME))) {
                        isLeanback = true;
                        break;
                    }
                }
            }
        }
        if (isLeanback && !element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_BANNER)) {
            context.report(ISSUE, element, context.getLocation(element), "...");
        }
    }
}

