   @Override public Collection<String> getApplicableElements() { return Arrays.asList(TAG_USES_PERMISSION, TAG_USES_FEATURE); }

   @Override public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
       String tag = element.getTagName();
       if (TAG_USES_FEATURE.equals(tag)) {
           String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
           if (name.isEmpty()) return;
           String required = element.getAttributeNS(ANDROID_URI, ATTR_REQUIRED);
           if ("false".equalsIgnoreCase(required)) {
               mNotRequiredFeatures.add(name);
           }
       } else if (TAG_USES_PERMISSION.equals(tag)) {
           String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
           if (name.isEmpty()) return;
           List<String> features = PERMISSION_TO_FEATURES.get(name);
           if (features != null) {
               mPermissions.add(new Pair<>(element, name));
           }
       }
   }

   @Override public void afterCheckFile(@NonNull Context context) {
       for (Pair<Element,String> pair : mPermissions) {
           List<String> features = PERMISSION_TO_FEATURES.get(pair.getSecond());
           boolean missing = false;
           StringBuilder sb = new StringBuilder();
           for (String feature : features) {
               if (!mNotRequiredFeatures.contains(feature)) {
                   missing = true;
                   if (sb.length() > 0) sb.append(", ");
                   sb.append(feature);
               }
           }
           if (missing) {
               // report on element
               context.report(ISSUE, pair.getFirst(), context.getLocation(pair.getFirst()),
                   "Permission `" + pair.getSecond() + "` implies hardware feature(s) `" + sb + "` which may not be supported on TVs. Consider adding `<uses-feature android:name=\"...\" android:required=\"false\" />`.");
           }
       }
   }

