@Override
public void visitDocument(@NonNull XmlContext context, @NonNull Document document) {
    // Gather uses-feature declarations
    Map<String, Boolean> features = new HashMap<>();
    NodeList featureNodes = document.getElementsByTagName(SdkConstants.TAG_USES_FEATURE);
    for (int i = 0; i < featureNodes.getLength(); i++) {
        Element element = (Element) featureNodes.item(i);
        String name = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME);
        if (name.isEmpty()) continue;
        String required = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_REQUIRED);
        // if any declaration says required=false, treat as not required
        if ("false".equals(required)) {
            features.put(name, Boolean.FALSE);
        } else if (!features.containsKey(name)) {
            features.put(name, Boolean.TRUE);
        }
    }

    NodeList permissionNodes = document.getElementsByTagName(SdkConstants.TAG_USES_PERMISSION);
    for (int i=0; i<permissionNodes.getLength(); i++) {
        Element element = (Element) permissionNodes.item(i);
        String name = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_NAME);
        String feature = PERMISSION_TO_FEATURE.get(name);
        if (feature == null) continue;
        Boolean required = features.get(feature);
        if (required == null || required) {
            context.report(ISSUE_PERMISSION_IMPLIES_UNSUPPORTED_HARDWARE, element, context.getLocation(element),
                String.format("Permission `%1$s` implies `%2$s`, a hardware feature not supported on Android TV; declare `<uses-feature android:name=\"%2$s\" android:required=\"false\" />`", name, feature));
        }
    }
}

