@Override
public Collection<String> getApplicableElements() {
    return Collections.singletonList(TAG_USES_PERMISSION);
}

@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    String permission = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
    if (permission.isEmpty()) {
        return;
    }
    String feature = getImpliedFeature(permission);
    if (feature == null) {
        return;
    }
    if (hasExplicitFeatureDeclaration(context.document.getDocumentElement(), feature, false)) {
        return;
    }
    String message = String.format(
        "Permission '%1$s' implies feature '%2$s', which is not supported on Android TV devices. "
        + "Consider explicitly declaring `%3$s` with `android:required=\"false\"`.",
        permission, feature, feature);
    context.report(PERMISSION_IMPLIES_UNSUPPORTED_HARDWARE, element, context.getLocation(element), message);
}
```

