Implementation of hasDeclaredNonRequiredFeature:
private boolean hasDeclaredFeature(@NonNull Document document, @NonNull String feature) {
    NodeList features = document.getElementsByTagName(TAG_USES_FEATURE);
    for (int i=0; i<features.getLength(); i++) {
        Node node = features.item(i);
        if (node.getNodeType() == Node.ELEMENT_NODE) {
            Element e = (Element) node;
            if (feature.equals(e.getAttributeNS(ANDROID_URI, ATTR_NAME))) {
                String required = e.getAttributeNS(ANDROID_URI, ATTR_REQUIRED);
                if ("false".equals(required)) {
                    return true;
                }
            }
        }
    }
    return false;
}

