import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.ATTR_REQUIRED;
import static com.android.SdkConstants.TAG_USES_FEATURE;

import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import com.android.utils.XmlUtils;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import org.w3c.dom.Element;

public class AndroidTvDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
        "UnsupportedTvHardware",
        "Unsupported TV hardware feature requested",
        "The `<uses-feature>` element should not require this unsupported TV hardware feature. ...",
        Category.CORRECTNESS,
        5,
        Severity.WARNING,
        new Implementation(AndroidTvDetector.class, Scope.MANIFEST_SCOPE)
    );

    private static final Set<String> UNSUPPORTED_FEATURES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        "android.hardware.touchscreen",
        "android.hardware.faketouch",
        "android.hardware.faketouch.multitouch.distinct",
        "android.hardware.faketouch.multitouch.jazzhand",
        "android.hardware.telephony",
        "android.hardware.camera",
        "android.hardware.camera.autofocus",
        "android.hardware.camera.flash",
        "android.hardware.camera.front",
        "android.hardware.nfc",
        "android.hardware.location.gps",
        "android.hardware.microphone",
        "android.hardware.sensor.accelerometer",
        "android.hardware.sensor.barometer",
        "android.hardware.sensor.compass",
        "android.hardware.sensor.gyroscope",
        "android.hardware.sensor.light",
        "android.hardware.sensor.proximity",
        "android.hardware.sensor.stepcounter",
        "android.hardware.sensor.stepdetector",
        "android.hardware.screen.portrait"
    )));

    @Override
    public Collection<String> getApplicableElements() { return Collections.singletonList(TAG_USES_FEATURE); }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
        if (name == null || name.isEmpty()) return;
        if (!UNSUPPORTED_FEATURES.contains(name)) return;
        String required = element.getAttributeNS(ANDROID_URI, ATTR_REQUIRED);
        if ("false".equals(required)) return;
        context.report(ISSUE, element, context.getLocation(element), "The feature \"" + name + "\" is not supported on TV devices and should be marked with `required=\"false\"`, or removed.");
    }
}

