public class DuplicateResourceDetector extends Detector implements ResourceFolderScanner {

    public static final Issue ISSUE = Issue.create(
        "DuplicateDefinition",
        "Duplicate definitions of resources",
        "You can define a resource multiple times in different resource folders; that's how string translations are done, for example. However, defining the same resource more than once in the same resource folder is likely an error, for example attempting to add a new resource without realizing that the name is already used, and so on.",
        Category.CORRECTNESS,
        7,
        Severity.WARNING,
        new Implementation(DuplicateResourceDetector.class, Scope.RESOURCE_FOLDER_SCOPE)
    );

    private static final String VALUES_PREFIX = "values";

    @Override
    public boolean appliesTo(@NotNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public void checkFolder(@NotNull ResourceContext context, @NotNull File folder) {
        File[] files = folder.listFiles();
        if (files == null) return;
        // map from resource key to first occurrence location
        Map<String, Location> seen = new HashMap<>();
        for (File file : files) {
            if (!file.isFile() || !file.getName().endsWith(".xml")) continue;
            checkXmlFile(context, file, seen);
        }
    }

    private void checkXmlFile(ResourceContext context, File file, Map<String, Location> seen) {
        try (InputStream is = new BufferedInputStream(new FileInputStream(file))) {
            XMLInputFactory factory = XMLInputFactory.newInstance();
            // secure factory
            factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
            factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);
            XMLStreamReader reader = factory.createXMLStreamReader(is);
            while (reader.hasNext()) {
                int event = reader.next();
                if (event == XMLStreamConstants.START_ELEMENT) {
                    String localName = reader.getLocalName();
                    if (localName.equals("resources")) {
                        // root; children are resources
                        continue;
                    }
                    String name = reader.getAttributeValue(null, "name");
                    if (name == null || name.isEmpty()) continue;
                    String type = localName;
                    if (localName.equals("item")) {
                        String itemType = reader.getAttributeValue(null, "type");
                        if (itemType == null || itemType.isEmpty()) continue;
                        type = itemType;
                    }
                    String key = type + "/" + name;
                    int line = reader.getLocation().getLineNumber();
                    Location location = Location.create(file, new DefaultPosition(line, -1, line));
                    Location previous = seen.get(key);
                    if (previous != null) {
                        String message = String.format("Duplicate resource definition for `%1$s` (%2$s)", name, key);
                        Incident incident = new Incident(ISSUE, context.getProject(), location, message);
