import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceFolderType;
import com.android.resources.ResourceType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceFolderScanner;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;

import java.io.File;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class DuplicateResourceDetector extends Detector implements ResourceFolderScanner, XmlScanner {

    private static final String ISSUE_ID = "DuplicateDefinition";
    public static final Issue DUPLICATE_DEFINITION = Issue.create(
            ISSUE_ID,
            "Duplicate definitions of resources",
            "You can define a resource multiple times in different resource folders; that's how string translations are done, for example. However, defining the same resource more than once in the same resource folder is likely an error, for example attempting to add a new resource without realizing that the name is already used, and so on.",
            Category.CORRECTNESS,
            7,
            Severity.ERROR,
            new Implementation(DuplicateResourceDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private Map<String, Location> mSeen;

    public DuplicateResourceDetector() {
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return true;
    }

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        mSeen = new HashMap<>();
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        mSeen = null;
    }

    @Override
    public void checkFolder(@NonNull Context context, @NonNull ResourceFolderType folderType, @NonNull File folder) {
        if (folderType == ResourceFolderType.VALUES) {
            return; // handled by XML scanner
        }
        Map<String, File> seen = new HashMap<>();
        File[] files = folder.listFiles();
        if (files == null) return;
        for (File file : files) {
            if (file.isDirectory()) continue;
            String name = file.getName();
            if (name.startsWith(".")) continue;
            int dot = name.indexOf('.');
