    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        ResourceFolderType folderType = context.getResourceFolderType();
        if (folderType != ResourceFolderType.VALUES) {
            return;
        }
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_NAME) && !element.hasAttribute(ATTR_NAME)) {
            return;
        }
        Node parent = element.getParentNode();
        if (parent == null || parent.getNodeType() != Node.ELEMENT_NODE
                || !TAG_RESOURCES.equals(parent.getNodeName())) {
            return;
        }
        String type = element.getTagName();
        String name = element.getAttribute(ATTR_NAME);
        if (name.isEmpty()) {
            name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
        }
        if (name.isEmpty()) return;

        File folder = context.file.getParentFile();
        String key = folder.getPath() + "/" + type + "/" + name;
        Location first = mSeen.get(key);
        Location current = context.getLocation(element);
        if (first == null) {
            mSeen.put(key, current);
        } else {
            current.setSecondary(first);
            context.report(DUPLICATE_DEFINITION, element,
                    context.getLocation(element),
                    String.format("`%1$s` has already been defined in this values folder", name),
                    null);
        }
    }

    private static final String TAG_RESOURCES = "resources";
    private static final String ATTR_NAME = "name";
    private static final String ANDROID_URI = "http://schemas.android.com/apk/res/android";
}
