public void visitDocument(@NonNull XmlContext context) {
    Document document = context.document;
    Element root = document.getDocumentElement();
    if (root == null) return;
    ResourceFolderType folderType = context.getResourceFolderType();
    if (folderType == null) return;
    File folder = context.file.getParentFile();
    String folderPath = folder.getAbsolutePath();
    if (folderType == ResourceFolderType.VALUES) {
        NodeList children = root.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node node = children.item(i);
            if (node.getNodeType() != Node.ELEMENT_NODE) continue;
            Element child = (Element) node;
            String tag = child.getTagName();
            if ("eat-comment".equals(tag) || "skip".equals(tag)) continue;
            String name = child.getAttributeNS(ANDROID_URI, "name");
