package com.android.tools.lint.checks;

import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.ATTR_TYPE;
import static com.android.SdkConstants.TAG_RESOURCES;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Incident;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.utils.SdkUtils;
import com.google.common.collect.ArrayListMultimap;
import com.google.common.collect.ListMultimap;
import com.google.common.collect.Maps;
import java.io.File;
import java.util.List;
import java.util.Map;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class DuplicateResourceDetector extends Detector implements XmlScanner {

    private static final Implementation IMPLEMENTATION = new Implementation(
            DuplicateResourceDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue DUPLICATE_DEFINITION = Issue.create(
            "DuplicateDefinition",
            "Duplicate definitions of resources",
            "You can define a resource multiple times in different resource folders; that's how "
                    + "string translations are done, for example. However, defining the same "
                    + "resource more than once in the same resource folder is likely an error.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            IMPLEMENTATION);

    private final Map<String, ListMultimap<String, Location>> mLocations = Maps.newHashMap();

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Node parent = element.getParentNode();
        if (parent == null || parent.getNodeType() != Node.ELEMENT_NODE
                || !TAG_RESOURCES.equals(parent.getLocalName())) {
            return;
        }

        String tag = element.getLocalName();
        if (tag == null) {
            return;
        }

        String type;
        if (TAG_ITEM.equals(tag)) {
            type = element.getAttribute(ATTR_TYPE);
            if (type == null || type.isEmpty()) {
                return;
            }
        } else if ("skip".equals(tag) || "eat-comment".equals(tag)) {
            return;
        } else {
            type = tag;
        }

        String name = element.getAttribute(ATTR_NAME);
        if (name == null || name.isEmpty()) {
            return;
        }

        File folder = context.file.getParentFile();
        String folderPath = folder != null ? folder.getPath() : context.file.getPath();

        String key = type + "/" + name;
        ListMultimap<String, Location> map = mLocations.get(folderPath);
        if (map == null) {
            map = ArrayListMultimap.create();
            mLocations.put(folderPath, map);
        }

        map.put(key, context.getNameLocation(element));
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        for (Map.Entry<String, ListMultimap<String, Location>> folderEntry : mLocations.entrySet()) {
            ListMultimap<String, Location> map = folderEntry.getValue();
            for (Map.Entry<String, List<Location>> entry : map.asMap().entrySet()) {
                List<Location> locations = entry.getValue();
                if (locations.size() < 2) {
                    continue;
                }
                String[] parts = entry.getKey().split("/", 2);
                String type = parts[0];
                String name = parts[1];

                Location first = locations.get(0);
                for (int i = 1; i < locations.size(); i++) {
                    Location location = locations.get(i);
                    Location secondary = Location.create(first.getFile(), first.getStart(), first.getEnd());
                    location.setSecondary(secondary);

                    String message = String.format(
                            "`R.%s.%s` has already been defined in this resource folder",
                            type, name);
                    context.report(new Incident(DUPLICATE_DEFINITION, location, message));
                }
            }
        }
    }
}
```

