@Override
public void checkFolder(@NonNull Context context, @NonNull File folder) {
    File[] files = folder.listFiles();
    if (files == null) {
        return;
    }

    Map<String, List<File>> baseNames = Maps.newHashMap();
    for (File file : files) {
        if (file.isDirectory()) {
            continue;
        }
        String name = file.getName();
        int dot = name.lastIndexOf('.');
        String base = dot > 0 ? name.substring(0, dot) : name;
        List<File> list = baseNames.get(base);
        if (list == null) {
            list = new ArrayList<>();
            baseNames.put(base, list);
        }
        list.add(file);
    }

    for (Map.Entry<String, List<File>> entry : baseNames.entrySet()) {
        List<File> list = entry.getValue();
        if (list.size() > 1) {
            Location first = Location.create(list.get(0));
            Location location = first;
            for (int i = 1; i < list.size(); i++) {
                location.setSecondary(Location.create(list.get(i)));
                location = location.getSecondary();
            }
            context.report(ISSUE, first,
                    "Duplicate resource `@" + entry.getKey() + "` in " + folder.getName());
        }
    }
}
