package com.android.tools.lint.checks;

import static com.android.SdkConstants.*;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceFolderType;
import com.android.resources.ResourceType; // maybe
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class DuplicateResourceDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
        "ReferenceType",
        "Incorrect reference type",
        "When creating a resource alias, the referenced resource must be the same type as the alias.",
        Category.CORRECTNESS,
        6,
        Severity.ERROR,
        new Implementation(DuplicateResourceDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_ITEM);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String typeAttr = element.getAttribute(ATTR_TYPE);
        if (typeAttr == null || typeAttr.isEmpty()) return;
        Node firstChild = element.getFirstChild();
        if (firstChild == null) return;
        String value = firstChild.getNodeValue();
        if (value == null) return;
        value = value.trim();
        if (value.isEmpty()) return;
        String refType = getReferenceType(value);
        if (refType == null) return;
        if (!refType.equals(typeAttr)) {
            context.report(ISSUE, element, context.getLocation(element), 
                String.format("Expected reference type `@%1$s/...` to match alias type `%1$s`, but was `@%2$s/...`", typeAttr, refType));
        }
    }

    private static String getReferenceType(String reference) {
        if (!reference.startsWith("@")) return null;
        int slash = reference.indexOf('/');
        if (slash < 0) return null;
        String before = reference.substring(1, slash);
        int colon = before.indexOf(':');
        if (colon >= 0) {
            before = before.substring(colon + 1);
        }
        if (before.isEmpty()) return null;
        if (before.startsWith("+")) {
            before = before.substring(1);
        }
        return before;
    }
}

