override fun createUastHandler(context: JavaContext): UElementHandler {
    return object : UElementHandler() {
        override fun visitReferenceExpression(node: UReferenceExpression) {
            val target = node.resolve()
            val qName = when (target) {
                is PsiClass -> target.qualifiedName
                is PsiMember -> target.containingClass?.qualifiedName
                else -> null
            }
            check(node, qName)
        }

        override fun visitTypeReferenceExpression(node: UTypeReferenceExpression) {
            val type = node.type
            val qName = if (type is PsiClassType) type.resolve()?.qualifiedName else type.canonicalText
            check(node, qName)
        }

        override fun visitCallExpression(node: UCallExpression) {
            val method = node.resolve()
            val qName = method?.containingClass?.qualifiedName
            check(node, qName)
        }

        override fun visitImportStatement(node: UImportStatement) {
            val ref = node.importReference
            val qName = ref?.asSourceString()
            check(node, qName)
        }

        private fun check(node: UElement, qName: String?) {
            if (qName == null) return
            if (OLD_FE10_CLASSES.any { qName == it || qName.startsWith("$it.") }) {
                report(node, qName)
            } else if (OLD_FE10_PACKAGES.any { qName.startsWith(it) }) {
                report(node, qName)
            }
        }

        private fun report(node: UElement, qName: String) {
            context.report(ISSUE, node, context.getLocation(node), "Avoid using old K1 Kotlin compiler API: $qName")
        }
    }
}

