private static boolean isNegative(String value) {
    if (value == null || value.isEmpty()) {
        return false;
    }
    int i = 0;
    int n = value.length();
    if (value.charAt(i) == '+' || value.charAt(i) == '-') {
        i++;
    }
    if (i >= n) {
        return false;
    }
    int start = i;
    while (i < n && (Character.isDigit(value.charAt(i)) || value.charAt(i) == '.')) {
        i++;
    }
    if (start == i) {
        return false;
    }
    try {
        double d = Double.parseDouble(value.substring(0, i));
        return d < 0;
    } catch (NumberFormatException e) {
        return false;
    }
}
```

