    private static boolean isInMarginNamespace(@NonNull Attr attribute) {
        String namespace = attribute.getNamespaceURI();
        return ANDROID_URI.equals(namespace);
    }

    private static boolean isNegativeDimension(@NonNull String value) {
        if (!Character.isDigit(value.charAt(0)) && value.charAt(0) != '-') {
            return false;
        }

        int index = 0;
        if (value.charAt(0) == '-') {
            index = 1;
        }

        if (index >= value.length()) {
            return false;
        }

        // skip digits and decimal point
        while (index < value.length()) {
            char c = value.charAt(index);
            if (Character.isDigit(c) || c == '.') {
                index++;
            } else {
                break;
            }
        }

        if (index == 0 || index == value.length()) {
            return false;
        }

        // check for dimension unit
        String unit = value.substring(index);
        if (!unit.equals("dp") && !unit.equals("dip") && !unit.equals("sp")
                && !unit.equals("px") && !unit.equals("pt") && !unit.equals("in")
                && !unit.equals("mm")) {
            return false;
        }

        return value.startsWith("-");
    }
