private static boolean isNegativeDimension(@NonNull String value) {
    if (!value.startsWith("-")) {
        return false;
    }
    String rest = value.substring(1);
    // rest should be like "5dp"
    if (rest.isEmpty()) return false;
    int i = 0;
    boolean dotSeen = false;
    while (i < rest.length()) {
        char c = rest.charAt(i);
        if (c >= '0' && c <= '9') {
            i++;
        } else if (c == '.' && !dotSeen) {
            dotSeen = true;
            i++;
        } else {
            break;
        }
    }
    if (i == 0) return false;
    String unit = rest.substring(i);
    return isDimensionUnit(unit);
}

private static boolean isDimensionUnit(String unit) {
    return unit.equals("dp") || unit.equals("dip") || unit.equals("sp")
            || unit.equals("px") || unit.equals("pt") || unit.equals("in")
            || unit.equals("mm");
}
