package com.android.tools.lint.checks;

import com.android.tools.lint.detector.api.*;
import com.intellij.psi.PsiMethod;
import org.jetbrains.uast.*;

public class PowerManagerDetector extends Detector implements Detector.UastScanner {
    public static final Issue ISSUE = Issue.create(
        "InvalidWakeLockTag",
        "Invalid Wake Lock Tag",
        "Wake Lock tags must follow the PowerManager naming conventions: they must be non-empty, "
            + "must not contain spaces or ':' characters, and should typically be a class name.",
        Category.CORRECTNESS,
        5,
        Severity.WARNING,
        new Implementation(PowerManagerDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Override
    public List<String> getApplicableMethodNames() {
        return Collections.singletonList("newWakeLock");
    }

    @Override
    public void visitMethodCall(@NonNull JavaContext context, @NonNull UCallExpression call, @NonNull PsiMethod method) {
        if (!context.getEvaluator().isMemberInClass(method, "android.os.PowerManager")) {
            return;
        }
        List<UExpression> args = call.getValueArguments();
        if (args.size() != 2) return;
        UExpression tagArg = args.get(1);
        Object value = ConstantEvaluator.evaluate(context, tagArg);
        if (!(value instanceof String)) {
            return;
        }
        String tag = (String) value;
        if (tag.isEmpty()) {
            context.report(ISSUE, tagArg, context.getLocation(tagArg), "Wake lock tag must not be empty");
            return;
        }
        if (tag.length() > 100) {
            context.report(...);
            return;
        }
        if (!isValidWakeLockTag(tag)) {
            context.report(...);
        }
    }

    private static boolean isValidWakeLockTag(String tag) {
        for (int i = 0; i < tag.length(); i++) {
            char c = tag.charAt(i);
            if (c == ':' || Character.isWhitespace(c)) return false;
            if (!Character.isLetterOrDigit(c) && c != '.' && c != '_' && c != '$') return false;
        }
        return true;
    }
}
