package com.android.tools.lint.checks

import com.android.tools.lint.client.api.UElementHandler
import com.android.tools.lint.detector.api.*

class ReturnThisDetector : Detector(), SourceCodeScanner {
    override fun getApplicableUastTypes() = listOf(UMethod::class.java)
    override fun createUastHandler(context: JavaContext) = object : UElementHandler() {
        override fun visitMethod(node: UMethod) {
            // skip static, abstract, native, interface methods?
            if (node.isConstructor || node.hasModifierProperty(PsiModifier.ABSTRACT) || node.hasModifierProperty(PsiModifier.NATIVE)) return
            val superMethods = node.findSuperMethods()
            if (!superMethods.any { it.hasAnnotation(RETURN_THIS_ANNOTATION) } && !node.hasAnnotation(RETURN_THIS_ANNOTATION)) return
            if (!returnsThis(node)) {
                context.report(ISSUE, node, context.getNameLocation(node), "Method must return `this` because it overrides a method annotated with @ReturnThis")
            }
        }
    }
    private fun returnsThis(method: UMethod): Boolean {
        val body = method.uastBody ?: return false
        // Check all return statements
        var allReturnThis = true
        var hasReturn = false
        body.accept(object : AbstractUastVisitor() {
            override fun visitReturnExpression(node: UReturnExpression): Boolean {
                hasReturn = true
                val returnValue = node.returnExpression
                if (returnValue != null && !isThis(returnValue)) {
                    allReturnThis = false
                }
                return super.visitReturnExpression(node)
            }
        })
        // If method is non-void and no explicit return, false
        return hasReturn && allReturnThis
    }
    private fun isThis(expression: UExpression): Boolean {
        return expression is UThisExpression || (expression is UReferenceExpression && expression.resolvedName == "this") // less needed
    }
    companion object {
        private const val RETURN_THIS_ANNOTATION = "ReturnThis"
        @JvmField
        val ISSUE = Issue.create(
            id = "ReturnThis",
            briefDescription = "Method should return this",
            explanation = """
                Methods annotated with `@ReturnThis` (or overriding a method annotated with \
                `@ReturnThis`) must return `this` to allow method chaining.
            """,
            category = Category.CORRECTNESS,
            priority = 4,
            severity = Severity.WARNING,
            implementation = Implementation(ReturnThisDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )
    }
}

