```kotlin
package com.android.tools.lint.checks

import com.android.tools.lint.client.api.UElementHandler
import com.android.tools.lint.detector.api.*
import com.intellij.psi.PsiMethod
import org.jetbrains.uast.*

@Suppress("UnstableApiUsage")
class ReturnThisDetector : Detector(), SourceCodeScanner {

    override fun getApplicableUastTypes(): List<Class<out UElement>>? {
        return listOf(UMethod::class.java)
    }

    override fun createUastHandler(context: JavaContext): UElementHandler? {
        return object : UElementHandler() {
            override fun visitMethod(node: UMethod) {
                if (node.isConstructor) return
                if (node.body == null) return

                val evaluator = context.evaluator
                val containingClass = node.javaPsi.containingClass ?: return
                val superMethods = evaluator.getSuperMethods(node, containingClass)

                val hasReturnThisAnnotation = superMethods.any { superMethod ->
                    evaluator.getAllAnnotations(superMethod, true).any { annotation ->
                        annotation.qualifiedName == "ReturnThis"
                    }
                }

                if (!hasReturnThisAnnotation) return

                // Check that the method returns this
                val returnThis = node.findReturnThis()
                if (returnThis == null) {
                    context.report(
                        ISSUE,
                        node,
                        context.getLocation(node),
                        "Method must return `this` because it overrides a method annotated with @ReturnThis"
                    )
                }
            }
        }
    }

    private fun UMethod.findReturnThis(): UReturnExpression? {
        val body = this.body ?: return null
        val returns = mutableListOf<UReturnExpression>()
        body.accept(object : AbstractUVisitor() {
            override fun visitReturnExpression(node: UReturnExpression): Boolean {
                returns.add(node)
                return super.visitReturnExpression(node)
            }
        })
        // A method should return this; check all returns
        return returns.find { it.returnExpression?.isThis() == true }
    }

    private fun UExpression.isThis(): Boolean {
        return when (this) {
            is UThisExpression -> true
            else -> false
        }
    }

    companion object {
        @JvmField
        val ISSUE = Issue.create(
            id = "ReturnThis",
            briefDescription = "Method must return `this`",
            explanation = """
                Methods annotated with `@ReturnThis` (usually in the super method that this method is overriding) should also return `this`.
            """,
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.ERROR,
            implementation = Implementation(
                ReturnThisDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}
```

