class ReturnThisDetector : Detector(), SourceCodeScanner {
    companion object {
        val ISSUE: Issue = Issue.create(
            id = "ReturnThis",
            briefDescription = "Method must return `this`",
            explanation = """
                Methods annotated with @ReturnThis (usually a super method being overridden) must return `this`.
                Returning any other value violates the contract.
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.ERROR,
            implementation = Implementation(ReturnThisDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )
        private const val RETURN_THIS_ANNOTATION = "ReturnThis"
    }

    override fun applicableElements(): List<Class<out UElement>> = listOf(UMethod::class.java)

    override fun visitElement(context: JavaContext, element: UElement) {
        val method = element as? UMethod ?: return
        val psiMethod = method.javaPsi ?: return

        // Skip constructors, static methods, void return, etc.
        if (psiMethod.isConstructor || psiMethod.hasModifierProperty(PsiModifier.STATIC)) return
        val returnType = psiMethod.returnType ?: return
        if (returnType == PsiTypes.voidType()) return

        if (!hasReturnThisAnnotatedSuper(psiMethod)) return

        // Analyze body returns
        val body = method.uastBody ?: return
        val returns = mutableListOf<UReturnExpression>()
        body.accept(object : AbstractUastVisitor() {
            override fun visitReturnExpression(node: UReturnExpression): Boolean {
                returns.add(node)
                return super.visitReturnExpression(node)
            }
        })

        if (returns.isEmpty()) {
            context.report(ISSUE, method, context.getLocation(method), "This method must return `this`")
            return
        }

        for (ret in returns) {
            val operand = ret.returnExpression
            if (!isThisReference(operand)) {
                context.report(ISSUE, ret, context.getLocation(ret), "Must return `this`")
            }
        }
    }

    private fun hasReturnThisAnnotatedSuper(method: PsiMethod): Boolean {
        val supers = method.findDeepestSuperMethods().takeIf { it.isNotEmpty() }
            ?: method.findSuperMethods().takeIf { it.isNotEmpty() }
            ?: return false
        return supers.any { isReturnThisAnnotated(it) }
    }

    private fun isReturnThisAnnotated(method: PsiMethod): Boolean {
        return method.modifierList.annotations.any {
            val qName = it.qualifiedName
            qName == RETURN_THIS_ANNOTATION || qName?.endsWith(".$RETURN_THIS_ANNOTATION") == true
        }
    }

    private fun isThisReference(expression: UExpression?): Boolean {
        if (expression == null) return false
        return expression is USimpleNameReferenceExpression && expression.identifier == "this" ||
            expression is UThisExpression
    }
}

