class SecureRandomDetector : Detector(), SourceCodeScanner {

    companion object {
        @JvmField
        val ISSUE: Issue = Issue.create(
            id = "SecureRandom",
            briefDescription = "Using a fixed seed with `SecureRandom`",
            explanation = """
                Specifying a fixed seed will cause the instance to return a predictable \
                sequence of numbers. This may be useful for testing but it is not \
                appropriate for secure use.
            """,
            moreInfo = "https://goo.gle/SecureRandom",
            category = Category.SECURITY,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(
                SecureRandomDetector::class.java,
                EnumSet.of(Scope.JAVA_FILE)
            )
        )
    }

    override fun getApplicableConstructorTypes(): List<String> =
        listOf("java.security.SecureRandom")

    override fun applicableMethodNames(): List<String> = listOf("setSeed")

    override fun visitConstructor(
        context: JavaContext,
        node: UCallExpression,
        constructor: PsiMethod
    ) {
        if (node.valueArgumentCount > 0) {
            report(context, node, "Using a fixed seed with `SecureRandom` is not secure")
        }
    }

    override fun visitMethodCall(
        context: JavaContext,
        node: UCallExpression,
        method: PsiMethod
    ) {
        if (context.evaluator.isMemberInClass(method, "java.security.SecureRandom")) {
            report(context, node, "Using a fixed seed with `SecureRandom` is not secure")
        }
    }

    private fun report(context: JavaContext, node: UCallExpression, message: String) {
        context.report(
            issue = ISSUE,
            scope = node,
            location = context.getLocation(node),
            message = message
        )
    }
}

