package com.android.tools.lint.checks

import com.android.tools.lint.client.api.UElementHandler
import com.android.tools.lint.detector.api.*
import org.jetbrains.uast.UCallExpression
import org.jetbrains.uast.UElement

class SecureRandomDetector : Detector(), SourceCodeScanner {
    override fun getApplicableUastTypes(): List<Class<out UElement>>? =
        listOf(UCallExpression::class.java)

    override fun createUastHandler(context: JavaContext): UElementHandler? =
        object : UElementHandler() {
            override fun visitCallExpression(node: UCallExpression) {
                val psiMethod = node.resolve() ?: return
                val containingClass = psiMethod.containingClass?.qualifiedName ?: return
                if (containingClass != "java.security.SecureRandom") return

                if (psiMethod.isConstructor) {
                    if (node.valueArgumentCount > 0) {
                        reportIssue(node)
                    }
                } else if (psiMethod.name == "setSeed") {
                    reportIssue(node)
                }
            }

            private fun reportIssue(node: UCallExpression) {
                context.report(
                    ISSUE,
                    node,
                    context.getLocation(node),
                    "Using a fixed seed with `SecureRandom` can produce predictable random numbers; " +
                        "do not use a fixed seed except for testing purposes."
                )
            }
        }

    companion object {
        @JvmField
        val ISSUE: Issue = Issue.create(
            id = "SecureRandom",
            briefDescription = "Using a fixed seed with `SecureRandom`",
            explanation = """
                Specifying a fixed seed will cause the instance to return a predictable \
                sequence of numbers. This may be useful for testing but it is not \
                appropriate for secure use.
            """.trimIndent(),
            category = Category.SECURITY,
            priority = 9,
            severity = Severity.WARNING,
            implementation = Implementation(
                SecureRandomDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}

