import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Collections;
import org.w3c.dom.Element;

public class TooManyViewsDetector extends LayoutDetector {
    private static final int DEFAULT_MAX_DEPTH = 10;
    private static final String ENV_MAX_DEPTH = "ANDROID_LINT_MAX_DEPTH";

    public static final Issue ISSUE = Issue.create(
            "TooDeepLayout",
            "Layout hierarchy is too deep",
            "Layouts with too much nesting is bad for performance. Consider using a flatter layout "
                    + "(such as `RelativeLayout` or `GridLayout`).",
            Category.PERFORMANCE,
            5,
            Severity.WARNING,
            new Implementation(TooManyViewsDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public void visitElement(XmlContext context, Element element) {
        int maxDepth = getMaxDepth();
        int depth = getDepth(element);
        if (depth > maxDepth) {
            context.report(ISSUE, element, context.getLocation(element),
                    String.format("Layout has too many nested levels: depth=%d, maximum=%d",
                            depth, maxDepth));
        }
    }

    private int getDepth(Element element) {
        int depth = 0;
        Element current = element;
        while (current != null) {
            depth++;
            current = getParentElement(current);
        }
        return depth;
    }

    private Element getParentElement(Element element) {
        if (element.getParentNode() instanceof Element) {
            return (Element) element.getParentNode();
        }
        return null;
    }

    private int getMaxDepth() {
        String maxDepth = System.getenv(ENV_MAX_DEPTH);
        if (maxDepth != null && !maxDepth.isEmpty()) {
            try {
                return Integer.parseInt(maxDepth);
            } catch (NumberFormatException e) {
                // ignore
            }
        }
        return DEFAULT_MAX_DEPTH;
    }
}
