public class TooManyViewsDetector extends LayoutDetector {
    public static final Issue ISSUE = Issue.create(
        "TooDeepLayout",
        "Layout hierarchy is too deep",
        "Layouts with too much nesting is bad for performance. Consider using a flatter layout (such as `RelativeLayout` or `GridLayout`).",
        Category.PERFORMANCE,
        5,
        Severity.WARNING,
        new Implementation(TooManyViewsDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private static final int DEFAULT_MAX_DEPTH = 10;

    private int maxDepth;
    private int currentDepth;

    @Override
    public void beforeCheckProject(Context context) {
        maxDepth = DEFAULT_MAX_DEPTH;
        String env = System.getenv("ANDROID_LINT_MAX_DEPTH");
        if (env != null) {
            try {
                int parsed = Integer.parseInt(env);
                if (parsed > 0) {
                    maxDepth = parsed;
                }
            } catch (NumberFormatException e) {
                // ignore
            }
        }
    }

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        currentDepth++;
        if (currentDepth > maxDepth) {
            context.report(ISSUE, element, context.getLocation(element),
                String.format("Layout hierarchy is too deep: %1$d (maximum allowed is %2$d)", currentDepth, maxDepth));
        }
    }

    @Override
    public void visitElementEnd(XmlContext context, Element element) {
        currentDepth--;
    }
}

