package com.android.tools.lint.checks;

import static com.android.SdkConstants.TAG_MERGE;
import static com.android.SdkConstants.TAG_INCLUDE;
import static com.android.SdkConstants.TAG_REQUEST_FOCUS;
import static com.android.SdkConstants.TAG_VIEW;
import static com.android.SdkConstants.VIEW;
import static com.android.SdkConstants.VIEW_GROUP;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.LayoutDetector;
import com.android.tools.lint.detector.api.Lint;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class TooManyViewsDetector extends LayoutDetector {
    private static final int DEFAULT_MAX_DEPTH = 10;
    private static final String ENV_MAX_DEPTH = "ANDROID_LINT_MAX_DEPTH";

    public static final Issue ISSUE_TOO_DEEP = Issue.create(
            "TooDeepLayout",
            "Layout hierarchy is too deep",
            "Layouts with too much nesting is bad for performance.  Consider using a flatter layout such as `RelativeLayout` or `GridLayout`.",
            Category.PERFORMANCE,
            5,
            Severity.WARNING,
            new Implementation(TooManyViewsDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private int mMaxDepth = DEFAULT_MAX_DEPTH;

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        String env = System.getenv(ENV_MAX_DEPTH);
        if (env != null) {
            try {
                mMaxDepth = Integer.parseInt(env);
            } catch (NumberFormatException e) {
                mMaxDepth = DEFAULT_MAX_DEPTH;
            }
        }
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public void visitDocument(@NonNull XmlContext context, @NonNull Document document) {
        Element root = document.getDocumentElement();
        if (root == null) return;
        int depth = computeMaxDepth(root, 1);
        if (depth > mMaxDepth) {
            Location location = context.getLocation(root);
            context.report(ISSUE_TOO_DEEP, root, location,
                    String.format("Layout has too deep hierarchy: depth %1$d, maximum %2$d", depth, mMaxDepth));
        }
    }

    private int computeMaxDepth(Element element, int depth) {
        int max = depth;
        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                max = Math.max(max, computeMaxDepth(childElement, depth + 1));
            }
            child = child.getNextSibling();
        }
        return max;
    }

    @Override
    public Issue[] getIssues() {
        return new Issue[] { ISSUE_TOO_DEEP };
    }
}

