import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.EnumSet;

public class TooManyViewsDetector extends ResourceXmlDetector {
    private static final int DEFAULT_MAX = 80;
    private static final String ENV_MAX_VIEW_COUNT = "ANDROID_LINT_MAX_VIEW_COUNT";

    public static final Issue ISSUE = Issue.create(
            "TooManyViews",
            "Layout has too many views",
            "Using too many views in a single layout is bad for performance. Consider using compound drawables or other tricks for reducing the number of views in this layout.",
            Category.PERFORMANCE,
            5,
            Severity.WARNING,
            new Implementation(TooManyViewsDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public void visitDocument(@NonNull XmlContext context, @NonNull Document document) {
        int max = DEFAULT_MAX;
        String envValue = System.getenv(ENV_MAX_VIEW_COUNT);
        if (envValue != null) {
            try {
                max = Integer.parseInt(envValue);
            } catch (NumberFormatException e) {
                // ignore
            }
        }

        int count = countViews(document.getDocumentElement());
        if (count > max) {
            context.report(ISSUE, document, context.getLocation(document),
                    String.format("Layout has %1$d views, more than the %2$d maximum suggested for layout files.", count, max));
        }
    }

    private static int countViews(Element element) {
        int count = 0;
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(element);
        while (!queue.isEmpty()) {
            Node node = queue.removeFirst();
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                count++;
                if (node.hasChildNodes()) {
                    NodeList children = node.getChildNodes();
                    for (int i = 0, n = children.getLength(); i < n; i++) {
                        queue.add(children.item(i));
                    }
                }
            }
        }
        return count;
    }
}
