        context.report(ISSUE, application, context.getValueLocation(application, null), "Wear apps must specify the standalone flag...");
    } else if (!valid) {
        context.report(ISSUE, invalid, context.getValueLocation(invalid, ATTR_VALUE), "Standalone flag value must be true or false");
    }
}
