public class WearStandaloneAppDetector extends Detector implements Detector.ManifestScanner {
    private static final String STANDALONE_FLAG = "com.google.android.wearable.standalone";
    private static final String WEARABLE_FEATURE = "android.hardware.type.watch";

    public static final Issue ISSUE = Issue.create(
            "WearStandaloneAppFlag",
            "Invalid or missing Wear standalone app flag",
            "Wearable apps must declare whether they can run as a standalone app by adding "
                    + "a <meta-data> element with android:name=\"com.google.android.wearable.standalone\" "
                    + "and android:value=\"true\" or \"false\" inside the <application> element.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(WearStandaloneAppDetector.class, Scope.MANIFEST_SCOPE));

    private boolean mIsWatchApp;

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_USES_FEATURE, TAG_APPLICATION);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String tag = element.getTagName();
        if (TAG_USES_FEATURE.equals(tag)) {
            String name = getManifestAttribute(element, ATTR_NAME);
            if (WEARABLE_FEATURE.equals(name)) {
                String required = getManifestAttribute(element, ATTR_REQUIRED);
                if (required == null || !Boolean.parseBoolean(required) && !"false".equals(required)) {
                    // default true or explicitly true; note Boolean.parseBoolean returns false for "false" too
                    if ("false".equals(required)) {
                        // not a watch app
                    } else {
                        mIsWatchApp = true;
                    }
                }
            }
        } else if (TAG_APPLICATION.equals(tag) && mIsWatchApp) {
            boolean found = false;
            boolean valid = false;
            NodeList children = element.getChildNodes();
            for (int i = 0; i < children.getLength(); i++) {
                Node child = children.item(i);
                if (child.getNodeType() == Node.ELEMENT_NODE
                        && TAG_META_DATA.equals(child.getNodeName())) {
                    Element meta = (Element) child;
                    String name = getManifestAttribute(meta, ATTR_NAME);
                    if (STANDALONE_FLAG.equals(name)) {
                        found = true;
                        String value = getManifestAttribute(meta, ATTR_VALUE);
                        if ("true".equals(value) || "false".equals(value)) {
                            valid = true;
                        } else {
                            context.report(ISSUE, context.getLocation(meta),
                                    "The `com.google.android.wearable.standalone` meta-data value must be `true` or `false`.");
                            return;
                        }
                    }
                }
            }
            if (!found) {
                context.report(ISSUE, context.getLocation(element),
                        "Missing `com.google.android.wearable.standalone` meta-data element. Wearable apps must declare whether they can run standalone.");
            } else if (!valid) {
                // already reported if invalid value
            }
        }
    }

    private static String getManifestAttribute(Element element, String localName) {
        String value = element.getAttribute(ANDROID_URI, localName);
        if (value == null || value.isEmpty()) {
            value = element.getAttribute("android:" + localName);
        }
        return value;
    }
}
