        }
        return type != null && HOSTNAME_VERIFIER.equals(type.getCanonicalText());
    }

    private static boolean alwaysReturnsTrue(@NotNull UExpression body) {
        if (body instanceof UReturnExpression) {
            return isTrueLiteral(((UReturnExpression) body).getReturnExpression());
        }
        if (body instanceof UBlockExpression) {
            for (UExpression expr : ((UBlockExpression) body).getExpressions()) {
                if (expr instanceof UReturnExpression) {
                    if (!isTrueLiteral(((UReturnExpression) expr).getReturnExpression())) {
                        return false;
                    }
                }
            }
            return true; // all returns are true
        }
        return isTrueLiteral(body);
    }

    private static boolean isTrueLiteral(@org.jetbrains.annotations.Nullable UExpression expression) {
        if (expression == null) {
            return false;
        }
        if (expression instanceof UParenthesizedExpression) {
            return isTrueLiteral(((UParenthesizedExpression) expression).getExpression());
        }
        if (expression instanceof ULiteralExpression) {
            Object value = ((ULiteralExpression) expression).getValue();
            return Boolean.TRUE.equals(value);
        }
        return false;
    }

    private static boolean isString(@NotNull PsiType type) {
        PsiType base = type.getDeepComponentType();
        return "java.lang.String".equals(base.getCanonicalText());
    }

    private static boolean isType(@NotNull PsiType type, @NotNull String fqcn) {
        PsiType base = type.getDeepComponentType();
        return fqcn.equals(base.getCanonicalText());
    }
}
