package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;

import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Arrays;
import java.util.Collection;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class AutofillDetector extends ResourceXmlDetector {
    private static final String AUTO_FILL_HINTS = "autofillHints";
    private static final String IMPORTANT_FOR_AUTO_FILL = "importantForAutofill";

    private static final int AUTO_FILL_TARGET_SDK = 26;

    private static final Implementation IMPLEMENTATION = new Implementation(
            AutofillDetector.class, Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "Autofill",
            "Missing `autofillHints` attribute",
            "Specify an `autofillHints` attribute when targeting SDK version 26 or higher "
                    + "or explicitly specify that the view is not important for autofill. "
                    + "Your app can help an autofill service classify the data correctly by "
                    + "providing the meaning of each view that could be autofillable, such as "
                    + "views representing usernames, passwords, credit card fields, email "
                    + "addresses, etc.\n\n"
                    + "The hints can have any value, but it is recommended to use predefined "
                    + "values like 'username' for a username or 'creditCardNumber' for a credit "
                    + "card number. For a list of all predefined autofill hint constants, see the "
                    + "`AUTOFILL_HINT_` constants in the `View` reference.\n\n"
                    + "You can mark a view unimportant for autofill by specifying an "
                    + "`importantForAutofill` attribute on that view or a parent view.",
            Category.USABILITY,
            5,
            Severity.WARNING,
            IMPLEMENTATION)
            .setMoreInfo("https://developer.android.com/guide/topics/text/autofill.html");

    @NonNull
    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(
                "AutoCompleteTextView",
                "EditText",
                "ExtractEditText",
                "MultiAutoCompleteTextView",
                "SearchView",
                "TextInputEditText"
        );
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (context.getProject().getTargetSdk() < AUTO_FILL_TARGET_SDK) {
            return;
        }

        if (element.hasAttributeNS(ANDROID_URI, AUTO_FILL_HINTS)) {
            return;
        }

        if (isNotImportantForAutofill(element)) {
            return;
        }

        context.report(ISSUE, element, context.getNameLocation(element),
                "Missing `autofillHints` attribute");
    }

    private static boolean isNotImportantForAutofill(@NonNull Element element) {
        // Check this view.
        String value = element.getAttributeNS(ANDROID_URI, IMPORTANT_FOR_AUTO_FILL);
        if (!value.isEmpty()) {
            int mode = parseImportantForAutofill(value);
            return mode == ViewConstants.IMPORTANT_FOR_AUTOFILL_NO
                    || mode == ViewConstants.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS;
        }

        // Check ancestors; if an ancestor excludes descendants, this view is not important.
        Node parent = element.getParentNode();
        while (parent instanceof Element) {
            Element parentElement = (Element) parent;
            String parentValue = parentElement.getAttributeNS(ANDROID_URI, IMPORTANT_FOR_AUTO_FILL);
            if (!parentValue.isEmpty()) {
                int mode = parseImportantForAutofill(parentValue);
                if (mode == ViewConstants.IMPORTANT_FOR_AUTOFILL_NO
                        || mode == ViewConstants.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS
                        || mode == ViewConstants.IMPORTANT_FOR_AUTOFILL_YES_EXCLUDE_DESCENDANTS) {
                    return true;
                }
            }
            parent = parentElement.getParentNode();
        }
        return false;
    }

    private static int parseImportantForAutofill(@NonNull String value) {
        // The attribute can be an integer constant or a symbolic name.
        switch (value) {
            case "yes":
                return ViewConstants.IMPORTANT_FOR_AUTOFILL_YES;
            case "no":
                return ViewConstants.IMPORTANT_FOR_AUTOFILL_NO;
            case "auto":
                return ViewConstants.IMPORTANT_FOR_AUTOFILL_AUTO;
            case "yesExcludeDescendants":
                return ViewConstants.IMPORTANT_FOR_AUTOFILL_YES_EXCLUDE_DESCENDANTS;
            case "noExcludeDescendants":
                return ViewConstants.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS;
            default:
                try {
                    return Integer.parseInt(value);
                } catch (NumberFormatException e) {
                    // Unknown or resource reference; treat as auto/default.
                    return ViewConstants.IMPORTANT_FOR_AUTOFILL_AUTO;
                }
        }
    }

    private static final class ViewConstants {
        static final int IMPORTANT_FOR_AUTOFILL_AUTO = 0;
        static final int IMPORTANT_FOR_AUTOFILL_YES = 1;
        static final int IMPORTANT_FOR_AUTOFILL_NO = 2;
        static final int IMPORTANT_FOR_AUTOFILL_YES_EXCLUDE_DESCENDANTS = 4;
        static final int IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS = 8;

        private ViewConstants() {}
    }
}
```

