        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(
                SdkConstants.EDIT_TEXT,
                SdkConstants.AUTO_COMPLETE_TEXT_VIEW,
                SdkConstants.MULTI_AUTO_COMPLETE_TEXT_VIEW);
    }

    @Override
    public void beforeCheckFile(@NonNull Context context) {
        mTargetSdk = context.getMainProject().getTargetSdk();
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (mTargetSdk < 26) {
            return;
        }

        if (element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_AUTOFILL_HINTS)) {
            return;
        }

        if (isUnimportant(element)) {
            return;
        }

        context.report(
                ISSUE,
                element,
                context.getLocation(element),
                "Missing autofillHints attribute");
    }

    private boolean isUnimportant(@NonNull Element element) {
        while (element != null) {
            String important = element.getAttributeNS(
                    SdkConstants.ANDROID_URI, SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
            if (important != null && !important.isEmpty()) {
                return important.equals(SdkConstants.VALUE_NO)
