public class EllipsizeMaxLinesDetector extends LayoutDetector {

  public static final Issue ISSUE = Issue.create(
      "EllipsizeMaxLines",
      "Combining ellipsize and maxLines=1",
      "Combining `ellipsize` and `maxLines=1` can lead to crashes on some devices. ...",
      Category.CORRECTNESS,
      5,
      Severity.WARNING,
      new Implementation(EllipsizeMaxLinesDetector.class, Scope.RESOURCE_FILE_SCOPE));

  @Override
  public Collection<String> getApplicableAttributes() {
    return Collections.singletonList(SdkConstants.ATTR_ELLIPSIZE);
  }

  @Override
  public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
    Element element = attribute.getOwnerElement();
    if (element == null) return;
    if (SdkConstants.VALUE_NONE.equals(attribute.getValue())) return;
    String maxLines = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_MAX_LINES);
    if ("1".equals(maxLines)) {
      context.report(ISSUE, attribute, context.getValueLocation(attribute),
          "Combining `ellipsize` and `maxLines=1` can cause crashes on some devices; "
          + "use `singleLine=\"true\"` or remove `ellipsize`");
    }
  }
}

