@Override
public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
    if (!ANDROID_URI.equals(attribute.getNamespaceURI())) return;
    String name = attribute.getLocalName();
    if (!MAX_LINES.equals(name)) return;
    if (!"1".equals(attribute.getValue())) return;
    Element element = attribute.getOwnerElement();
    if (element.getAttributeNS(ANDROID_URI, ELLIPSIZE) == null || element.getAttributeNS(ANDROID_URI, ELLIPSIZE).isEmpty()) return;
    context.report(ISSUE, attribute, context.getNameLocation(attribute),
        "Combining `ellipsize` and `maxLines=1` can lead to crashes on some devices. Use `singleLine=true` instead.");
}
```

