public class InefficientWeightDetector extends ResourceXmlDetector {

    private static final String TAG_LINEAR_LAYOUT = "LinearLayout";
    private static final String ATTR_BASELINE_ALIGNED = "baselineAligned";
    private static final String ATTR_ORIENTATION = "orientation";
    private static final String ORIENTATION_VERTICAL = "vertical";
    private static final String VALUE_FALSE = "false";
    private static final String ATTR_LAYOUT_WEIGHT = "layout_weight";

    public static final Issue DISABLE_BASELINE_ALIGNMENT = Issue.create(
        "DisableBaselineAlignment",
        "Missing baselineAligned attribute",
        "When a LinearLayout is used to distribute the space proportionally between nested layouts, " +
            "the baseline alignment property should be turned off to make the layout computation faster. " +
            "Set android:baselineAligned=\"false\".",
        Category.PERFORMANCE,
        3,
        Severity.WARNING,
        new Implementation(
            InefficientWeightDetector.class,
            Scope.RESOURCE_FILE_SCOPE,
            Scope.RESOURCE_FILE_SCOPE
        )
    );

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_LINEAR_LAYOUT);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (ORIENTATION_VERTICAL.equals(element.getAttribute(ATTR_ORIENTATION))) {
            return;
        }
        String baselineAligned = element.getAttribute(ATTR_BASELINE_ALIGNED);
        if (VALUE_FALSE.equals(baselineAligned)) {
            return;
        }

        boolean hasWeightedLayoutChild = false;
        for (Node child = element.getFirstChild(); child != null; child = child.getNextSibling()) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                String weight = childElement.getAttribute(ATTR_LAYOUT_WEIGHT);
                if (weight != null && !weight.isEmpty() && !"0".equals(weight)) {
                    if (isViewGroup(childElement.getTagName())) {
                        hasWeightedLayoutChild = true;
                        break;
                    }
                }
            }
        }

        if (hasWeightedLayoutChild) {
            context.report(
                DISABLE_BASELINE_ALIGNMENT,
                context.getValueLocation(element),
                "Set android:baselineAligned=\"false\" on this LinearLayout to improve performance"
            );
        }
    }

    private static boolean isViewGroup(String tagName) {
        return tagName != null && (
            tagName.endsWith("Layout") ||
            "RadioGroup".equals(tagName) ||
            "ViewGroup".equals(tagName) ||
            "ScrollView".equals(tagName) ||
            "HorizontalScrollView".equals(tagName) ||
            "Toolbar".equals(tagName) ||
            "AdapterView".equals(tagName) ||
            "GridView".equals(tagName) ||
            "ListView".equals(tagName) ||
            "RecyclerView".equals(tagName)
        );
    }
}

