@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    if (!VALUE_HORIZONTAL.equals(element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION))) {
        return;
    }

    String baselineAligned = element.getAttributeNS(ANDROID_URI, ATTR_BASELINE_ALIGNED);
    if (VALUE_FALSE.equals(baselineAligned)) {
        return;
    }

    NodeList children = element.getChildNodes();
    for (int i=0; i<children.getLength(); i++) {
        Node child = children.item(i);
        if (child.getNodeType() != Node.ELEMENT_NODE) continue;
        Element childElement = (Element) child;

        if (isLayout(childElement)) {
            String weight = childElement.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
            if (weight != null && !weight.isEmpty()) {
                float value;
                try { value = Float.parseFloat(weight); } catch (NumberFormatException e) { continue; }
                if (value > 0f) {
                    context.report(ISSUE, element, context.getLocation(element),
                        "LinearLayout with weights to distribute space among nested layouts should set android:baselineAligned=\"false\" for better performance.");
                    return;
                }
            }
        }
    }
}

