import org.w3c.dom.Element;

import java.util.Collection;
import java.util.Collections;

public class InefficientWeightDetector extends LayoutDetector {
    public static final Issue ISSUE = Issue.create(
            "NestedWeights",
            "Nested layout weights",
            "Layout weights require a widget to be measured twice. When a `LinearLayout` with non-zero weights is nested inside another `LinearLayout` with non-zero weights, then the number of measurements increase exponentially.",
            Category.PERFORMANCE,
            3,
            Severity.WARNING,
            new Implementation(InefficientWeightDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(LINEAR_LAYOUT);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (!hasNonZeroWeight(element)) {
            return;
        }
        Element parent = element.getParentNode() instanceof Element ? (Element) element.getParentNode() : null;
        while (parent != null) {
            if (LINEAR_LAYOUT.equals(parent.getTagName()) && hasNonZeroWeight(parent)) {
                context.report(ISSUE, element, context.getLocation(element), "Nested `layout_weight` attributes will result in exponential measurement overhead");
                return;
            }
            parent = parent.getParentNode() instanceof Element ? (Element) parent.getParentNode() : null;
        }
    }

    private static boolean hasNonZeroWeight(@NonNull Element element) {
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
            return false;
        }
        String value = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
        if (value == null || value.isEmpty()) {
            return false;
        }
        if (value.startsWith("@")) {
            return true; // unknown; assume problematic
        }
        try {
            float weight = Float.parseFloat(value);
            return weight != 0f;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}

