package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_IME_ACTION_ID;

import com.android.annotations.NonNull;
import com.android.resources.ResourceType;
import com.android.resources.ResourceUrl;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;

import org.w3c.dom.Attr;

import java.util.Collection;
import java.util.Collections;

public class InvalidImeActionIdDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
            "InvalidImeActionId",
            "Invalid `android:imeActionId` declaration",
            "The `android:imeActionId` attribute must be set to an integer constant "
                    + "or an integer resource reference (e.g. `@integer/action_send`). "
                    + "ID resource references such as `@+id/resName` are not valid because "
                    + "`EditorInfo.imeActionId` expects a raw integer action id, not a view id.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(InvalidImeActionIdDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public Collection<String> getApplicableAttributes() {
        return Collections.singletonList(ATTR_IME_ACTION_ID);
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String value = attribute.getValue();
        if (value == null || value.isEmpty()) {
            return;
        }

        ResourceUrl url = ResourceUrl.parse(value);
        if (url != null) {
            if (url.type == ResourceType.ID) {
                context.report(ISSUE, attribute, context.getValueLocation(attribute),
                        "Invalid `android:imeActionId`: should not be an ID resource reference (`"
                                + value + "`). Use an integer constant or an integer resource reference.");
            }
        } else {
            // not a reference; must be an integer constant
            if (!isIntegerConstant(value)) {
                context.report(ISSUE, attribute, context.getValueLocation(attribute),
                        "Invalid `android:imeActionId`: must be an integer constant or an integer resource reference.");
            }
        }
    }

    private static boolean isIntegerConstant(String value) {
        // Accept decimal/hex integer, optionally with leading +/- and 0x prefix.
        try {
            // Use Long to allow full range? But action id int.
            if (value.startsWith("0x") || value.startsWith("0X")) {
                Long.parseLong(value.substring(2), 16);
            } else {
                Long.parseLong(value);
            }
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}

