public class ManifestResourceDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "ManifestResource",
            "Manifest resource references",
            "Elements in the manifest can reference resources, but those resources cannot " +
            "vary across configurations (except as a special case, by version, and except " +
            "for a few specific package attributes such as the application title and icon).",
            Category.CORRECTNESS, 5, Severity.WARNING,
            new Implementation(ManifestResourceDetector.class, Scope.MANIFEST_SCOPE));

    @Override
    public Collection<String> getApplicableAttributes() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitAttribute(@NotNull XmlContext context, @NotNull Attr attribute) {
        String value = attribute.getValue();
        if (value.isEmpty() || value.charAt(0) != '@') {
            return;
        }
        ResourceUrl url = ResourceUrl.parse(value);
        if (url == null || url.isTheme() || url.packageName != null) {
            return;
        }
        if (isExempt(attribute, url)) {
            return;
        }
        ResourceRepository resources = context.getProject().getResourceRepository();
        if (resources == null) {
            return;
        }
        List<ResourceItem> items = resources.getResources(
                ResourceNamespace.RES_AUTO, url.type, url.name);
        if (items.size() <= 1) {
            return;
        }
        for (ResourceItem item : items) {
            FolderConfiguration config = item.getConfiguration();
            if (config == null) {
                continue;
            }
            if (hasNonVersionQualifier(config)) {
                String message = String.format(
                        "Resources referenced from the manifest cannot vary across configurations " +
                        "except for version: `%1$s` has different values for different configurations " +
                        "(e.g. `%2$s`)", value, config.getQualifierString());
                context.report(ISSUE, attribute, context.getValueLocation(attribute), message);
                return;
            }
        }
    }

    private static boolean isExempt(Attr attribute, ResourceUrl url) {
        if (url.type != ResourceType.STRING && url.type != ResourceType.DRAWABLE
                && url.type != ResourceType.MIPMAP) {
            return false;
        }
        String name = attribute.getLocalName();
        if (!name.equals(ATTR_LABEL) && !name.equals(ATTR_ICON)) {
            return false;
        }
        return attribute.getOwnerElement().getTagName().equals(TAG_APPLICATION)
                && attribute.getNamespaceURI().equals(ANDROID_URI);
    }

    private static boolean hasNonVersionQualifier(FolderConfiguration config) {
        if (config.getQualifierCount() == 0) {
            return false;
        }
        if (config.getQualifierCount() == 1 && config.getVersionQualifier() != null) {
            return false;
        }
        return true;
    }
}
