public class ManifestResourceDetector extends Detector implements XmlScanner {
    private static final String ANDROID_NS = "http://schemas.android.com/apk/res/android";
    @Override
    public Collection<String> getApplicableElements() { return ALL; }
    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        NamedNodeMap attributes = element.getAttributes();
        for (int i = 0, n = attributes.getLength(); i < n; i++) {
            Attr attr = (Attr) attributes.item(i);
            String value = attr.getValue();
            if (value.isEmpty() || value.charAt(0) != '@') continue;
            ResourceUrl url = ResourceUrl.parse(value);
            if (url == null || url.framework) continue;
            if (isExempt(element, attr)) continue;
            ResourceRepository repository = context.getProject().getResourceRepository();
            List<ResourceItem> items = repository.getResourceItems(url.type, url.name);
            if (items == null) continue;
            for (ResourceItem item : items) {
                FolderConfiguration config = item.getConfiguration();
                if (config != null && config.isDefault()) continue;
                // If only version qualifier...
                if (config != null && isVersionOnly(config)) continue;
                // report
            }
        }
    }
}
```

