package com.android.tools.lint.checks;

import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Element;
import java.util.*;

public class ManifestTypoDetector extends Detector implements Detector.XmlScanner {

    private static final Implementation IMPLEMENTATION = new Implementation(
            ManifestTypoDetector.class,
            Scope.MANIFEST_SCOPE
    );

    private static final Issue ISSUE = Issue.create(
            "ManifestTypo",
            "Manifest tag typo",
            "This check looks through the manifest, and if it finds any tags that look like likely misspellings, they are flagged.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            IMPLEMENTATION
    );

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String tag = element.getTagName();
        if (tag == null) return;
        if (VALID_TAGS.contains(tag)) {
            return;
        }
        String closest = null;
        int best = Integer.MAX_VALUE;
        for (String valid : VALID_TAGS) {
            int distance = editDistance(tag, valid);
            if (distance < best) {
                best = distance;
                closest = valid;
            }
        }
        if (closest != null && best <= getThreshold(tag.length())) {
            context.report(ISSUE, element, context.getLocation(element),
                    String.format("Tag '%1$s' looks like a misspelling of '%2$s'", tag, closest),
                    null);
        }
    }

    private static int getThreshold(int length) {
        if (length <= 4) return 0;
        if (length <= 8) return 1;
        return 2;
    }

    private static int editDistance(String s, String t) {
        // Levenshtein
        int n = s.length();
        int m = t.length();
        if (n == 0) return m;
        if (m == 0) return n;
        int[] prev = new int[m + 1];
        int[] curr = new int[m + 1];
        for (int j = 0; j <= m; j++) prev[j] = j;
        for (int i = 1; i <= n; i++) {
            curr[0] = i;
            char sc = s.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                char tc = t.charAt(j - 1);
                int cost = sc == tc ? 0 : 1;
                curr[j] = Math.min(Math.min(curr[j - 1] + 1, prev[j] + 1), prev[j - 1] + cost);
            }
            int[] tmp = prev; prev = curr; curr = tmp;
        }
        return prev[m];
    }

    private static final Set<String> VALID_TAGS = new HashSet<>(Arrays.asList(
        "manifest", "application", "activity", "activity-alias", "intent-filter", "action", "category",
        "data", "uses-permission", "permission", "permission-group", "permission-tree",
        "uses-feature", "uses-library", "uses-sdk", "provider", "receiver", "service",
        "meta-data", "grant-uri-permission", "path-permission",
        "instrumentation", "supports-screens", "compatible-screens", "profile",
        "restrictions", "package", "queries", "attribution", "property"
    ));
}

