package com.android.tools.lint.checks

import com.android.SdkConstants.*
import com.android.ide.common.repository.GradleVersion
import com.android.resources.ResourceFolderType
import com.android.tools.lint.detector.api.*
import org.w3c.dom.Attr
import org.w3c.dom.Element
import java.util.*

class NamespaceDetector : ResourceXmlDetector() {

    override fun appliesTo(folderType: ResourceFolderType): Boolean {
        return folderType == ResourceFolderType.LAYOUT
    }

    override fun getApplicableElements(): Collection<String>? {
        return XmlScannerConstants.ALL
    }

    override fun visitElement(context: XmlContext, element: Element) {
        if (!context.project.isLibrary) {
            return
        }

        val tag = element.tagName
        // Only consider custom views (fully qualified class names)
        if (tag.indexOf('.') == -1) {
            return
        }

        // Check attributes
        var i = 0
        val length = element.attributes.length
        while (i < length) {
            val attr = element.attributes.item(i) as Attr
            val namespaceUri = attr.namespaceURI ?: continue
            val prefix = attr.prefix ?: ""

            // Skip if it's an xmlns declaration
            if (prefix == XMLNS_PREFIX || attr.name == XMLNS) {
                i++
                continue
            }

            // Skip standard schemas and tools namespace
            if (namespaceUri == ANDROID_URI ||
                namespaceUri == TOOLS_URI ||
                namespaceUri == DIST_NAMESPACE ||
                namespaceUri == APP鸪
            ) {
                i++
                continue
            }

            // Check if the namespace URI contains the library package
            if (namespaceUri.startsWith(RESOURCE_AUTO_URI)) {
                i++
                continue
            }

            // Library package namespace: e.g., http://schemas.android.com/apk/res/com.example.library
            val packageName = context.project.getPackage()
            if (packageName != null && namespaceUri.startsWith("http://schemas.android.com/apk/res/$packageName")) {
                // Report
                val location = context.getLocation(attr)
                context.report(
                    ISSUE,
                    attr,
                    location,
                    "When using a custom view with custom attributes in a library project, the layout must use the special `http://schemas.android.com/apk/res-auto` namespace instead of `http://schemas.android.com/apk/res/${packageName}`."
                )
            }
            i++
        }
    }

    companion object {
        private val IMPLEMENTATION = Implementation(
            NamespaceDetector::class.java,
            Scope.RESOURCE_FILE_SCOPE
        )

        @JvmField
        val ISSUE = Issue.create(
            id = "LibraryCustomView",
            briefDescription = "Library custom views should use res-auto namespace",
            explanation = """
                When using a custom view with custom attributes in a library project, the layout must use the special namespace `http://schemas.android.com/apk/res-auto` instead of a URI which includes the library project's own package. This will be used to automatically adjust the namespace of the attributes when the library resources are merged into the application project.
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 8,
            severity = Severity.ERROR,
            implementation = IMPLEMENTATION
        )

        const val AUTO_URI = "http://schemas.android.com/apk/res-auto"
    }
}
```

