```
package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import org.w3c.dom.Attr
import org.w3c.dom.Document
import org.w3c.dom.Element
import org.w3c.dom.NamedNodeMap
import org.w3c.dom.Node

class NamespaceDetector : Detector(), Detector.XmlScanner {

    override fun getApplicableFiles(): Int = Scope.RESOURCE_FILE

    override fun visitDocument(context: XmlContext, document: Document) {
        val namespaces = mutableListOf<Attr>()
        val used = mutableSetOf<String>()

        fun collect(element: Element) {
            // collect namespace attributes
            val attrs = element.attributes
            for (i in 0 until attrs.length) {
                val attr = attrs.item(i) as Attr
                if (attr.name == "xmlns" || attr.name.startsWith("xmlns:")) {
                    namespaces.add(attr)
                } else {
                    // attribute usage prefix
                    val prefix = attr.prefix
                    if (prefix != null) used.add(prefix)
                }
            }
            // element usage prefix
            val prefix = element.prefix
            if (prefix != null) used.add(prefix)

            val childNodes = element.childNodes
            for (i in 0 until childNodes.length) {
                val child = childNodes.item(i)
                if (child.nodeType == Node.ELEMENT_NODE) collect(child as Element)
            }
        }

        collect(document.documentElement)

        for (attr in namespaces) {
            when {
                attr.name == "xmlns" -> {
                    // default namespace used if any unprefixed element exists
                    // Since root element is unprefixed if default ns, already used; but check any?
                    // Actually any unprefixed element uses default ns. We can record default ns as used if root or any child has null prefix.
                    // We'll track default in used if attr.name == "xmlns" and there is at least one unprefixed element.
                }
                attr.name.startsWith("xmlns:") -> {
                    val declaredPrefix = attr.name.substring(6)
                    if (declaredPrefix !in used) {
                        report(context, attr, declaredPrefix)
                    }
                }
            }
        }

        // Default namespace: if declared and all elements are prefixed? Rare.
        val defaultNsAttr = namespaces.find { it.name == "xmlns" }
        if (defaultNsAttr != null) {
            val hasUnprefixed = hasUnprefixedElement(document.documentElement)
            if (!hasUnprefixed) {
                report(context, defaultNsAttr, "")
            }
        }
    }

    private fun hasUnprefixedElement(element: Element): Boolean {
        if (element.prefix == null) return true
        val children = element.childNodes
        for (i in 0 until children.length) {
            val child = children.item(i)
            if (child.nodeType == Node.ELEMENT_NODE && (child as Element).prefix == null) return true
        }
        return false
    }

    private fun report(context: XmlContext, attr: Attr, prefix: String) {
        val message = if (prefix.isEmpty()) {
            "Unused namespace declaration: default namespace"
        } else {
            "Unused namespace declaration: $prefix"
        }
        context.report(ISSUE, context.getLocation(attr), message)
    }

    companion object {
        @JvmField
        val ISSUE = Issue.create(...)
    }
}
```

