package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.Category
import com.android.tools.lint.detector.api.Implementation
import com.android.tools.lint.detector.api.Issue
import com.android.tools.lint.detector.api.ResourceXmlDetector
import com.android.tools.lint.detector.api.Scope
import com.android.tools.lint.detector.api.Severity
import com.android.tools.lint.detector.api.XmlContext
import org.w3c.dom.Attr
import org.w3c.dom.Document
import org.w3c.dom.Element
import org.w3c.dom.Node

class NamespaceDetector : ResourceXmlDetector() {

    override fun visitDocument(context: XmlContext, document: Document) {
        val root = document.documentElement ?: return
        val namespaceAttributes = mutableListOf<Attr>()
        val usedPrefixes = mutableSetOf<String>()
        var hasUnprefixedElement = false

        fun visit(element: Element) {
            if (element.prefix != null) {
                usedPrefixes += element.prefix
            } else {
                hasUnprefixedElement = true
            }

            val attributes = element.attributes ?: return
            for (i in 0 until attributes.length) {
                val attr = attributes.item(i) as Attr
                val name = attr.name
                when {
                    name == "xmlns" -> {
                        namespaceAttributes += attr
                    }
                    name.startsWith("xmlns:") -> {
                        namespaceAttributes += attr
                    }
                    else -> {
                        attr.prefix?.let { usedPrefixes += it }
                    }
                }
            }

            val children = element.childNodes
            for (i in 0 until children.length) {
                val child = children.item(i)
                if (child.nodeType == Node.ELEMENT_NODE) {
                    visit(child as Element)
                }
            }
        }

        visit(root)

        for (attr in namespaceAttributes) {
            if (attr.name == "xmlns") {
                if (!hasUnprefixedElement) {
                    reportUnused(context, attr, null)
                }
            } else {
                val prefix = attr.name.substringAfter("xmlns:")
                if (prefix !in usedPrefixes) {
                    reportUnused(context, attr, prefix)
                }
            }
        }
    }

    private fun reportUnused(context: XmlContext, attr: Attr, prefix: String?) {
        val message = if (prefix != null) {
            "Unused namespace \"$prefix\""
        } else {
            "Unused default namespace"
        }
        context.report(ISSUE, context.getLocation(attr), message)
    }

    companion object {
        @JvmField
        val ISSUE = Issue.create(
            id = "UnusedNamespace",
            briefDescription = "Unused namespace",
            explanation = """
                Unused namespace declarations take up space and require processing that is not necessary.
                Remove any namespace declarations that are not used by elements or attributes in this file.
            """,
            category = Category.CORRECTNESS,
            priority = 4,
            severity = Severity.WARNING,
            implementation = Implementation(
                NamespaceDetector::class.java,
                Scope.RESOURCE_FILE_SCOPE
            )
        )
    }
}
```

