private fun visitElement(
    context: XmlContext,
    element: Element,
    active: MutableMap<String, ArrayDeque<Decl>>,
    defaultStack: ArrayDeque<Decl>
) {
    val attrs = element.attributes
    val pushed = mutableListOf<Decl>()
    for i in 0 until attrs.length {
        val attr = attrs.item(i) as Attr
        val name = attr.name
        if (name == "xmlns") {
            val decl = Decl(attr, null)
            defaultStack.addLast(decl)
            pushed.add(decl)
        } else if (name.startsWith("xmlns:")) {
            val prefix = name.substringAfter("xmlns:")
            val decl = Decl(attr, prefix)
            active.getOrPut(prefix) { ArrayDeque() }.addLast(decl)
            pushed.add(decl)
        }
    }
    // element tag usage
    val p = element.prefix
    if (p.isNullOrEmpty()) {
        defaultStack.lastOrNull()?.used = true
    } else {
        active[p]?.lastOrNull()?.used = true
    }
    // attribute usage
    for i in 0 until attrs.length) {
        val attr = attrs.item(i) as Attr
        if (attr.name == "xmlns" || attr.name.startsWith("xmlns:")) continue
        val ap = attr.prefix
        if (!ap.isNullOrEmpty()) {
            active[ap]?.lastOrNull()?.used = true
        }
    }
    // children
    val children = element.childNodes
    for i in 0 until children.length) {
        val child = children.item(i)
        if (child.nodeType == Node.ELEMENT_NODE) {
            visitElement(context, child as Element, active, defaultStack)
        }
    }
    // pop and report
    for (decl in pushed.asReversed()) {
        if (decl.prefix == null) {
            defaultStack.removeLast()
            if (!decl.used) reportUnused(context, decl.attr, null)
        } else {
            active[decl.prefix]!!.removeLast()
            if (!decl.used) reportUnused(context, decl.attr, decl.prefix)
        }
    }
}
```

