class StorageDetector : Detector(), SourceCodeScanner {
    override fun getApplicableMethodNames(): List<String> = listOf("getUsableSpace")

    override fun visitMethodCall(context: JavaContext, call: UCallExpression, visitor: UElementHandler?) {
        if (isUsableSpaceCall(call)) {
            // If the same file also references the new storage APIs, don't warn.
            if (usesNewStorageApi(context.uFile)) {
                return
            }

            context.report(
                ISSUE,
                call,
                context.getLocation(call),
                "Using `getUsableSpace()` can give inaccurate results; consider calling `StorageManager#getAllocatableBytes(UUID)` instead"
