        // Ensure it's a method call (not constructor) named getUsableSpace.
        if (!call.isMethodCall()) return false
        val method = call.resolve() ?: return true
        return method.name == "getUsableSpace"
    }

    private fun usesNewStorageApi(uFile: UFile?): Boolean {
        uFile ?: return false
        return uFile.asRefdLanguageExtensions().any { refExpr ->
            val name = refExpr.resolvedName
            name == "allocateBytes" || name == "getAllocatableBytes"
        }
    }

    companion object {
        @JvmField
        val ISSUE = Issue.create(
            id = "UsableSpace",
            briefDescription = "Using getUsableSpace()",
            explanation = """
                When you need to allocate disk space for large files, consider using the new \
