class StorageDetector : Detector(), SourceCodeScanner {
    private val pendingReports = mutableListOf<Pair<JavaContext, UCallExpression>>()
    private var usesNewStorageApi = false

    override fun getApplicableMethodNames(): List<String> = listOf("getUsableSpace", "allocateBytes", "getAllocatableBytes")

    override fun visitMethodCall(context: JavaContext, call: UCallExpression, visitor: UElementHandler?) {
        val methodName = call.methodName ?: return
        when (methodName) {
            "allocateBytes", "getAllocatableBytes" -> usesNewStorageApi = true
            "getUsableSpace" -> pendingReports.add(context to call)
        }
    }

    override fun beforeCheckFile(context: Context) {
        pendingReports.clear()
        usesNewStorageApi = false
    }

    override fun afterCheckFile(context: Context) {
        if (!usesNewStorageApi) {
            for ((_, call) in pendingReports) {
                context.report(ISSUE, call, context.getLocation(call), MESSAGE)
            }
        }
        pendingReports.clear()
    }
}
