```java
@Override
public boolean appliesTo(@NonNull ResourceFolderType folderType) {
    return folderType == ResourceFolderType.LAYOUT;
}

@Override
public @NonNull Collection<String> getApplicableElements() {
    return Arrays.asList(
        SdkConstants.EDIT_TEXT,
        SdkConstants.AUTO_COMPLETE_TEXT_VIEW,
        SdkConstants.MULTI_AUTO_COMPLETE_TEXT_VIEW,
        SdkConstants.TAG_TEXT_INPUT_EDIT_TEXT
    );
}

@Override
public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    String inputType = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_INPUT_TYPE);
    if (inputType.isEmpty()) {
        // missing
        context.report(ISSUE, element, context.getLocation(element), 
            "You should set `android:inputType` on this text field for a better user experience; if the field is intentionally generic, use `inputType=\"text\"`");
        return;
    }
    if ("text".equals(inputType) || inputType.equals("text|")) // exact text suppresses further checks
        return;
    // check id hints
    String id = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_ID);
    String name = stripId(id);
    if (name == null) return;
    name = name.toLowerCase(Locale.ROOT);

    Set<String> types = new HashSet<>();
    for (String t : inputType.split("\\|")) {
        if (!t.isEmpty()) types.add(t.trim().toLowerCase(Locale.ROOT));
    }

    for (Map.Entry<String, String> entry : ID_TO_INPUT_TYPE.entrySet()) {
        if (name.contains(entry.getKey())) {
            String expected = entry.getValue();
            if (!types.contains(expected.toLowerCase(Locale.ROOT))) {
                context.report(ISSUE, element, context.getLocation(element),
                    "id suggests this field is for " + entry.getKey() + ", so `android:inputType` should include `" + expected + "`");
            }
        }
    }
}
```

