package com.android.tools.lint.checks

import com.android.SdkConstants
import com.android.tools.lint.detector.api.*
import org.w3c.dom.Element
import org.w3c.dom.Node

class WearableConfigurationActionDetector : ResourceXmlDetector() {

    override fun appliesTo(context: Context): Boolean {
        // only manifest files
        return context is XmlContext
    }

    override fun getApplicableElements(): Collection<String>? {
        return listOf(SdkConstants.TAG_SERVICE, SdkConstants.TAG_ACTIVITY)
    }

    override fun visitElement(context: XmlContext, element: Element) {
        val rootPackage = context.document.documentElement?.getAttributeNS(ANDROID_URI, ATTR_PACKAGE) ?: return
        when (element.tagName) {
            SdkConstants.TAG_SERVICE -> {
                val metadata = findChildByName(element, SdkConstants.TAG_METADATA) ?: return
                val name = metadata.getAttributeNS(ANDROID_URI, SdkConstants.ATTR_NAME)
                if (name == WEARABLE_CONFIG_ACTION_METADATA) {
                    val value = metadata.getAttributeNS(ANDROID_URI, SdkConstants.ATTR_VALUE)
                    if (value == WATCH_FACE_EDITOR_VALUE) {
                        services.add(ServiceInfo(metadata, element, rootPackage))
                    }
                }
            }
            SdkConstants.TAG_ACTIVITY -> {
                val hasEditor = element.childElements(TAG_INTENT_FILTER).any { filter ->
                    filter.childElements(TAG_ACTION).any { action ->
                        action.getAttributeNS(ANDROID_URI, ATTR_NAME) == WATCH_FACE_EDITOR_ACTION
                    }
                }
                if (hasEditor) {
                    val hasCategory = element.childElements(TAG_INTENT_FILTER).any { filter ->
                        filter.childElements(TAG_CATEGORY).any { category ->
                            category.getAttributeNS(ANDROID_URI, ATTR_NAME) == WEARABLE_CONFIGURATION_CATEGORY
                        }
                    }
                    activities.add(ActivityInfo(element, rootPackage, hasCategory))
                }
            }
        }
