private UCallExpression findDelegationCall(UMethod constructor) {
    final UCallExpression[] result = new UCallExpression[1];
    constructor.accept(new AbstractUastVisitor() {
        @Override public boolean visitCallExpression(UCallExpression node) {
            if (node.isConstructorCall()) {
                String name = node.getMethodName();
                if ("super".equals(name) || "this".equals(name)) {
                    result[0] = node;
                    return true; // stop
                }
            }
            return super.visitCallExpression(node);
        }
    });
    return result[0];
}
