@Override
public void visitClass(@NotNull JavaContext context, @NotNull UClass node) {
    PsiClass psiClass = node.getJavaPsi();
    if (psiClass == null) return;
    if (psiClass instanceof PsiAnonymousClass) return;
    if (psiClass.hasModifierProperty(PsiModifier.STATIC)) return;
    PsiClass containing = psiClass.getContainingClass();
    if (containing == null) return;
    if (context.getDriver().isSuppressed(context, ISSUE, psiClass)) return;

    PsiMethod[] constructors = psiClass.getConstructors();
    if (constructors.length == 0) {
        report(context, node);
        return;
    }

    boolean hasMain = false;
    for (PsiMethod constructor : constructors) {
        PsiCodeBlock body = constructor.getBody();
        if (body == null) {
            // implicit super()
            hasMain = true;
            continue;
        }
        PsiStatement[] statements = body.getStatements();
        if (statements.length == 0) {
            hasMain = true; // implicit super()
            continue;
        }
        PsiStatement first = statements[0];
        if (first instanceof PsiExpressionStatement) {
            PsiExpression expr = ((PsiExpressionStatement) first).getExpression();
            if (expr instanceof PsiMethodCallExpression) {
                PsiMethodCallExpression call = (PsiMethodCallExpression) expr;
                if (call.isConstructorCall()) {
                    String callName = call.getMethodExpression().getReferenceName();
                    if ("super".equals(callName)) {
                        if (isMainLooperCall(call)) {
                            hasMain = true;
                        }
                    }
                    // if this(...) we ignore? Could follow chain, but for now ignore
                }
            }
        } else {
            // not explicit super/this -> implicit super() -> main
            hasMain = true;
        }
    }

    if (hasMain) {
        report(context, node);
    }
}
