@SuppressWarnings("UnstableApiUsage") // maybe?
public class HandlerDetector extends Detector implements Detector.ClassScanner {
    private static final String ANDROID_OS_HANDLER = "android.os.Handler";
    private static final String CLASS_ANDROID_OS_LOOPER = "android.os.Looper";
    private static final String METHOD_GET_MAIN_LOOPER = "getMainLooper";

    private static final Implementation IMPLEMENTATION = new Implementation(
            HandlerDetector.class,
            Scope.JAVA_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "HandlerLeak",
            "Handler reference leaks",
            "Since this Handler is declared as an inner class, it may prevent the " +
                    "outer class from being garbage collected. If the Handler is using a " +
                    "Looper or MessageQueue for a thread other than the main thread, " +
                    "then there is no issue. If the Handler is using the Looper or " +
                    "MessageQueue of the main thread, you need to fix your Handler " +
                    "declaration, as follows: Declare the Handler as a static class; In " +
                    "the outer class, instantiate a WeakReference to the outer class and " +
                    "pass this object to your Handler when you instantiate the Handler; " +
                    "Make all references to members of the outer class using the " +
                    "WeakReference object.",
            Category.PERFORMANCE,
            5,
            Severity.WARNING,
            IMPLEMENTATION);

    @Override
    @Nullable
    public List<String> applicableSuperClasses() {
        return Collections.singletonList(ANDROID_OS_HANDLER);
    }

    @Override
    public void visitClass(@NotNull JavaContext context, @NotNull UClass node) {
        PsiClass psiClass = node.getJavaPsi();
        if (psiClass == null || psiClass instanceof PsiAnonymousClass) {
            return;
        }

        if (psiClass.hasModifierProperty(PsiModifier.STATIC)) {
            return;
        }

        if (psiClass.getContainingClass() == null) {
            return;
        }

        if (context.getDriver().isSuppressed(context, ISSUE, psiClass)) {
            return;
        }

        PsiMethod[] constructors = psiClass.getConstructors();
        if (constructors.length == 0) {
            report(context, psiClass);
            return;
        }

        boolean hasMainThread = false;
        for (PsiMethod constructor : constructors) {
            PsiCodeBlock body = constructor.getBody();
            if (body == null) {
                hasMainThread = true;
                continue;
            }

            PsiStatement[] statements = body.getStatements();
            if (statements.length == 0) {
                hasMainThread = true;
                continue;
            }

            PsiStatement first = statements[0];
            if (first instanceof PsiExpressionStatement) {
                PsiExpression expr = ((PsiExpressionStatement) first).getExpression();
                if (expr instanceof PsiMethodCallExpression) {
                    PsiMethodCallExpression call = (PsiMethodCallExpression) expr;
                    if (call.isConstructorCall()) {
                        String name = call.getMethodExpression().getReferenceName();
                        if ("super".equals(name)) {
                            if (usesMainThreadLooper(call)) {
                                hasMainThread = true;
                                break; // no need to check further
                            }
                        } else if ("this".equals(name)) {
                            // Could chain to another constructor; to keep it simple we
                            // do not follow the chain and conservatively do not flag.
                            // Most cases are covered by direct super calls.
                        } else {
                            // Not an explicit super() or this() call: implicit super() uses current looper
                            hasMainThread = true;
                        }
                    } else {
                        hasMainThread = true;
                    }
                } else {
                    hasMainThread = true;
                }
            } else {
                hasMainThread = true;
            }
        }

        if (hasMainThread) {
            report(context, psiClass);
        }
    }

    private void report(@NotNull JavaContext context, @NotNull PsiClass node) {
        context.report(ISSUE, context.getNameLocation(node),
                "This Handler class should be static or leaks may occur");
    }

    private boolean usesMainThreadLooper(@NotNull PsiMethodCallExpression call) {
        PsiExpression[] args = call.getArgumentList().getExpressions();
        int count = args.length;
        if (count == 0) {
            // Handler() - uses the current thread's Looper (typically the main thread)
            return true;
        }

        PsiExpression firstArg = args[0];
        PsiType firstType = firstArg.getType();
        if (firstType != null && firstType.equalsToText(CLASS_ANDROID_OS_LOOPER)) {
            // Explicit Looper; only a problem if it is the main looper
            return isMainLooper(firstArg);
        }

        // One argument that is not a Looper (e.g., Handler.Callback) or no explicit
        // Looper at all: uses the current thread's Looper.
        return true;
    }

    private boolean isMainLooper(@NotNull PsiExpression expression) {
        if (expression instanceof PsiMethodCallExpression) {
            PsiMethodCallExpression call = (PsiMethodCallExpression) expression;
            PsiReferenceExpression methodExpr = call.getMethodExpression();
            if (METHOD_GET_MAIN_LOOPER.equals(methodExpr.getReferenceName())) {
                PsiExpression qualifier = methodExpr.getQualifierExpression();
                if (qualifier == null) {
                    return true;
                }
                String text = qualifier.getText();
                return CLASS_ANDROID_OS_LOOPER.equals(text)
                        || "Looper".equals(text);
            }
        }
        return false;
    }
}
