private UCallExpression findSuperCall(UMethod method) {
    UExpression body = method.getUastBody();
    if (body == null) return null;
    final UCallExpression[] result = new UCallExpression[1];
    body.accept(new AbstractUastVisitor() {
        @Override
        public boolean visitCallExpression(UCallExpression node) {
            if (node.isConstructor()) {
                PsiMethod resolved = UastUtils.getParentOfType? no.
                PsiMethod resolved = (PsiMethod) node.resolve();
                if (resolved != null && context.getEvaluator().isMemberInClass(resolved, HANDLER_CLS)) {
                    result[0] = node;
                    return true;
                }
            }
            return super.visitCallExpression(node);
        }
    });
    return result[0];
}
```
