public class ParcelDetector extends Detector implements Detector.UastScanner {

    private static final String PARCELABLE = "android.os.Parcelable";
    private static final String CREATOR = "CREATOR";

    private static final Implementation IMPLEMENTATION = new Implementation(
            ParcelDetector.class,
            Scope.JAVA_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "ParcelCreator",
            "Missing Parcelable CREATOR field",
            "According to the `Parcelable` interface documentation, \"Classes implementing the Parcelable interface must also have a static field called `CREATOR`, which is an object implementing the `Parcelable.Creator` interface.\" This field is required for the Android framework to create instances of your class from a `Parcel`.",
            Category.CORRECTNESS,
            5,
            Severity.ERROR,
            IMPLEMENTATION);

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NotNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NotNull UClass node) {
                if (node.isInterface() || node.hasModifierProperty(PsiModifier.ABSTRACT)) {
                    return;
