import static com.android.tools.lint.client.api.JavaParserKt.TYPE_INT;
import com.android.tools.lint.detector.api.*;
import java.util.Collections;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.uast.*;

public class ParcelDetector extends Detector implements SourceCodeScanner {
    private static final String PARCELABLE_CLS = "android.os.Parcelable";
    private static final String CREATOR_CLS = "android.os.Parcelable.Creator";
    private static final String FIELD_NAME = "CREATOR";

    @Override
    public List<Class<? extends UElement>> getApplicableUElementTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUElementHandler(JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(UClass node) {
                checkClass(context, node);
            }
        };
    }

    private void checkClass(JavaContext context, UClass cls) {
        if (cls.isInterface() || cls.getName() == null) return;
        if (!context.getEvaluator().extendsClass(cls, PARCELABLE_CLS, false)) return;
        // search fields
        for (UField field : cls.getFields()) {
            if (FIELD_NAME.equals(field.getName()) && field.isStatic()) {
                PsiType type = field.getType();
                if (type instanceof PsiClassType) {
                    PsiClass resolved = ((PsiClassType) type).resolve();
                    if (resolved != null
                            && "Creator".equals(resolved.getName())
                            && context.getEvaluator().extendsClass(resolved, "android.os.Parcelable.Creator", true)) {
                        return;
                    }
                }
            }
        }
        context.report(ISSUE, cls, context.getNameLocation(cls),
                String.format("The class %1$s does not define a CREATOR field...", cls.getQualifiedName()),
                null);
    }
}
