package com.android.tools.lint.checks

import com.android.SdkConstants.*
import com.android.resources.ResourceFolderType
import com.android.tools.lint.detector.api.*
import org.w3c.dom.Element
import org.w3c.dom.Node

class RestrictionsDetector : ResourceXmlDetector() {

    companion object {
        private val IMPLEMENTATION = Implementation(
            RestrictionsDetector::class.java,
            Scope.RESOURCE_FILE_SCOPE
        )

        @JvmField
        val ISSUE = Issue.create(
            id = "ValidRestrictions",
            briefDescription = "Invalid Restrictions Descriptor",
            explanation = """
                Ensures that an application's restrictions XML file is properly formed.
                Restrictions XML files must define a `<restrictions>` root element containing \
                `<restriction>` elements with valid attributes and values.
            """,
            category = Category.CORRECTNESS,
            priority = 5,
            severity = Severity.ERROR,
            implementation = IMPLEMENTATION
        )

        private const val RESTRICTIONS_TAG = "restrictions"
        private const val RESTRICTION_TAG = "restriction"
        private const val CHOICE_TAG = "choice"
        private const val ATTR_KEY = "key"
        private const val ATTR_TITLE = "title"
        private const val ATTR_TYPE = "restrictionType"
        private const val ATTR_VALUE = "value"
        private const val ATTR_DEFAULT_VALUE = "defaultValue"

        private val VALID_TYPES = listOf(
            "bool", "integer", "float", "string", "choice",
            "multi_select", "bundle", "bundle_array"
        )
    }

    override fun appliesTo(folderType: ResourceFolderType): Boolean {
        return folderType == ResourceFolderType.XML
    }

    override fun getApplicableElements(): Collection<String>? {
        return listOf(RESTRICTIONS_TAG)
    }

    override fun visitElement(context: XmlContext, element: Element) {
        // root <restrictions>
        if (element.parentNode?.nodeType != Node.DOCUMENT_NODE) return
        val restrictionElements = element.children().filter { it.tagName == RESTRICTION_TAG }
        if (restrictionElements.isEmpty()) {
            context.report(ISSUE, element, context.getLocation(element),
                "Restrictions file must contain at least one `<restriction>` element")
        }
        val seenKeys = mutableSetOf<String>()
        restrictionElements.forEach { restriction ->
            checkRestriction(context, restriction, seenKeys)
        }
    }

    private fun checkRestriction(context: XmlContext, restriction: Element, seenKeys: MutableSet<String>) {
        val namespace = restriction.namespaceURI
        // key
        val key = restriction.getAttributeNS(ANDROID_URI, ATTR_KEY).ifBlank { null }
        if (key == null) {
            reportMissing(context, restriction, ATTR_KEY)
        } else if (!seenKeys.add(key)) {
            context.report(ISSUE, restriction, context.getLocation(restriction),
                "Duplicate restriction key `$key`")
        }
        // title
        val title = restriction.getAttributeNS(ANDROID_URI, ATTR_TITLE).ifBlank { null }
        if (title == null) {
            reportMissing(context, restriction, ATTR_TITLE)
        }
        // type
        val type = restriction.getAttributeNS(ANDROID_URI, ATTR_TYPE).ifBlank { null }
        if (type == null) {
            reportMissing(context, restriction, ATTR_TYPE)
        } else if (type !in VALID_TYPES) {
            context.report(ISSUE, restriction, context.getLocation(restriction),
                "Invalid restrictionType `$type`; must be one of ${VALID_TYPES.joinToString()}")
        } else {
            // type-specific validation
            val choices = restriction.children().filter { it.tagName == CHOICE_TAG }.toList()
            if (type == "choice" || type == "multi_select") {
                if (choices.isEmpty()) {
                    context.report(ISSUE, restriction, context.getLocation(restriction),
                        "Restrictions of type `$type` must contain at least one `<choice>` element")
                }
            } else {
                if (choices.isNotEmpty()) {
                    context.report(ISSUE, restriction, context.getLocation(restriction),
                        "`<choice>` elements are only allowed for `choice` or `multi_select` restrictions")
                }
            }
            // default value type
            val defaultValue = restriction.getAttributeNS(ANDROID_URI, ATTR_DEFAULT_VALUE)
            if (defaultValue.isNotBlank()) {
                validateDefaultValue(context, restriction, type, defaultValue)
            }
        }
        // Check nested restrictions for bundle/bundle_array?
        if (type == "bundle") {
            val nested = restriction.children().filter { it.tagName == RESTRICTION_TAG }.toList()
            if (nested.isEmpty()) {
                // not necessarily error? maybe bundle can be empty.
            }
            nested.forEach { checkRestriction(context, it, seenKeys) }
        } else if (type == "bundle_array") {
            val nested = restriction.children().filter { it.tagName == RESTRICTION_TAG }.toList()
            if (nested.size != 1 || nested[0].getAttributeNS(ANDROID_URI, ATTR_TYPE) != "bundle") {
                context.report(ISSUE, restriction, context.getLocation(restriction),
                    "A restriction of type `bundle_array` must contain exactly one nested `bundle` restriction")
            }
            nested.forEach { checkRestriction(context, it, seenKeys) }
        }
    }

    private fun validateDefaultValue(context: XmlContext, restriction: Element, type: String, value: String) {
        when (type) {
            "bool" -> if (value != "true" && value != "false") {
                context.report(ISSUE, restriction, context.getLocation(restriction),
                    "Default value for `bool` restriction must be `true` or `false`")
            }
            "integer" -> value.toIntOrNull() ?: context.report(...)
            "float" -> value.toFloatOrNull() ?: ...
            "choice" -> {
                val choices = restriction.children().filter { it.tagName == CHOICE_TAG }.map {
                    it.getAttributeNS(ANDROID_URI, ATTR_VALUE)
                }.toList()
                if (value !in choices) ...
            }
            "multi_select" -> {
                // defaultValue is string array resource
                if (!value.startsWith("@array/")) ...
            }
            "bundle", "bundle_array" -> {
                // bundle types shouldn't have defaultValue
                context.report(...)
            }
        }
    }

    private fun reportMissing(context, element, attr) {
        context.report(ISSUE, element, context.getLocation(element),
            "Missing required `android:$attr` attribute on `<restriction>`")
    }

    private fun Element.children(): Sequence<Element> = ...
}

