package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.*
import com.android.tools.lint.detector.api.Context
import org.jetbrains.uast.ULiteralExpression
import org.jetbrains.uast.UExpression
import org.w3c.dom.Attr
import org.w3c.dom.Element
import org.w3c.dom.Node

class SecretDetector : Detector(), SourceCodeScanner, XmlScanner, ResourceFolderScanner {

    companion object {
        private val ISSUE = Issue.create(
            id = "SecretInSource",
            briefDescription = "Secret in source code",
            explanation = """
                Including secrets, such as API keys, in source code is a security risk. It is generally best practice to not include API keys in source code, and instead use something like the Secrets Gradle Plugin for Android.
                """,
            category = Category.SECURITY,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(
                SecretDetector::class.java,
                Scope.JAVA_FILE_SCOPE,
                Scope.MANIFEST_SCOPE,
                Scope.RESOURCE_FILE_SCOPE
            )
        )
    }

    override fun getApplicableUastTypes() = listOf(ULiteralExpression::class.java)

    override fun createUastHandler(context: JavaContext): UElementHandler? {
        return object : UElementHandler() {
            override fun visitLiteralExpression(node: ULiteralExpression) {
                val value = node.value
                if (value !is String) return
                if (looksLikeSecret(value)) {
                    context.report(ISSUE, node, context.getLocation(node), "Possible secret in source code; avoid hardcoding secrets.")
                }
            }
        }
    }

    override fun getApplicableElements(): Collection<String>? = listOf("meta-data", "string")

    override fun visitElement(context: XmlContext, element: Element) {
        when (element.tagName) {
            "meta-data" -> {
                val name = element.getAttributeNS(ANDROID_URI, "name")
                if (isSecretName(name)) {
                    val value = element.getAttributeNS(ANDROID_URI, "value")
                    if (value.isNotBlank() && value != "@string/...") {
                        context.report(ISSUE, element, context.getLocation(element), "Possible secret in manifest meta-data; avoid hardcoding secrets.")
                    }
                }
            }
            "string" -> {
                val name = element.getAttribute("name")
                if (isSecretName(name)) {
                    val text = element.textContent?.trim()
                    if (!text.isNullOrBlank()) {
                        context.report(ISSUE, element, context.getLocation(element), "Possible secret in strings resource; avoid hardcoding secrets.")
                    }
                }
            }
        }
    }

    override fun checkResourceFolder(context: ResourceContext, folderName: String, folder: File) {
        // maybe not needed
    }
