class SecretDetector : Detector(), SourceCodeScanner {

    override fun getApplicableUastTypes(): List<Class<out UElement>>? {
        return listOf(ULiteralExpression::class.java)
    }

    override fun createUastHandler(context: JavaContext): UElementHandler? {
        return object : UElementHandler() {
            override fun visitLiteralExpression(node: ULiteralExpression) {
                checkLiteral(context, node)
            }
        }
    }

    private fun checkLiteral(context: JavaContext, node: ULiteralExpression) {
        val value = node.value as? String ?: return
        if (value.isBlank() || value.length < MIN_SECRET_LENGTH) return

        if (looksLikeSecret(value)) {
            reportIssue(context, node)
            return
        }

        val parent = node.uastParent ?: return
        val name = when (parent) {
            is UVariable -> parent.name
            is UCallExpression -> {
                // Try to find which parameter this argument corresponds to.
                val index = parent.valueArguments.indexOf(node)
                if (index >= 0) parent.resolve()?.parameterList?.parameters?.get(index)?.name else null
            }
            else -> null
        }
        if (name != null && SECRET_NAME_PATTERN.matcher(name).matches()) {
            reportIssue(context, node)
        }
    }

    private fun looksLikeSecret(value: String): Boolean {
        return KNOWN_SECRET_PREFIXES.any { value.startsWith(it) }
                || API_KEY_PATTERN.matches(value)
    }

    private fun reportIssue(context: JavaContext, node: ULiteralExpression) {
        context.report(
            ISSUE,
            node,
            context.getLocation(node),
            "Potential secret hardcoded in source code; consider using the Secrets Gradle Plugin instead."
        )
    }

    companion object {
        private const val MIN_SECRET_LENGTH = 12
        private val KNOWN_SECRET_PREFIXES = listOf("AIza", "AKIA", "ASIA", "sk-", "pk_")
        private val API_KEY_PATTERN = Regex("^[A-Za-z0-9_\\-]{20,}$")
        private val SECRET_NAME_PATTERN = Pattern.compile("(?i).*(api[_\\-]?key|secret|token|password|auth).*")

        @JvmField
        val ISSUE: Issue = Issue.create(...)
    }
}
```

