package com.android.tools.lint.checks

import com.android.tools.lint.client.api.UElementHandler
import com.android.tools.lint.detector.api.*
import com.intellij.psi.PsiMethod
import org.jetbrains.uast.*

class SelectedPhotoAccessDetector : Detector(), SourceCodeScanner {

    override fun getApplicableUastNodeTypes() = listOf(UCallExpression::class.java)

    override fun createUastHandler(context: JavaContext): UElementHandler =
        object : UElementHandler() {
            override fun visitCallExpression(node: UCallExpression) {
                val methodName = node.methodName ?: return
                if (methodName !in REQUEST_METHODS) return

                val found = node.valueArguments.any { arg ->
                    arg.containsTargetPermission()
                }
                if (found) {
                    context.report(
                        ISSUE,
                        node,
                        context.getLocation(node),
                        MESSAGE
                    )
                }
            }
        }

    private fun UExpression.containsTargetPermission(): Boolean {
        return when (this) {
            is ULiteralExpression -> {
                ConstantEvaluator.evaluateString(this) in TARGET_PERMISSIONS
            }
            is UCallExpression -> {
                // handle Kotlin vararg or array constructors
                if (methodName in ARRAY_CONSTRUCTORS || this.methodName == "arrayOf") {
                    valueArguments.any { it.containsTargetPermission() }
                } else {
                    ConstantEvaluator.evaluateString(this) in TARGET_PERMISSIONS
                }
            }
            is UPolyadicExpression -> operands.any { it.containsTargetPermission() }
            is UReferenceExpression -> {
                val value = ConstantEvaluator.evaluate(this)
                when (value) {
                    is String -> value in TARGET_PERMISSIONS
                    is Array<*> -> value.any { it is String && it in TARGET_PERMISSIONS }
                    else -> false
                }
            }
            else -> ConstantEvaluator.evaluateString(this) in TARGET_PERMISSIONS
        }
    }

    companion object {
        private val TARGET_PERMISSIONS = setOf(
            "android.permission.READ_MEDIA_IMAGES",
            "android.permission.READ_MEDIA_VIDEO",
            "android.permission.READ_MEDIA_VISUAL_USER_SELECTED"
        )
        private val REQUEST_METHODS = setOf(
            "requestPermissions",
            "requestPermission",
            "registerForActivityResult"
        )
        private val ARRAY_CONSTRUCTORS = setOf("arrayOf", "Array", "emptyArray")

        private const val MESSAGE =
            "On Android 14+, requesting READ_MEDIA_IMAGES or READ_MEDIA_VIDEO triggers " +
            "selected photo access. Consider using the Android Photo Picker or " +
            "handling partial access."

        @JvmField
        val ISSUE = Issue.create(
            id = "SelectedPhotoAccess",
            briefDescription = "Behavior change when requesting photo library access",
            explanation = """
                Starting in Android 14, when an app requests `READ_MEDIA_IMAGES` or
                `READ_MEDIA_VIDEO`, the user can choose to grant access to selected
                photos and videos only. Requesting these permissions will now show a
                runtime dialog that lets the user manage partial access on a
                per-selection basis.

                Instead of relying on the system to manage this selection lifecycle,
                consider using the Android Photo Picker (`ActivityResultContracts.
                PickVisualMedia`), which does not require any storage permissions and
                provides a consistent user experience across Android versions.
                Alternatively, adapt your app to handle partial access by checking
                `READ_MEDIA_VISUAL_USER_SELECTED` and querying the user's selection.
            """,
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.WARNING,
            implementation = Implementation(
                SelectedPhotoAccessDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}
```

