```
private fun UExpression?.containsTargetPermission(): Boolean {
    if (this == null) return false
    return when (this) {
        is ULiteralExpression -> ConstantEvaluator.evaluateString(this) in TARGET_PERMISSIONS
        is UCallExpression -> when {
            methodName == "arrayOf" -> valueArguments.any { it.containsTargetPermission() }
            methodName == "arrayOfNotNull" -> valueArguments.any { it.containsTargetPermission() }
            methodName == "Array" -> valueArguments.any { it.containsTargetPermission() }
            this.kind == UastCallKind.NEW_ARRAY -> valueArguments.any { it.containsTargetPermission() }
            else -> ConstantEvaluator.evaluateString(this) in TARGET_PERMISSIONS
        }
        is UPolyadicExpression -> operands.any { it.containsTargetPermission() }
        is UQualifiedReferenceExpression,
        is USimpleNameReferenceExpression,
        is ULocalVariableReferenceExpression,
        is UFieldReferenceExpression -> {
            ConstantEvaluator.evaluate(this)?.let { value ->
                when (value) {
                    is String -> value in TARGET_PERMISSIONS
                    is Array<*> -> value.filterIsInstance<String>().any { it in TARGET_PERMISSIONS }
                    else -> false
                }
            } ?: false
        }
        else -> ConstantEvaluator.evaluateString(this) in TARGET_PERMISSIONS
    }
}
