package com.android.tools.lint.checks;

import static com.android.SdkConstants.SELECTOR;
import static com.android.SdkConstants.VALUE_ITEM;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.ResourceXmlDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;

public class StateListDetector extends ResourceXmlDetector {

    private static final Implementation IMPLEMENTATION = new Implementation(
            StateListDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "StateListReachable",
            "Unreachable state in a `<selector>`",
            "In a selector, only the last child in the state list should omit a state qualifier. "
                    + "If not, all subsequent items in the list will be ignored since the given "
                    + "item will match all.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            IMPLEMENTATION);

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(SELECTOR);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (!SELECTOR.equals(element.getTagName())) {
            return;
        }

        NodeList children = element.getChildNodes();
        // Find item elements
        List<Element> items = new ArrayList<>();
        for (int i = 0, n = children.getLength(); i < n; i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE && VALUE_ITEM.equals(child.getNodeName())) {
                items.add((Element) child);
            }
        }

        for (int i = 0; i < items.size() - 1; i++) {
            Element item = items.get(i);
            if (!hasStateQualifiers(item)) {
                // This item has no state qualifiers and appears before the last position,
                // so it will match all states and subsequent items are unreachable.
                context.report(ISSUE, item, context.getLocation(item),
                        "This item will match any state, so items after it will never be reached");
            }
        }
    }

    private boolean hasStateQualifiers(@NonNull Element element) {
        NamedNodeMap attributes = element.getAttributes();
        for (int i = 0, n = attributes.getLength(); i < n; i++) {
            Node attr = attributes.item(i);
            String name = attr.getLocalName();
            String prefix = attr.getPrefix();
            if (name != null && name.startsWith(STATE_ATTR_PREFIX)) {
                return true;
            }
        }
        return false;
    }

    private static final String STATE_ATTR_PREFIX = "state_";
}
```

