  public static final Issue ISSUE = Issue.create(
    "StateListReachable",
    "Unreachable state in selector",
    "In a <selector>, only the last item should omit state qualifiers; otherwise subsequent items are unreachable.",
    Category.CORRECTNESS,
    6,
    Severity.WARNING,
    new Implementation(StateListDetector.class, Scope.RESOURCE_FILE_SCOPE)
  );

  @Override public Collection<String> getApplicableElements() { return Arrays.asList("selector"); }

  @Override public void visitElement(XmlContext context, Element element) {
    NodeList children = element.getChildNodes();
    int count = children.getLength();
    // gather item elements
    for (int i = 0; i < count; i++) {
      Node child = children.item(i);
      if (child.getNodeType() != Node.ELEMENT_NODE) continue;
      if (!"item".equals(child.getLocalName())) continue; // or getNodeName maybe "item" no prefix
