public class UnsafeNativeCodeDetector extends Detector implements Detector.UastScanner {
    private static final String SYSTEM_CLASS = "java.lang.System";
    private static final String RUNTIME_CLASS = "java.lang.Runtime";
    private static final String LOAD = "load";
    public static final Issue ISSUE = Issue.create(
        "UnsafeDynamicallyLoadedCode",
        "Dynamically loaded code",
        "Dynamically loading code using `load` ...", // brief
        Category.SECURITY,
        6,
        Severity.WARNING,
        new Implementation(UnsafeNativeCodeDetector.class, Scope.JAVA_FILE_SCOPE));

    @Override
    public List<String> getApplicableMethodNames() { return Arrays.asList(LOAD); }

    @Override
    public void visitMethodCall(@NonNull JavaContext context, @NonNull UCallExpression call, @NonNull PsiMethod method) {
        JavaEvaluator evaluator = context.getEvaluator();
        if (evaluator.isMemberInClass(method, SYSTEM_CLASS) || evaluator.isMemberInClass(method, RUNTIME_CLASS)) {
            context.report(ISSUE, call, context.getLocation(call), "Do not dynamically load code with `load`; use `loadLibrary` instead.");
        }
    }
}

