package com.android.tools.lint.checks;

import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceContext;
import com.android.tools.lint.detector.api.ResourceFolderType;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import java.io.File;
import java.util.EnumSet;

public class UnsafeNativeCodeDetector extends Detector implements Detector.BinaryResourceScanner, Detector.OtherFileScanner {
    private static final String EXTENSION = ".so";
    private static final String MESSAGE = "Native code outside library directory";

    private static final Implementation IMPLEMENTATION =
            new Implementation(UnsafeNativeCodeDetector.class,
                    EnumSet.of(Scope.OTHER, Scope.RESOURCE_FILE));

    public static final Issue ISSUE = Issue.create(
            "UnsafeNativeCodeLocation",
            "Native code outside library directory",
            "In general, application native code should only be placed in the application's library directory, "
                + "not in other locations such as the res or assets directories. Placing the code in the library "
                + "directory provides increased assurance that the code will not be tampered with after "
                + "application installation. Application developers should use the features of their "
                + "development environment to place application native libraries into the lib directory of "
                + "their compiled APKs. Embedding non-shared library native executables into applications "
                + "should be avoided when possible.",
            Category.SECURITY,
            6,
            Severity.WARNING,
            IMPLEMENTATION
    );

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType, @NonNull String fileName) {
        return fileName.endsWith(EXTENSION);
    }

    @Override
    public void checkBinaryResource(@NonNull ResourceContext context) {
        context.report(ISSUE, Location.at(context.file), MESSAGE);
    }

    @Override
    public boolean appliesTo(@NonNull Context context, @NonNull File file) {
        if (!file.getName().endsWith(EXTENSION)) {
            return false;
        }
        String path = file.getPath().replace('\\', '/');
        return path.contains("/assets/") || path.contains("/res/");
    }

    @Override
    public void run(@NonNull Context context) {
        context.report(ISSUE, Location.at(context.file), MESSAGE);
    }
}
```

