private static boolean hasConstructor(UClass cls, JavaContext context, String... expectedTypes) {
 for (UMethod method : cls.getMethods()) {
   if (method.isConstructor()) {
     PsiParameterList list = method.getJavaPsi().getParameterList();
     if (list.getParametersCount() != expectedTypes.length) continue;
     PsiParameter[] params = list.getParameters();
     boolean match = true;
     for (int i=0;i<expectedTypes.length;i++) {
       String type = params[i].getType().getCanonicalText();
       if (!expectedTypes[i].equals(type)) { match=false; break; }
     }
     if (match) return true;
   }
 }
 return false;
}

