        if (declaration.isAbstract()) return;
        if (!context.getEvaluator().extendsClass(declaration, "android.view.View", true)) return;
        boolean hasConstructor = false;
        for (PsiMethod constructor : declaration.getConstructors()) {
            if (matches(constructor, Context.class, AttributeSet.class)) { hasConstructor=true; break; }
        }
        if (!hasConstructor) context.report(...);
    }
}
```

