private static boolean hasMatchingConstructor(UClass cls, String... expectedTypes) {
    for (UMethod method : cls.getMethods()) {
        if (!method.isConstructor()) continue;
        List<UParameter> params = method.getUastParameters();
        if (params.size() != expectedTypes.length) continue;
