@Override
public List<Class<? extends UElement>> getApplicableUObjectTypes() {
    return Collections.singletonList(UClass.class);
}

@Override
public UElementHandler createUastHandler(@NotNull JavaContext context) {
    return new UElementHandler() {
        @Override
        public void visitClass(@NotNull UClass node) {
            if (node.isInterface() || node.isEnum() || node.hasModifierProperty(PsiModifier.ABSTRACT)) return;
            if (!context.getEvaluator().extendsClass(node, "android.view.View", false)) return;
            // skip View itself
            if ("android.view.View".equals(node.getQualifiedName())) return;

            boolean hasOneArg = false, hasTwoArg = false, hasThreeArg = false;
            for (UMethod method : node.getMethods()) {
                if (!method.isConstructor() || !method.isPublic()) continue;
                List<UParameter> params = method.getUastParameters();
                int n = params.size();
                if (n == 1 && isContext(params.get(0))) hasOneArg = true;
                else if (n == 2 && isContext(params.get(0)) && isAttributeSet(params.get(1))) hasTwoArg = true;
                else if (n == 3 && isContext(params.get(0)) && isAttributeSet(params.get(1)) && isInt(params.get(2))) hasThreeArg = true;
            }
            if (!hasOneArg && !hasTwoArg && !hasThreeArg) {
                context.report(ISSUE, node, context.getNameLocation(node), "Missing one of the required constructors for XML inflation");
            }
        }
    };
}
```

