private List<ViewEntry> collectViews(Element root) {
    List<ViewEntry> entries = new ArrayList<>();
    collect(root, entries);
    return entries;
}
private void collect(Element element, List<ViewEntry> entries) {
    String id = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_ID);
    if (id != null && !id.isEmpty()) {
        String name = stripIdPrefix(id);
        if (!name.isEmpty()) entries.add(new ViewEntry(name, element.getTagName()));
    }
    Node child = element.getFirstChild();
    while (child != null) {
        if (child.getNodeType() == Node.ELEMENT_NODE) {
            collect((Element) child, entries);
        }
        child = child.getNextSibling();
    }
}
```
