@Override
public void afterCheckEachProject(@NonNull Context context) {
    for (Map.Entry<String, List<LayoutInfo>> entry : mLayoutInfos.entrySet()) {
        List<LayoutInfo> variants = entry.getValue();
        if (variants.size() < 2) continue;
        Set<String> common = null;
        for (LayoutInfo info : variants) {
            if (common == null) common = new HashSet<>(info.ids);
            else common.retainAll(info.ids);
        }
        if (common == null) continue;
        for (LayoutInfo info : variants) {
            Set<String> missingFromCommon = new HashSet<>(info.ids);
            missingFromCommon.removeAll(common);
            for (String id : missingFromCommon) {
                Location location = info.idLocations.get(id);
                if (location == null) location = info.rootLocation;
                context.report(ISSUE, location,
                    String.format("The view `R.id.%1$s` is not present in all versions of this layout; it appears in `%2$s` but not in all other layout variations.", id, entry.getKey()));
            }
        }
    }
}

