@Override public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
    if (!context.getResourceFolderType().equals(ResourceFolderType.LAYOUT)) return; // though appliesTo ensures
    String value = attribute.getValue();
    String id = getIdName(value);
    if (id == null) return;
    String filename = context.file.getName();
    LayoutInfo info = getInfo(filename, context);
    Node node = attribute.getOwnerElement();
    String tag = node.getNodeName();
    info.ids.add(id);
    info.idToTag.put(id, tag);
    info.idToNode.put(id, node);
}
```

