private LayoutInfo getInfo(String filename, XmlContext context) {
    List<LayoutInfo> list = mLayouts.computeIfAbsent(filename, k -> new ArrayList<>());
    for (LayoutInfo info : list) {
        if (info.file.equals(context.file)) return info;
    }
    LayoutInfo info = new LayoutInfo(context.file, context);
    list.add(info);
    return info;
}
