```
@Override public void afterCheckProject(@NonNull Context context) {
    for (Map.Entry<String, List<LayoutInfo>> entry : mLayouts.entrySet()) {
        List<LayoutInfo> infos = entry.getValue();
        if (infos.size() < 2) continue;
        // Build union of ids and canonical tag for each id ( majority? )
        Map<String, String> idToCommonTag = new HashMap<>();
        for (LayoutInfo info : infos) {
            for (Map.Entry<String, String> e : info.idToTag.entrySet()) {
                idToCommonTag.put(e.getKey(), e.getValue()); // last one; could check consistency
            }
        }
        // For each file, find ids in any other file but not here, and ids here but not in others.
        for (LayoutInfo info : infos) {
            Set<String> others = new HashSet<>();
            for (LayoutInfo other : infos) {
                if (other != info) others.addAll(other.ids);
            }
            Set<String> missing = new HashSet<>(others);
            missing.removeAll(info.ids);
            Set<String> extra = new HashSet<>(info.ids);
            extra.removeAll(others);
            // type mismatches: ids present in both with different tag
            List<String> typeMismatches = new ArrayList<>();
            for (String id : info.ids) {
                if (others.contains(id)) {
                    for (LayoutInfo other : infos) {
                        if (other != info && other.ids.contains(id)) {
                            String tag1 = info.idToTag.get(id);
                            String tag2 = other.idToTag.get(id);
                            if (tag1 != null && tag2 != null && !tag1.equals(tag2)) {
                                typeMismatches.add(id + " (" + tag1 + " vs " + tag2 + ")");
                                break;
                            }
                        }
                    }
                }
            }
            if (missing.isEmpty() && extra.isEmpty() && typeMismatches.isEmpty()) continue;
            // Build aggregated message
            StringBuilder sb = new StringBuilder();
            sb.append("The layout \"").append(entry.getKey()).append("\" has inconsistencies across configurations:");
            if (!missing.isEmpty()) { sb.append("\nMissing in this configuration: ").append(missing); }
            if (!extra.isEmpty()) { sb.append("\nOnly present in this configuration: ").append(extra); }
            if (!typeMismatches.isEmpty()) { sb.append("\nInconsistent view types: ").append(typeMismatches); }
            Location location = context.getRangeLocation? We need use info.context.getLocation(root). Use info.context.getLocation(info.context.document.getDocumentElement()).
            info.context.report(ISSUE, location, sb.toString());
        }
    }
}
```

